"""Physical calculation modules shared by figure-generation scripts.

Style is centralized in the project-root preamble.py. All model dependencies
are embedded here for an independently reproducible, compact release.
"""
import sys, types
from pathlib import Path
import numpy as np
import matplotlib as mpl
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path: sys.path.insert(0,str(ROOT))
from preamble import *
from preamble import _norm_fs, _install_typography_guard

def _install_module(name, source, filename):
    mod = types.ModuleType(name)
    mod.__file__ = str(filename)
    mod.__package__ = name.rpartition(".")[0]
    sys.modules[name] = mod
    exec(compile(source, str(filename), "exec"), mod.__dict__)
    return mod

_models_pkg = types.ModuleType("models")
_models_pkg.__path__ = []
sys.modules["models"] = _models_pkg

# ---- embedded models.pinem_core ----
_install_module('models.pinem_core', 'import numpy as np\nfrom scipy.special import jv, iv, spherical_jn, spherical_yn\nfrom scipy.constants import c,hbar,e,m_e,epsilon_0\n\nEV=e\n\ndef electron_relativistic(ke_eV):\n    K=ke_eV*e\n    mc2=m_e*c*c\n    gamma=1+K/mc2\n    beta=np.sqrt(1-1/gamma**2)\n    v=beta*c\n    p=gamma*m_e*v\n    return dict(gamma=gamma,beta=beta,v=v,p=p,E=gamma*mc2)\n\ndef pinem_g_from_field(z,Ez,omega,v):\n    z=np.asarray(z); Ez=np.asarray(Ez)\n    return e/(2*hbar*omega)*np.trapz(Ez*np.exp(-1j*omega*z/v),z)\n\ndef evanescent_field(z,E0=1.0,L=50e-9,phase=0.0,asym=0.0):\n    z=np.asarray(z)\n    env=np.exp(-np.abs(z)/L)\n    return E0*env*np.exp(1j*(phase+asym*np.tanh(z/L)))\n\ndef bessel_populations(g,nmax=20):\n    n=np.arange(-nmax,nmax+1)\n    p=jv(n,2*np.abs(g))**2\n    p/=p.sum()\n    return n,p\n\ndef coherent_gain_fraction(g,nmax=80):\n    n,p=bessel_populations(g,nmax)\n    return p[n>0].sum()\n\ndef incoherent_populations(mu,nmax=30):\n    n=np.arange(-nmax,nmax+1)\n    p=np.exp(-mu)*iv(np.abs(n),mu)\n    p/=p.sum()\n    return n,p\n\ndef temporal_bessel_population(delays_fs,n,g0,sigma_e_fs,sigma_p_fs):\n    delays=np.asarray(delays_fs,dtype=float)\n    # Gaussian electron-light cross correlation; field-envelope width enters amplitude.\n    sig=np.sqrt(sigma_e_fs**2+sigma_p_fs**2)\n    g=g0*np.exp(-(delays**2)/(4*sig**2))\n    return jv(abs(int(n)),2*np.abs(g))**2\n\ndef gaussian_blur1d(y,sigma_pts):\n    if sigma_pts<=0: return np.asarray(y)\n    r=max(2,int(4*sigma_pts))\n    x=np.arange(-r,r+1)\n    k=np.exp(-x*x/(2*sigma_pts*sigma_pts)); k/=k.sum()\n    return np.convolve(y,k,mode=\'same\')\n\ndef drude_eps(omega,wp,gamma=0,eps_inf=1.0):\n    omega=np.asarray(omega,dtype=complex)\n    return eps_inf-wp**2/(omega*(omega+1j*gamma))\n\ndef sphere_polarizability(radius,eps,eps_m=1.0):\n    return 4*np.pi*epsilon_0*eps_m*radius**3*(eps-eps_m)/(eps+2*eps_m)\n\ndef rayleigh_efficiencies(radius,omega,eps,eps_m=1.0):\n    k=np.sqrt(eps_m)*omega/c\n    a=sphere_polarizability(radius,eps,eps_m)\n    csca=k**4*np.abs(a)**2/(6*np.pi*(epsilon_0*eps_m)**2)\n    cext=k*np.imag(a)/(epsilon_0*eps_m)\n    cabs=np.maximum(np.real(cext-csca),0)\n    geo=np.pi*radius**2\n    return csca/geo,cabs/geo\n\n\ndef mie_efficiencies_sphere(radius, omega, eps, eps_m=1.0, nmax=None):\n    """Exact Mie efficiencies for a homogeneous nonmagnetic sphere.\n\n    Parameters follow the standard Bohren-Huffman convention with host\n    permittivity eps_m and relative refractive index m=sqrt(eps/eps_m).\n    Returns Q_sca, Q_abs, Q_ext.\n    """\n    radius=float(radius); omega=float(np.real(omega))\n    k=np.sqrt(eps_m)*omega/c\n    x=max(k*radius,1e-12)\n    mr=np.sqrt(complex(eps)/eps_m)\n    if nmax is None:\n        nmax=max(1,int(np.ceil(x+4*x**(1/3)+2)))\n    n=np.arange(1,nmax+1)\n    mx=mr*x\n    jx=spherical_jn(n,x); jxp=spherical_jn(n,x,derivative=True)\n    yx=spherical_yn(n,x); yxp=spherical_yn(n,x,derivative=True)\n    h=jx+1j*yx; hp=jxp+1j*yxp\n    jmx=spherical_jn(n,mx); jmxp=spherical_jn(n,mx,derivative=True)\n    # Riccati-Bessel functions and derivatives.\n    psi_x=x*jx; dpsi_x=jx+x*jxp\n    psi_mx=mx*jmx; dpsi_mx=jmx+mx*jmxp\n    xi_x=x*h; dxi_x=h+x*hp\n    an=(mr*psi_mx*dpsi_x-psi_x*dpsi_mx)/(mr*psi_mx*dxi_x-xi_x*dpsi_mx)\n    bn=(psi_mx*dpsi_x-mr*psi_x*dpsi_mx)/(psi_mx*dxi_x-mr*xi_x*dpsi_mx)\n    fac=(2*n+1)\n    qsca=(2/x**2)*np.sum(fac*(np.abs(an)**2+np.abs(bn)**2))\n    qext=(2/x**2)*np.sum(fac*np.real(an+bn))\n    qabs=max(float(np.real(qext-qsca)),0.0)\n    return float(np.real(qsca)), qabs, float(np.real(qext))\n\ndef dipole_nearfield_Ez(z,b,p=1.0):\n    z=np.asarray(z,dtype=float); r2=b*b+z*z; r=np.sqrt(r2)\n    # electrostatic dipole p along z, proportional form\n    return p*(3*z*z/r2-1)/np.maximum(r,1e-30)**3\n\ndef impact_coupling(b,L=55e-9,g_surface=5.0,b0=50e-9):\n    b=np.asarray(b,float)\n    return g_surface*np.exp(-(np.maximum(b,b0)-b0)/L)\n\ndef fluence_to_g(F,F0=1.0,g_at_F0=4.7):\n    return g_at_F0*np.sqrt(np.maximum(F,0)/F0)\n\ndef coherent_spectrum(energies_eV,photon_eV,g,sigma_eV=0.35,nmax=35):\n    y=np.zeros_like(energies_eV,dtype=float)\n    n,p=bessel_populations(g,nmax)\n    for ni,pi in zip(n,p):\n        y += pi*np.exp(-(energies_eV-ni*photon_eV)**2/(2*sigma_eV**2))\n    return y/(np.max(y)+1e-30)\n\ndef spp_dispersion(k,wp,eps_d=1.0,eps_inf=1.0):\n    # lossless metal; solve analytic quadratic for omega^2 from k^2=(w/c)^2 epsm epsd/(epsm+epsd)\n    k=np.asarray(k,float)\n    q=(c*k)**2\n    # epsm=eps_inf-wp^2/x. derive quadratic: eps_inf*eps_d*x^2 - [eps_d*wp^2 + q(eps_inf+eps_d)]x + q*wp^2 = 0\n    A=eps_inf*eps_d\n    B=-(eps_d*wp**2 + q*(eps_inf+eps_d))\n    C=q*wp**2\n    disc=np.maximum(B*B-4*A*C,0)\n    x1=(-B-np.sqrt(disc))/(2*A)\n    x2=(-B+np.sqrt(disc))/(2*A)\n    # lower physical branch tending ck/sqrt(eps_d) at k->0 and surface plasmon at high k\n    x=np.minimum(x1,x2)\n    x=np.maximum(x,0)\n    return np.sqrt(x)\n\ndef field_decay_length_cylinder(photon_wavelength, electron_ke_eV):\n    rel=electron_relativistic(electron_ke_eV)\n    omega=2*np.pi*c/photon_wavelength\n    kz=omega/rel[\'v\']\n    k0=omega/c\n    kappa=np.sqrt(np.maximum(kz*kz-k0*k0,1e-60))\n    return 1/kappa\n\ndef dirac_spinor_components(ke_eV):\n    K=np.asarray(ke_eV,float)*e\n    E=K+m_e*c*c\n    p=np.sqrt(np.maximum(E*E-(m_e*c*c)**2,0))/c\n    u1=np.sqrt((E+m_e*c*c)/(2*E))\n    u2=np.sqrt((E-m_e*c*c)/(2*E))\n    return p,u1,u2\n\ndef poisson_fisher_sidebands(g,nmax=20):\n    n=np.arange(-nmax,nmax+1)\n    p=jv(n,2*g)**2\n    # derivative numerically\n    dg=1e-4*max(1,abs(g))\n    pp=jv(n,2*(g+dg))**2; pm=jv(n,2*(g-dg))**2\n    dp=(pp-pm)/(2*dg)\n    return np.sum(dp*dp/np.maximum(p,1e-15))\n', Path(__file__).parent/'models'/'pinem_core.py')

