_install_module('models.baum2016', 'import numpy as np\n\ndef longitudinal_lens(t_fs, sigma_t_fs=900, chirp_per_fs=0.0025, drift=1.0):\n    t=np.asarray(t_fs,float)\n    dE=chirp_per_fs*t\n    tf=(1-drift*chirp_per_fs)*t\n    return dE,tf\n\ndef compressed_width(sigma0_fs, kappa, drift):\n    return abs(1-kappa*drift)*sigma0_fs\n\ndef streak_map(t_fs,slope_mm_per_fs=0.004,offset=0.0):\n    return offset+slope_mm_per_fs*np.asarray(t_fs,float)\n', Path(__file__).parent/'models'/'baum2016.py')

# ---- embedded models.cai2018 ----
_install_module('models.cai2018', 'import numpy as np\nfrom scipy.special import jv\nfrom scipy.integrate import simpson\n\n# Cai et al. PRB 98, 045424 (2018), Eqs. (2)-(8), dimensionless R in lambda_p/(2pi)\ndef eta_from_Omega(g,Omega):\n    return 2*g*Omega/(1+Omega**2)\n\ndef real_channel(rho,ell,m,eta):\n    # rho = k_p R = 2pi R/lambda_p; Eq. (5)\n    return (1j**ell)*jv(ell,2*eta*jv(m,rho))\n\ndef gaussian_amplitude(rho,fwhm=30.0):\n    # paper quotes FWHM diameter 30 lambda_p/(2pi), so in rho units FWHM=30\n    return np.exp(-2*np.log(2)*(rho/fwhm)**2)\n\ndef image_wave(rho,phi,ell,m,eta,fwhm=30.0):\n    return gaussian_amplitude(rho,fwhm)*real_channel(rho,ell,m,eta)*np.exp(1j*ell*m*phi)\n\ndef far_radial(Q,ell,m,eta,fwhm=30.0,rmax=70.0,nr=5000):\n    # Eq. (7), Q is dimensionless Q/k_p; integral over rho\n    rho=np.linspace(0,rmax,nr)\n    base=rho*gaussian_amplitude(rho,fwhm)*jv(ell,2*eta*jv(m,rho))\n    out=np.empty_like(np.atleast_1d(Q),dtype=complex)\n    order=abs(ell*m)\n    for i,q in enumerate(np.atleast_1d(Q)):\n        out[i]=simpson(base*jv(order,q*rho),x=rho)\n    return out\n\ndef channel_probability_vs_offset(offset,ell,m,eta,fwhm=30.0,rmax=80,nr=900,nphi=512):\n    # faithful transverse integral of |phi0(R-R0) f_l(R)|^2\n    r=np.linspace(0,rmax,nr); ph=np.linspace(0,2*np.pi,nphi,endpoint=False)\n    R,PH=np.meshgrid(r,ph,indexing=\'ij\')\n    f2=np.abs(real_channel(R,ell,m,eta))**2\n    vals=[]\n    for d in np.atleast_1d(offset):\n        rr2=R**2+d**2-2*R*d*np.cos(PH)\n        g2=np.exp(-4*np.log(2)*rr2/fwhm**2)\n        vals.append(np.trapz(np.trapz(f2*g2*R,ph,axis=1),r))\n    vals=np.array(vals)\n    return vals/vals[0] if vals[0]!=0 else vals\n\ndef currents(eta_vals,fwhm_vals,ell,m,lambda_ratio=1.2e-3,rmax=100,nr=1800):\n    # Eq. (8), longitudinal fraction and azimuthal/longitudinal ratio.\n    rho=np.linspace(1e-5,rmax,nr)\n    outz=np.zeros((len(fwhm_vals),len(eta_vals)))\n    outr=np.zeros_like(outz)\n    for i,w in enumerate(fwhm_vals):\n        g2=np.exp(-4*np.log(2)*(rho/w)**2)\n        norm=np.trapz(g2*rho,rho)\n        for j,eta in enumerate(eta_vals):\n            f2=np.abs(jv(ell,2*eta*jv(m,rho)))**2\n            z=np.trapz(f2*g2*rho,rho)/norm\n            # local j_phi/j_z = ell*m/(k0 R)=ell*m*lambda_e/(2pi R_phys)\n            # rho=k_p R=2pi R/lambda_p -> ratio=ell*m*(lambda_e/lambda_p)/rho\n            ph=np.trapz(f2*g2*rho*(ell*m*lambda_ratio/np.maximum(rho,1e-9)),rho)/norm\n            outz[i,j]=z\n            outr[i,j]=ph/max(z,1e-15)\n    return outz,outr\n\ndef radial_probability_contribution(rho,ell,m,eta,fwhm=30.0):\n    """Fig. 4 quantity |phi_0(R) f_ell(R)|^2 normalized to incident on-axis intensity."""\n    rho=np.asarray(rho,float)\n    env=np.exp(-4*np.log(2)*(rho/fwhm)**2)\n    return env*np.abs(jv(int(ell),2*float(eta)*jv(int(m),rho)))**2\n\ndef radial_envelope(rho,fwhm=30.0):\n    rho=np.asarray(rho,float)\n    return np.exp(-4*np.log(2)*(rho/fwhm)**2)\n', Path(__file__).parent/'models'/'cai2018.py')

# ---- embedded models.feist2015 ----
_install_module('models.feist2015', 'import numpy as np\nfrom scipy.special import jv\n\ndef sideband_coefficients(g,nmax=30,phase=0.0):\n    n=np.arange(-nmax,nmax+1)\n    c=(1j**n)*jv(n,2*g)*np.exp(1j*n*phase)\n    return n,c\n\ndef energy_map(g_values,nmax=14):\n    n=np.arange(-nmax,nmax+1)\n    P=np.array([jv(n,2*g)**2 for g in g_values]).T\n    return n,P\n\ndef free_evolution_density(g,tau,dispersion=0.035,nmax=24,nt=900):\n    # optical phase coordinate theta in [0,2pi); quadratic spectral phase creates attosecond bunching\n    n,c=sideband_coefficients(g,nmax)\n    theta=np.linspace(-np.pi,np.pi,nt)\n    psi=np.zeros_like(theta,dtype=complex)\n    for ni,ci in zip(n,c):\n        psi += ci*np.exp(-1j*ni*theta)*np.exp(-1j*dispersion*tau*ni*ni)\n    rho=np.abs(psi)**2\n    rho/=np.trapz(rho,theta)\n    return theta,rho\n\ndef wigner_periodic(g,tau,dispersion=0.035,nmax=18,ntheta=240):\n    n,c=sideband_coefficients(g,nmax)\n    c=c*np.exp(-1j*dispersion*tau*n*n)\n    theta=np.linspace(-np.pi,np.pi,ntheta)\n    W=np.zeros((len(n),len(theta)),float)\n    # discrete-cylinder Wigner proxy: interference at mean energy index\n    for ia,na in enumerate(n):\n        for ib,nb in enumerate(n):\n            m=(na+nb)/2\n            if abs(m-round(m))<1e-9:\n                im=np.where(n==int(round(m)))[0]\n                if im.size:\n                    W[im[0]] += np.real(c[ia]*np.conj(c[ib])*np.exp(-1j*(na-nb)*theta))\n    if np.max(np.abs(W))>0: W/=np.max(np.abs(W))\n    return theta,n,W\n', Path(__file__).parent/'models'/'feist2015.py')

# ---- embedded models.li2026 ----
_install_module('models.li2026', "import numpy as np\nfrom scipy.special import jv\n\n# Li et al. PRR 8, 033355 (2026), Eqs. (1)-(8)\ndef coeff(n1,n2,b1,b2,phi1=0.0,phi2=0.0):\n    return jv(n1,2*abs(b1))*jv(n2,2*abs(b2))*np.exp(1j*(n1*phi1+n2*phi2))\n\ndef joint_distribution(b1,b2,l1=-1,l2=-1,nmax=18,phi1=0,phi2=0):\n    out={}\n    for n1 in range(-nmax,nmax+1):\n        for n2 in range(-nmax,nmax+1):\n            c=coeff(n1,n2,b1,b2,phi1,phi2)\n            N=n1+2*n2; ell=l1*n1+l2*n2\n            out[(N,ell)] = out.get((N,ell),0j)+c\n    P={k:abs(v)**2 for k,v in out.items()}\n    z=sum(P.values())\n    return {k:v/z for k,v in P.items()}\n\ndef collapsed_energy(b1,b2,nmax=18):\n    amp={}\n    for n1 in range(-nmax,nmax+1):\n        for n2 in range(-nmax,nmax+1):\n            N=n1+2*n2\n            amp[N]=amp.get(N,0j)+coeff(n1,n2,b1,b2)\n    p={N:abs(a)**2 for N,a in amp.items()}; z=sum(p.values())\n    return {N:v/z for N,v in p.items()}\n\ndef dispersion(KN,Kl,b1,b2,l1=-1,l2=-1,phi1=0,phi2=0):\n    return -2*abs(b1)*np.sin(KN+l1*Kl+phi1)-2*abs(b2)*np.sin(2*KN+l2*Kl+phi2)\n\ndef dos(b1,b2,l1=-1,l2=-1,n=900,bins=500):\n    k=np.linspace(-np.pi,np.pi,n,endpoint=False)\n    KN,KL=np.meshgrid(k,k,indexing='xy')\n    e=dispersion(KN,KL,b1,b2,l1,l2).ravel()\n    h,edges=np.histogram(e,bins=bins,density=True)\n    return .5*(edges[:-1]+edges[1:]),h\n\ndef mode_entropy(b1,b2,l1,l2,nmax=20):\n    P=joint_distribution(b1,b2,l1,l2,nmax)\n    Ns=sorted(set(k[0] for k in P)); Ls=sorted(set(k[1] for k in P))\n    ni={v:i for i,v in enumerate(Ns)}; li={v:i for i,v in enumerate(Ls)}\n    C=np.zeros((len(Ns),len(Ls)),complex)\n    # reconstruct coherent amplitudes directly, not sqrt(P)\n    for n1 in range(-nmax,nmax+1):\n        for n2 in range(-nmax,nmax+1):\n            N=n1+2*n2; ell=l1*n1+l2*n2\n            C[ni[N],li[ell]] += coeff(n1,n2,b1,b2)\n    C/=np.linalg.norm(C)\n    s=np.linalg.svd(C,compute_uv=False)**2\n    s=s[s>1e-14]\n    return float(-(s*np.log2(s)).sum()),s\n", Path(__file__).parent/'models'/'li2026.py')

# ---- embedded models.tavabi2025 ----
_install_module('models.tavabi2025', 'import numpy as np\nfrom scipy.special import jv\n\n\ndef uncertainty_sigma_l(sigma_x_nm=0.32, sigma_probe_nm=0.25):\n    """Tavabi et al. Eq. (3) lower bound in units of hbar."""\n    return 0.5*np.sqrt(1.0 + (sigma_probe_nm/sigma_x_nm)**2)\n\n\ndef offaxis_oam_profile(ell, m=1, y_nm=0.0, sigma_x_nm=0.32, sigma_probe_nm=0.25,\n                        sorter_sigma_l=0.42, qmax_nm_inv=40.0, nq=1800):\n    """OAM broadening from translation of a cylindrical inelastic channel.\n\n    A transition channel centered on an atom displaced by R from the sorter\n    axis acquires exp(-i q.R). The Jacobi-Anger expansion distributes an\n    intrinsic azimuthal order m over sorter orders l with amplitudes\n    J_{l-m}(qR). We integrate those channel weights over a Gaussian transverse\n    momentum envelope set by the probe and inelastic delocalization scales,\n    then convolve with the finite OAM-sorter point-spread function.\n    """\n    ell=np.asarray(ell,float)\n    q=np.linspace(0.0,qmax_nm_inv,nq)\n    # A compact momentum envelope: probe and transition localization add in\n    # quadrature in real space, hence suppress large q.\n    sigma_eff=np.sqrt(sigma_x_nm**2+sigma_probe_nm**2)\n    W=q*np.exp(-0.5*(q*sigma_eff)**2)\n    R=abs(float(y_nm))\n    lmin=int(np.floor(ell.min()))-8; lmax=int(np.ceil(ell.max()))+8\n    lint=np.arange(lmin,lmax+1)\n    weights=[]\n    for l in lint:\n        amp=jv(abs(l-m),q*R)\n        weights.append(np.trapz(W*amp*amp,q))\n    weights=np.asarray(weights)\n    if weights.sum()>0: weights/=weights.sum()\n    # Measurement sorter turns discrete l channels into continuous peaks.\n    sig=max(float(sorter_sigma_l),0.08)\n    out=np.zeros_like(ell)\n    for l,w in zip(lint,weights):\n        out += w*np.exp(-0.5*((ell-l)/sig)**2)\n    # Enforce the uncertainty floor by a gentle extra convolution when needed.\n    floor=uncertainty_sigma_l(sigma_x_nm,sigma_probe_nm)\n    if floor>sig:\n        extra=np.sqrt(max(floor**2-sig**2,0))\n        dl=float(np.mean(np.diff(ell)))\n        r=max(2,int(np.ceil(4*extra/max(dl,1e-6))))\n        x=np.arange(-r,r+1)*dl\n        ker=np.exp(-0.5*(x/extra)**2); ker/=ker.sum()\n        out=np.convolve(out,ker,mode=\'same\')\n    return out/(np.sum(out)+1e-30)\n\n\ndef gamma_profile(ell,m,offsets_nm,weights=None,**kw):\n    offsets_nm=np.asarray(offsets_nm,float)\n    if weights is None: weights=np.ones_like(offsets_nm)\n    weights=np.asarray(weights,float); weights/=weights.sum()+1e-30\n    out=np.zeros_like(np.asarray(ell,float))\n    for y,w in zip(offsets_nm,weights):\n        out += w*offaxis_oam_profile(ell,m,y,**kw)\n    return out/(out.sum()+1e-30)\n\n\ndef fit_spectrum(E,ell,components):\n    out=np.zeros((len(ell),len(E)))\n    for s,g in components:\n        out += np.outer(g,s)\n    return out\n', Path(__file__).parent/'models'/'tavabi2025.py')

# ---- embedded models.wu2026 ----
_install_module('models.wu2026', 'import numpy as np\nfrom scipy.special import jv, k1\nfrom scipy.linalg import expm, eig\nfrom scipy.constants import c,hbar,m_e,e,epsilon_0,pi\n\n# Faithful reconstruction from PRL 137, 063601 (2026): Eq. (1), second-order S matrix, Eq. (4).\n# Electron autocorrelation is evaluated analytically from Eq. (1), avoiding the unspecified D_l shorthand in Eq. (3).\n\nV0=0.5*c\nGAMMA0=1/np.sqrt(1-(V0/c)**2)\nSIGMA_Q=1e6\nOMEGA_PINEM=1.5e15\nLS=0.100\nTREP=0.5e-9\nB=1e-9\nD31=2.16*3.33564e-30\nD32=2.03*3.33564e-30\nPURE=np.array([0.95e3,1.0e3,2.0e6])\n\ndef config(idx=1):\n    if idx==1: return 3.0e15,2.9e15\n    return 3.0e15,1.5e15\n\ndef G_transverse(omega,dipole):\n    u=abs(omega/V0); x=u*B/GAMMA0\n    return e*dipole*u*k1(x)/(2*pi*epsilon_0*hbar*V0*GAMMA0)\n\ndef electron_autocorr(u,gm,Lp,phi_g=0.0,sigma_q=SIGMA_Q,omega=OMEGA_PINEM,Ls=LS):\n    # Analytic Gaussian integral of Eq. (1), normalized by I(0).\n    a=omega/V0\n    g=float(abs(gm))\n    nmax=max(12,int(np.ceil(2*g+10)))\n    n=np.arange(-nmax,nmax+1)\n    J=jv(n,2*g)\n    D=hbar/(2*GAMMA0**3*m_e*V0)\n    nn,mm=np.meshgrid(n,n,indexing=\'ij\')\n    Jnm=J[:,None]*J[None,:]*np.exp(1j*(nn-mm)*phi_g)\n    def raw(uu):\n        c1=nn*a-uu; c2=mm*a\n        mu=(c1+c2)/2\n        delta=c1-c2\n        A=2*D*(uu*Lp+(uu+(mm-nn)*a)*Ls)\n        Bph=uu*Lp+D*uu**2*Lp+(uu+(mm-nn)*a)*Ls + D*((uu-nn*a)**2-(mm*a)**2)*Ls\n        integ=np.exp(-(delta**2)/(8*sigma_q**2))*np.exp(-0.5*sigma_q**2*A**2)*np.exp(-1j*(A*mu+Bph))\n        return np.sum(Jnm*integ)\n    z=raw(0.0)\n    return raw(u)/z\n\ndef transition_data(cfg=1):\n    w31,w32=config(cfg)\n    w=np.zeros((3,3));\n    w[2,0]=w31; w[0,2]=-w31; w[2,1]=w32; w[1,2]=-w32\n    G=np.zeros((3,3),complex)\n    g31=G_transverse(w31,D31); g32=G_transverse(w32,D32)\n    G[2,0]=G[0,2]=g31; G[2,1]=G[1,2]=g32\n    return w,G\n\ndef scattering_terms(cfg=1):\n    w,G=transition_data(cfg)\n    allowed=[(2,0),(0,2),(2,1),(1,2)]\n    terms=[(0.0,np.eye(3,dtype=complex))]\n    # first order\n    for i,j in allowed:\n        A=np.zeros((3,3),complex); A[i,j]=-1j*G[i,j]\n        terms.append((w[i,j]/V0,A))\n    # second order all allowed chained pairs (i,k)(k,j)\n    for i,k in allowed:\n        for k2,j in allowed:\n            if k2!=k: continue\n            A=np.zeros((3,3),complex); A[i,j] += -0.5*G[i,k]*G[k,j]\n            terms.append(((w[i,k]+w[k,j])/V0,A))\n    # merge equal shifts/operators by matrix sum at same shift only\n    merged={}\n    for s,A in terms:\n        key=round(s,6)\n        merged[key]=merged.get(key,0)+A\n    return [(float(k),A) for k,A in merged.items()]\n\ndef scatter_superop(gm,Lp,cfg=1):\n    terms=scattering_terms(cfg)\n    S=np.zeros((9,9),complex)\n    cache={}\n    for sa,Aa in terms:\n      for sb,Ab in terms:\n        d=sa-sb\n        key=round(d,3)\n        if key not in cache: cache[key]=electron_autocorr(d,gm,Lp)\n        corr=cache[key]\n        # vec(A rho B^dagger)=(B* kron A)vec(rho)\n        S += corr*np.kron(Ab.conj(),Aa)\n    return S\n\ndef lindblad_superop(cfg=1):\n    w31,w32=config(cfg)\n    Gamma31=w31**3*D31**2/(3*pi*epsilon_0*hbar*c**3)\n    Gamma32=w32**3*D32**2/(3*pi*epsilon_0*hbar*c**3)\n    jumps=[]\n    J=np.zeros((3,3),complex); J[0,2]=np.sqrt(Gamma31); jumps.append(J)\n    J=np.zeros((3,3),complex); J[1,2]=np.sqrt(Gamma32); jumps.append(J)\n    for j,g in enumerate(PURE):\n        J=np.zeros((3,3),complex); J[j,j]=np.sqrt(2*g); jumps.append(J)\n    L=np.zeros((9,9),complex); I=np.eye(3)\n    # phase-matched train: coherent H0 phase over each full period is an integer multiple of 2pi, so omit stroboscopic commutator.\n    for J in jumps:\n        JJ=J.conj().T@J\n        L += np.kron(J.conj(),J)-0.5*np.kron(I,JJ)-0.5*np.kron(JJ.T,I)\n    return L, Gamma31, Gamma32\n\ndef one_period_map(gm,Lp,cfg=1):\n    Sc=scatter_superop(gm,Lp,cfg)\n    L,_,_=lindblad_superop(cfg)\n    return expm(L*TREP)@Sc\n\ndef steady_state(gm,Lp,cfg=1):\n    F=one_period_map(gm,Lp,cfg)\n    vals,vecs=eig(F)\n    idx=np.argmin(abs(vals-1))\n    rho=vecs[:,idx].reshape((3,3),order=\'F\')\n    rho=(rho+rho.conj().T)/2\n    rho/=np.trace(rho)\n    # numerical projection of tiny negative eigenvalues caused by perturbative truncation\n    lam,U=np.linalg.eigh(rho); lam=np.clip(lam,0,None); rho=(U*lam)@U.conj().T; rho/=np.trace(rho)\n    return rho\n\ndef coherence(rho,i,j):\n    den=np.sqrt(max(rho[i,i].real*rho[j,j].real,1e-30))\n    return min(1.0,abs(rho[i,j])/den)\n\ndef iterate(gm,Lp,cfg=1,nsteps=1000,rho0=None):\n    F=one_period_map(gm,Lp,cfg)\n    if rho0 is None:\n        rho0=np.zeros((3,3),complex); rho0[0,0]=1\n    v=rho0.reshape(9,order=\'F\')\n    arr=np.empty((nsteps+1,3,3),complex); arr[0]=rho0\n    for k in range(1,nsteps+1):\n        v=F@v\n        rho=v.reshape((3,3),order=\'F\'); rho=(rho+rho.conj().T)/2; rho/=np.trace(rho)\n        arr[k]=rho; v=rho.reshape(9,order=\'F\')\n    return arr\n\n\ndef iterate_at(gm,Lp,times_s,cfg=1,rho0=None):\n    F=one_period_map(gm,Lp,cfg)\n    if rho0 is None:\n        rho0=np.zeros((3,3),complex); rho0[0,0]=1\n    v0=rho0.reshape(9,order=\'F\')\n    vals,V=np.linalg.eig(F); Vinv=np.linalg.inv(V); c0=Vinv@v0\n    out=[]\n    for t in np.asarray(times_s):\n        n=int(round(t/TREP)); v=V@((vals**n)*c0); rho=v.reshape((3,3),order=\'F\'); rho=(rho+rho.conj().T)/2; rho/=np.trace(rho); out.append(rho)\n    return np.array(out)\n\ndef electron_autocorr_grid(u,gm,Lps,phi_g=0.0,sigma_q=SIGMA_Q,omega=OMEGA_PINEM,Ls=LS):\n    Lps=np.asarray(Lps,float)\n    a=omega/V0; g=float(abs(gm)); nmax=max(12,int(np.ceil(2*g+10)))\n    n=np.arange(-nmax,nmax+1); J=jv(n,2*g); D=hbar/(2*GAMMA0**3*m_e*V0)\n    nn,mm=np.meshgrid(n,n,indexing=\'ij\'); nn=nn.ravel()[:,None]; mm=mm.ravel()[:,None]\n    Jnm=(J[:,None]*J[None,:]*np.exp(1j*(np.subtract.outer(n,n))*phi_g)).ravel()[:,None]\n    def raw(uu):\n        c1=nn*a-uu; c2=mm*a; mu=(c1+c2)/2; delta=c1-c2\n        A=2*D*(uu*Lps[None,:]+(uu+(mm-nn)*a)*Ls)\n        Bph=uu*Lps[None,:]+D*uu**2*Lps[None,:]+(uu+(mm-nn)*a)*Ls + D*((uu-nn*a)**2-(mm*a)**2)*Ls\n        integ=np.exp(-(delta**2)/(8*sigma_q**2))*np.exp(-0.5*sigma_q**2*A**2)*np.exp(-1j*(A*mu+Bph))\n        return np.sum(Jnm*integ,axis=0)\n    return raw(u)/raw(0.0)\n\ndef scan_steady_state(gs,Lps,cfg=1):\n    gs=np.asarray(gs,float); Lps=np.asarray(Lps,float); terms=scattering_terms(cfg)\n    diffs=sorted(set(round(sa-sb,3) for sa,_ in terms for sb,_ in terms))\n    Lsuper,_,_=lindblad_superop(cfg); Dmap=expm(Lsuper*TREP)\n    p1=np.zeros((len(Lps),len(gs))); p2=np.zeros_like(p1); mu=np.zeros_like(p1)\n    for j,g in enumerate(gs):\n        corr={d:electron_autocorr_grid(d,g,Lps) for d in diffs}\n        for i,Lp in enumerate(Lps):\n            Sc=np.zeros((9,9),complex)\n            for sa,Aa in terms:\n                for sb,Ab in terms:\n                    Sc += corr[round(sa-sb,3)][i]*np.kron(Ab.conj(),Aa)\n            F=Dmap@Sc\n            vals,vecs=np.linalg.eig(F); kk=np.argmin(abs(vals-1)); rho=vecs[:,kk].reshape((3,3),order=\'F\')\n            rho=(rho+rho.conj().T)/2; rho/=np.trace(rho)\n            lam,U=np.linalg.eigh(rho); lam=np.clip(lam,0,None); rho=(U*lam)@U.conj().T; rho/=np.trace(rho)\n            p1[i,j]=rho[0,0].real; p2[i,j]=rho[1,1].real; mu[i,j]=coherence(rho,0,1)\n    return p1,p2,mu\n\n# --- Direct Eq. (1) evaluator used to validate the analytic Eq. (2) autocorrelation ---\ndef electron_wavefunction_q(q,gm,Lp,phi_g=0.0,sigma_q=SIGMA_Q,omega=OMEGA_PINEM,Ls=LS):\n    """Longitudinal shaped-electron wavefunction from paper Eq. (1).\n\n    A q-independent normalization/global phase is intentionally omitted; callers that need\n    normalized observables normalize numerically.  The paraxial dispersion phase keeps the\n    linear and quadratic q terms of E(q) given immediately before Eq. (1).\n    """\n    q=np.asarray(q,float)\n    a=omega/V0\n    g=float(abs(gm))\n    nmax=max(12,int(np.ceil(2*g+10)))\n    n=np.arange(-nmax,nmax+1)\n    J=jv(n,2*g)\n    D=hbar/(2*GAMMA0**3*m_e*V0)\n    # Final free drift phase outside the sideband sum.\n    outer=np.exp(-1j*(q*Lp + D*q*q*Lp))\n    qq=q[:,None]-n[None,:]*a\n    env=np.exp(-(qq*qq)/(4*sigma_q*sigma_q))\n    pre=np.exp(1j*n*phi_g)\n    phase=np.exp(-1j*(qq*Ls + D*qq*qq*Ls))\n    return outer*np.sum(J[None,:]*pre[None,:]*env*phase,axis=1)\n\n\ndef electron_autocorr_direct(u,gm,Lp,phi_g=0.0,sigma_q=SIGMA_Q,omega=OMEGA_PINEM,Ls=LS,\n                              points_per_sigma=14.0,margin_sigma=7.0):\n    """Numerical Eq. (2) using Eq. (1), normalized so I(0)=1.\n\n    The q grid spans every materially occupied PINEM sideband plus a Gaussian tail margin.\n    Linear interpolation evaluates psi(q+u), avoiding any analytic assumptions about D_l.\n    """\n    a=omega/V0; g=float(abs(gm)); nmax=max(12,int(np.ceil(2*g+10)))\n    qlo=-nmax*a-margin_sigma*sigma_q-min(0.0,float(u))\n    qhi= nmax*a+margin_sigma*sigma_q-max(0.0,float(u))\n    dq=sigma_q/float(points_per_sigma)\n    nq=max(2001,int(np.ceil((qhi-qlo)/dq))+1)\n    q=np.linspace(qlo,qhi,nq)\n    psi=electron_wavefunction_q(q,gm,Lp,phi_g,sigma_q,omega,Ls)\n    # Compute shifted wavefunction from Eq. (1) directly (no interpolation phase artefacts).\n    psis=electron_wavefunction_q(q+float(u),gm,Lp,phi_g,sigma_q,omega,Ls)\n    den=np.trapz(abs(psi)**2,q)\n    return np.trapz(psis*np.conj(psi),q)/den\n\n\ndef validate_autocorr(gm=2.0,Lp=0.0111,cfg=1):\n    """Return analytic/direct Eq.(2) comparisons at both bound-electron transitions."""\n    w31,w32=config(cfg)\n    out={}\n    for name,u in [(\'u31\',w31/V0),(\'u32\',w32/V0),(\'difference\',(w31-w32)/V0)]:\n        a=electron_autocorr(u,gm,Lp)\n        d=electron_autocorr_direct(u,gm,Lp)\n        out[name]={\'analytic\':a,\'direct\':d,\'abs_error\':abs(a-d),\'rel_error\':abs(a-d)/max(abs(d),1e-15)}\n    return out\n', Path(__file__).parent/'models'/'wu2026.py')

# ---- embedded models.novel_extensions ----
_install_module('models.novel_extensions', 'import numpy as np\nfrom scipy.linalg import eigh, eig\nfrom scipy.special import jv\nfrom scipy.optimize import differential_evolution\nfrom scipy.ndimage import gaussian_filter\n\nfrom .li2026 import dispersion, joint_distribution, coeff\n\n\ndef harper_strip(ky, alpha=1/3, jx=1.0, jy=1.0, nx=31, loss=0.0, nonreciprocal=0.0):\n    """Harper-Hofstadter strip H(ky) in Landau gauge.\n\n    alpha is synthetic flux per plaquette. nonreciprocal introduces Hatano-Nelson\n    asymmetry along x; loss may be scalar or nx-array on-site loss.\n    """\n    m=np.arange(nx)\n    onsite=2*jy*np.cos(ky+2*np.pi*alpha*m)\n    if np.ndim(loss)==0:\n        onsite=onsite-1j*float(loss)\n    else:\n        onsite=onsite-1j*np.asarray(loss,float)\n    H=np.diag(onsite.astype(complex))\n    for i in range(nx-1):\n        H[i,i+1]=jx*np.exp(+nonreciprocal)\n        H[i+1,i]=jx*np.exp(-nonreciprocal)\n    return H\n\n\ndef hofstadter_spectrum(alpha=1/3,jx=1,jy=1,nx=31,nk=181):\n    kys=np.linspace(-np.pi,np.pi,nk)\n    evals=np.empty((nk,nx)); edge=np.empty_like(evals)\n    x=np.arange(nx); edge_w=np.exp(-x/3)+np.exp(-(nx-1-x)/3)\n    for ik,k in enumerate(kys):\n        E,V=eigh(harper_strip(k,alpha,jx,jy,nx))\n        evals[ik]=E\n        edge[ik]=np.sum((np.abs(V)**2)*edge_w[:,None],axis=0)\n    return kys,evals,edge\n\n\ndef chern_fukui_q3(alpha=1/3,jx=1,jy=1,nk=35):\n    """Fukui Chern numbers of magnetic Bloch Hamiltonian for alpha=p/q, q=3 here."""\n    q=3\n    kxs=np.linspace(-np.pi/q,np.pi/q,nk,endpoint=False)\n    kys=np.linspace(-np.pi,np.pi,nk,endpoint=False)\n    vec=np.empty((nk,nk,q,q),complex)\n    energies=np.empty((nk,nk,q))\n    for ix,kx in enumerate(kxs):\n      for iy,ky in enumerate(kys):\n        H=np.zeros((q,q),complex)\n        for m in range(q):\n            H[m,m]=2*jy*np.cos(ky+2*np.pi*alpha*m)\n            H[m,(m+1)%q]+=jx\n            H[(m+1)%q,m]+=jx\n        # boundary phase in magnetic unit cell\n        H[q-1,0]=jx*np.exp(1j*kx*q); H[0,q-1]=jx*np.exp(-1j*kx*q)\n        E,V=eigh(H); energies[ix,iy]=E; vec[ix,iy]=V\n    ch=[]; curv=[]\n    for b in range(q):\n        F=np.zeros((nk,nk))\n        for ix in range(nk):\n          for iy in range(nk):\n            u=vec[ix,iy,:,b]; ux=vec[(ix+1)%nk,iy,:,b]; uy=vec[ix,(iy+1)%nk,:,b]\n            uxy=vec[(ix+1)%nk,(iy+1)%nk,:,b]\n            Ux=np.vdot(u,ux); Ux/=abs(Ux)\n            Uy=np.vdot(u,uy); Uy/=abs(Uy)\n            Uyx=np.vdot(uy,uxy); Uyx/=abs(Uyx)\n            Uxy=np.vdot(ux,uxy); Uxy/=abs(Uxy)\n            F[ix,iy]=np.angle(Ux*Uxy/(Uyx*Uy))\n        ch.append(F.sum()/(2*np.pi)); curv.append(F)\n    return kxs,energies,np.array(ch),np.array(curv)\n\n\ndef lifshitz_quench(b1=1.0,b2=3.0,l1=-1,l2=-1,nk=160,times=None,sigma_k=0.55):\n    """Quench of a synthetic-site-localized/Gaussian packet into Li et al. dispersion."""\n    if times is None: times=np.linspace(0,8,241)\n    k=np.linspace(-np.pi,np.pi,nk,endpoint=False)\n    KN,KL=np.meshgrid(k,k,indexing=\'ij\')\n    E=dispersion(KN,KL,b1,b2,l1,l2)\n    # broad Gaussian around k=0 mimics a compact synthetic-space wavepacket\n    w=np.exp(-(KN**2+KL**2)/(2*sigma_k**2)); w/=w.sum()\n    G=np.array([np.sum(w*np.exp(-1j*E*t)) for t in times])\n    rate=-np.log(np.maximum(np.abs(G)**2,1e-14))\n    # real-space spreading from initial delta (uniform k) under the same band\n    snaps=[]\n    for t in [0.0,0.7,1.5,3.0]:\n        psi=np.fft.fftshift(np.fft.ifft2(np.exp(-1j*E*t)))\n        p=np.abs(psi)**2; p/=p.sum(); snaps.append(p)\n    return k,E,np.asarray(times),G,rate,np.array(snaps)\n\n\ndef synthetic_lattice_hamiltonian(nmax=6,lmax=6,j1=1.0,j2=1.0,l1=-1,l2=-1,phi1=0,phi2=0,disorder=0,seed=1):\n    sites=[(N,L) for N in range(-nmax,nmax+1) for L in range(-lmax,lmax+1)]\n    idx={s:i for i,s in enumerate(sites)}; H=np.zeros((len(sites),len(sites)),complex)\n    rng=np.random.default_rng(seed)\n    if disorder>0: H[np.diag_indices(len(sites))]=rng.uniform(-disorder/2,disorder/2,len(sites))\n    hops=[((1,l1),j1*np.exp(1j*phi1)),((2,l2),j2*np.exp(1j*phi2))]\n    for s,i in idx.items():\n      for (dN,dL),J in hops:\n        t=(s[0]+dN,s[1]+dL)\n        if t in idx:\n            j=idx[t]; H[j,i]+=J; H[i,j]+=np.conj(J)\n    return sites,H\n\n\ndef disorder_robustness(ws=np.linspace(0,8,25),nreal=10,nmax=5,lmax=5,j1=1,j2=1,seed=0):\n    rng=np.random.default_rng(seed); ipr=[]; gap=[]\n    for W in ws:\n        a=[]; b=[]\n        for r in range(nreal):\n            sites,H=synthetic_lattice_hamiltonian(nmax,lmax,j1,j2,disorder=W,seed=int(rng.integers(1e9)))\n            E,V=eigh(H)\n            mid=np.argsort(np.abs(E))[:max(4,len(E)//10)]\n            a.append(np.mean(np.sum(np.abs(V[:,mid])**4,axis=0)))\n            Es=np.sort(E); b.append(np.mean(np.diff(Es[len(Es)//2-3:len(Es)//2+4])))\n        ipr.append(np.mean(a)); gap.append(np.mean(b))\n    return np.asarray(ws),np.asarray(ipr),np.asarray(gap)\n\n\ndef twocolor_coefficients(g1,g2,phi=0,nmax=28):\n    """Energy coefficients for coherent omega+2omega PINEM."""\n    n=np.arange(-2*nmax,2*nmax+1)\n    A=np.zeros(len(n),complex); ni={v:i for i,v in enumerate(n)}\n    for n1 in range(-nmax,nmax+1):\n      for n2 in range(-nmax,nmax+1):\n        N=n1+2*n2\n        if N in ni:\n            A[ni[N]]+=(1j**(n1+n2))*jv(n1,2*g1)*jv(n2,2*g2)*np.exp(1j*n2*phi)\n    A/=np.linalg.norm(A)\n    return n,A\n\n\ndef periodic_wigner_from_coeff(n,A,ntheta=360):\n    theta=np.linspace(-np.pi,np.pi,ntheta)\n    nmin,nmax=int(n.min()),int(n.max()); W=np.zeros((len(n),ntheta))\n    lut={int(v):i for i,v in enumerate(n)}\n    for ia,na in enumerate(n):\n      for ib,nb in enumerate(n):\n        s=na+nb\n        if s%2==0 and s//2 in lut:\n            W[lut[int(s//2)]] += np.real(A[ia]*np.conj(A[ib])*np.exp(-1j*(na-nb)*theta))\n    W/=np.max(np.abs(W))+1e-15\n    psi=np.sum(A[:,None]*np.exp(-1j*n[:,None]*theta),axis=0)\n    I=np.abs(psi)**2; I/=np.trapz(I,theta)\n    return theta,W,I\n\n\ndef measured_joint_distribution(b1,b2,l1=-1,l2=-1,sigma_n=0.8,sigma_l=0.8,counts=None,seed=0,nmax=16,phi2=0):\n    P=joint_distribution(b1,b2,l1,l2,nmax=nmax,phi2=phi2)\n    Ns=np.arange(min(k[0] for k in P),max(k[0] for k in P)+1)\n    Ls=np.arange(min(k[1] for k in P),max(k[1] for k in P)+1)\n    M=np.zeros((len(Ls),len(Ns)))\n    n0=Ns[0]; l0=Ls[0]\n    for (N,L),v in P.items(): M[L-l0,N-n0]=v\n    B=gaussian_filter(M,sigma=(sigma_l,sigma_n),mode=\'constant\'); B/=B.sum()\n    if counts:\n        rng=np.random.default_rng(seed); C=rng.poisson(counts*B); B=C/max(C.sum(),1)\n    return Ns,Ls,M,B\n\n\ndef mutual_information(P):\n    P=np.asarray(P,float); P=P/(P.sum()+1e-30)\n    px=P.sum(axis=0,keepdims=True); py=P.sum(axis=1,keepdims=True)\n    Q=px*py; mask=P>0\n    return float(np.sum(P[mask]*np.log2(P[mask]/Q[mask])))\n\n\ndef phase_fisher(b1,b2,l1=-1,l2=-1,sigma_n=0,sigma_l=0,phase=-np.pi/2,nmax=14):\n    d=1e-3\n    _,_,_,P0=measured_joint_distribution(b1,b2,l1,l2,sigma_n,sigma_l,nmax=nmax,phi2=phase)\n    _,_,_,Pp=measured_joint_distribution(b1,b2,l1,l2,sigma_n,sigma_l,nmax=nmax,phi2=phase+d)\n    _,_,_,Pm=measured_joint_distribution(b1,b2,l1,l2,sigma_n,sigma_l,nmax=nmax,phi2=phase-d)\n    dp=(Pp-Pm)/(2*d)\n    return float(np.sum(dp*dp/np.maximum(P0,1e-14)))\n\n\ndef inverse_design(target_sites,l1=-1,l2=-1,bounds=((0,4),(0,4),(-np.pi,np.pi)),nmax=12,seed=3,maxiter=80):\n    # target_sites dict {(N,L):prob}\n    keys=list(target_sites); tv=np.array([target_sites[k] for k in keys],float); tv/=tv.sum()\n    def objective(x):\n        b1,b2,phi=x; P=joint_distribution(b1,b2,l1,l2,nmax=nmax,phi2=phi)\n        pv=np.array([P.get(k,0) for k in keys]);\n        # reward target fidelity, penalize leakage\n        overlap=np.sum(np.sqrt(np.maximum(pv,0)*tv))**2\n        captured=pv.sum()\n        return 1-(0.72*overlap+0.28*captured)\n    res=differential_evolution(objective,bounds,seed=seed,maxiter=maxiter,popsize=10,tol=2e-4,polish=True,workers=1)\n    return res.x,1-res.fun\n\n\ndef nonhermitian_strip_spectrum(gamma=0.7,eta=0.28,alpha=1/3,nx=40,nk=121):\n    kys=np.linspace(-np.pi,np.pi,nk); vals=[]; centers=[]\n    loss=gamma*(np.arange(nx)/(nx-1))\n    x=np.arange(nx)\n    for ky in kys:\n        H=harper_strip(ky,alpha=alpha,nx=nx,loss=loss,nonreciprocal=eta)\n        E,V=eig(H); order=np.argsort(E.real); E=E[order]; V=V[:,order]\n        norm=np.sum(abs(V)**2,axis=0); c=np.sum(x[:,None]*abs(V)**2,axis=0)/norm\n        vals.append(E); centers.append(c)\n    return kys,np.array(vals),np.array(centers)\n\n# --- v14: open-system, quantum-geometry, catastrophe and inference extensions ---\ndef energy_ladder_hamiltonian(nmax=12, g=1.8, phase=0.0, detuning=0.0):\n    """Finite PINEM energy-ladder tight-binding Hamiltonian in photon-order basis."""\n    n=np.arange(-nmax,nmax+1)\n    H=np.diag(detuning*n.astype(float)).astype(complex)\n    J=g*np.exp(1j*phase)\n    for i in range(len(n)-1):\n        H[i+1,i]=J; H[i,i+1]=np.conj(J)\n    return n,H\n\n\ndef lindblad_superoperator(H, dephasing=0.0, relaxation=0.0):\n    """Liouvillian for energy-basis dephasing plus nearest-step energy relaxation."""\n    d=H.shape[0]; I=np.eye(d)\n    L=-1j*(np.kron(I,H)-np.kron(H.T,I))\n    cops=[]\n    if dephasing>0:\n        n=np.arange(d)-(d-1)/2\n        cops.append(np.sqrt(dephasing)*np.diag(n/np.max(np.abs(n))))\n    if relaxation>0:\n        C=np.zeros((d,d),complex)\n        for i in range(1,d): C[i-1,i]=1.0\n        cops.append(np.sqrt(relaxation)*C)\n    for C in cops:\n        CdC=C.conj().T@C\n        L += np.kron(C.conj(),C)-0.5*np.kron(I,CdC)-0.5*np.kron(CdC.T,I)\n    return L\n\n\ndef open_system_ladder_dynamics(g=1.8,nmax=10,dephasing=0.15,relaxation=0.03,times=None,compute_gap=False):\n    from scipy.sparse.linalg import expm_multiply\n    if times is None: times=np.linspace(0,8,161)\n    times=np.asarray(times,float)\n    n,H=energy_ladder_hamiltonian(nmax,g)\n    L=lindblad_superoperator(H,dephasing,relaxation)\n    d=len(n); rho0=np.zeros((d,d),complex); rho0[nmax,nmax]=1\n    v0=rho0.reshape(-1,order=\'F\')\n    if len(times)>1 and np.allclose(times,np.linspace(times[0],times[-1],len(times))):\n        VV=expm_multiply(L,v0,start=times[0],stop=times[-1],num=len(times),endpoint=True)\n    else:\n        from scipy.linalg import expm\n        VV=np.array([expm(L*t)@v0 for t in times])\n    pops=[]; purity=[]; coherence=[]\n    for vv in VV:\n        rho=vv.reshape((d,d),order=\'F\'); rho=(rho+rho.conj().T)/2; rho/=np.trace(rho)\n        pops.append(np.real(np.diag(rho)))\n        purity.append(np.real(np.trace(rho@rho)))\n        coherence.append(np.sum(np.abs(rho-np.diag(np.diag(rho))))/(d-1))\n    if compute_gap:\n        ev=np.linalg.eigvals(L)\n        idx=np.argsort(-ev.real)\n        gap=max(0.0,-ev[idx[1]].real)\n    else:\n        gap=np.nan  # explicitly omitted unless compute_gap=True\n    return n,times,np.asarray(pops),np.asarray(purity),np.asarray(coherence),gap\n\ndef liouvillian_gap_scan(g=1.8,nmax=6,dephasings=None,relaxation=0.03):\n    if dephasings is None: dephasings=np.linspace(0,1.5,80)\n    n,H=energy_ladder_hamiltonian(nmax,g)\n    gaps=[]\n    for gam in dephasings:\n        ev=np.linalg.eigvals(lindblad_superoperator(H,gam,relaxation))\n        s=np.sort(ev.real)[::-1]\n        gaps.append(max(0,-s[1]))\n    return np.asarray(dephasings),np.asarray(gaps)\n\n\ndef qwz_geometry(m=-1.0,nk=101):\n    """Berry curvature, quantum metric trace, and Wilson loop of the lower QWZ band."""\n    k=np.linspace(-np.pi,np.pi,nk,endpoint=False)\n    dk=2*np.pi/nk\n    vec=np.empty((nk,nk,2),complex); curv=np.zeros((nk,nk)); gtr=np.zeros_like(curv)\n    for ix,kx in enumerate(k):\n      for iy,ky in enumerate(k):\n        d=np.array([np.sin(kx),np.sin(ky),m+np.cos(kx)+np.cos(ky)])\n        H=d[0]*np.array([[0,1],[1,0]],complex)+d[1]*np.array([[0,-1j],[1j,0]])+d[2]*np.array([[1,0],[0,-1]],complex)\n        E,V=eigh(H); vec[ix,iy]=V[:,0]\n    # gauge-invariant plaquette curvature and FS metric from overlaps\n    for ix in range(nk):\n      for iy in range(nk):\n        u=vec[ix,iy]; ux=vec[(ix+1)%nk,iy]; uy=vec[ix,(iy+1)%nk]\n        uxy=vec[(ix+1)%nk,(iy+1)%nk]\n        Ux=np.vdot(u,ux); Uy=np.vdot(u,uy); Uxy=np.vdot(ux,uxy); Uyx=np.vdot(uy,uxy)\n        curv[ix,iy]=np.angle((Ux/abs(Ux))*(Uxy/abs(Uxy))/((Uyx/abs(Uyx))*(Uy/abs(Uy))))/(dk*dk)\n        gxx=(1-abs(Ux)**2)/(dk*dk); gyy=(1-abs(Uy)**2)/(dk*dk)\n        gtr[ix,iy]=gxx+gyy\n    # Wilson loop along kx for each ky\n    wil=[]\n    for iy in range(nk):\n        z=1+0j\n        for ix in range(nk):\n            ov=np.vdot(vec[ix,iy],vec[(ix+1)%nk,iy]); z*=ov/abs(ov)\n        wil.append(np.angle(z)/(2*np.pi))\n    wil=np.unwrap(np.array(wil)*2*np.pi)/(2*np.pi)\n    return k,curv,gtr,wil\n\n\ndef geometry_mass_scan(ms=np.linspace(-3,3,121),nk=41):\n    ch=[]; vol=[]\n    for m in ms:\n        k,F,gtr,W=qwz_geometry(m,nk)\n        dk=2*np.pi/nk\n        ch.append(F.sum()*dk*dk/(2*np.pi))\n        vol.append(gtr.sum()*dk*dk/(2*np.pi)**2)\n    return np.asarray(ms),np.asarray(ch),np.asarray(vol)\n\n\ndef threecolor_coefficients(g1,g2,g3,phi2=0.0,phi3=0.0,nmax=18):\n    """Coherent omega+2omega+3omega PINEM amplitudes A_N using harmonic convolutions."""\n    ns=np.arange(-nmax,nmax+1)\n    a1=(1j**ns)*jv(ns,2*g1)\n    a2=(1j**ns)*jv(ns,2*g2)*np.exp(1j*ns*phi2)\n    a3=(1j**ns)*jv(ns,2*g3)*np.exp(1j*ns*phi3)\n    Nmax=6*nmax\n    arr1=np.zeros(2*Nmax+1,complex); arr2=np.zeros_like(arr1); arr3=np.zeros_like(arr1)\n    off=Nmax\n    for n,a in zip(ns,a1): arr1[off+n]=a\n    for n,a in zip(ns,a2): arr2[off+2*n]=a\n    for n,a in zip(ns,a3): arr3[off+3*n]=a\n    conv=np.convolve(np.convolve(arr1,arr2),arr3)\n    # convolution index has offset 3*Nmax\n    Nc=np.arange(len(conv))-3*Nmax\n    mask=(Nc>=-3*nmax)&(Nc<=3*nmax)\n    A=conv[mask]; Nvals=Nc[mask]\n    A/=np.linalg.norm(A)\n    return Nvals,A\n\ndef temporal_intensity_from_coeff(n,A,nt=720,zeta=0.035):\n    """Temporal density after free propagation with quadratic spectral phase zeta*n^2.\n\n    zeta is the dimensionless dispersion phase accumulated by adjacent PINEM sidebands.\n    At zeta=0 a pure phase modulation has uniform temporal density, as required.\n    """\n    theta=np.linspace(-np.pi,np.pi,nt,endpoint=False)\n    prop=np.exp(-1j*zeta*n*n)\n    psi=np.sum((A*prop)[:,None]*np.exp(-1j*n[:,None]*theta),axis=0)\n    I=np.abs(psi)**2; I/=I.max()+1e-15\n    return theta,I\n\n\ndef caustic_control_map(g1=2.0,g2=1.2,g3=0.7,nphi=61):\n    ph=np.linspace(-np.pi,np.pi,nphi)\n    peak=np.zeros((nphi,nphi)); width=np.zeros_like(peak)\n    for i,p2 in enumerate(ph):\n      for j,p3 in enumerate(ph):\n        n,A=threecolor_coefficients(g1,g2,g3,p2,p3,nmax=11)\n        th,I=temporal_intensity_from_coeff(n,A,nt=240)\n        peak[i,j]=I.max()\n        # circular participation width in phase bins\n        q=I/(I.sum()+1e-15); width[i,j]=1/np.sum(q*q)\n    return ph,peak,width\n\n\ndef sideband_prob(g,nmax=16):\n    n=np.arange(-nmax,nmax+1); p=jv(n,2*g)**2; p/=p.sum(); return n,p\n\n\ndef poisson_loglike_counts(counts,p):\n    p=np.maximum(p,1e-15); return np.sum(counts*np.log(p))\n\n\ndef bayesian_g_posterior(true_g=2.1,counts_total=3000,ggrid=None,nmax=16,seed=5):\n    if ggrid is None: ggrid=np.linspace(0.3,4.5,360)\n    n,p=sideband_prob(true_g,nmax); rng=np.random.default_rng(seed); counts=rng.multinomial(counts_total,p)\n    ll=[]\n    for g in ggrid:\n        _,pg=sideband_prob(g,nmax); ll.append(poisson_loglike_counts(counts,pg))\n    ll=np.array(ll); post=np.exp(ll-ll.max()); post/=np.trapz(post,ggrid)\n    mean=np.trapz(ggrid*post,ggrid); sd=np.sqrt(np.trapz((ggrid-mean)**2*post,ggrid))\n    return n,counts,np.asarray(ggrid),post,mean,sd\n\n\ndef fisher_g_scan(gs=np.linspace(0.2,5,220),nmax=18,background=2e-4):\n    """Classical FI with a small detector/background floor to regularize exact Bessel zeros."""\n    Fs=[]; dg=2e-4\n    for g in gs:\n        _,p=sideband_prob(g,nmax); _,pp=sideband_prob(g+dg,nmax); _,pm=sideband_prob(g-dg,nmax)\n        p=(p+background); p/=p.sum(); pp=(pp+background); pp/=pp.sum(); pm=(pm+background); pm/=pm.sum()\n        dp=(pp-pm)/(2*dg); Fs.append(np.sum(dp*dp/p))\n    return np.asarray(gs),np.asarray(Fs)\n\n\ndef adaptive_bayes_sequence(true_g=2.1,shots=(50,100,300,1000,3000),seed=7):\n    ggrid=np.linspace(0.3,4.5,320); n,p=sideband_prob(true_g,16); rng=np.random.default_rng(seed)\n    out=[]; prior=np.ones_like(ggrid); prior/=np.trapz(prior,ggrid)\n    cum=np.zeros_like(p,dtype=int)\n    prev=0\n    for total in shots:\n        add=total-prev; prev=total; cum+=rng.multinomial(add,p)\n        ll=np.array([poisson_loglike_counts(cum,sideband_prob(g,16)[1]) for g in ggrid])\n        post=prior*np.exp(ll-ll.max()); post/=np.trapz(post,ggrid)\n        mu=np.trapz(ggrid*post,ggrid); sd=np.sqrt(np.trapz((ggrid-mu)**2*post,ggrid))\n        out.append((total,mu,sd,post.copy()))\n    return ggrid,out\n\n# --- v15: stochastic trajectories, Floquet resonances, flux defects and uncertainty propagation ---\ndef quantum_jump_ensemble(g=1.7,nmax=7,dephasing=0.12,relaxation=0.045,tmax=6.0,dt=0.03,ntraj=180,seed=7):\n    """Monte-Carlo wave-function unraveling of the finite PINEM energy ladder.\n\n    Returns ensemble populations, single-trajectory final photon-order samples,\n    total jump counts, and a small set of representative trajectories.\n    """\n    from scipy.linalg import expm\n    rng=np.random.default_rng(seed)\n    n,H=energy_ladder_hamiltonian(nmax,g)\n    d=len(n); nn=n.astype(float); scale=max(np.max(np.abs(nn)),1)\n    cops=[]\n    if dephasing>0: cops.append(np.sqrt(dephasing)*np.diag(nn/scale))\n    if relaxation>0:\n        C=np.zeros((d,d),complex)\n        for i in range(1,d): C[i-1,i]=1.0\n        cops.append(np.sqrt(relaxation)*C)\n    R=sum((C.conj().T@C for C in cops),np.zeros((d,d),complex))\n    Heff=H-0.5j*R\n    Ueff=expm(-1j*Heff*dt)\n    steps=int(round(tmax/dt)); times=np.linspace(0,steps*dt,steps+1)\n    pop_acc=np.zeros((steps+1,d)); jump_counts=np.zeros(ntraj,int); finals=np.zeros(ntraj,int)\n    reps=[]\n    for tr in range(ntraj):\n        psi=np.zeros(d,complex); psi[nmax]=1\n        pop_acc[0]+=abs(psi)**2; path=[0]\n        for it in range(1,steps+1):\n            # first-order jump probabilities evaluated at the beginning of the step\n            rates=np.array([max(0.0,float(np.real(np.vdot(psi,(C.conj().T@C)@psi)))) for C in cops])\n            probs=dt*rates; pjump=min(float(probs.sum()),0.35)\n            r=rng.random()\n            if cops and r<pjump and probs.sum()>0:\n                target=rng.random()*probs.sum(); cs=np.cumsum(probs); j=int(np.searchsorted(cs,target))\n                psi=cops[j]@psi; norm=np.linalg.norm(psi); psi=psi/(norm if norm>0 else 1)\n                jump_counts[tr]+=1\n            else:\n                psi=Ueff@psi; psi/=np.linalg.norm(psi)\n            p=abs(psi)**2; pop_acc[it]+=p\n            path.append(float(np.sum(n*p)))\n        finals[tr]=int(rng.choice(n,p=abs(psi)**2/np.sum(abs(psi)**2)))\n        if tr<12: reps.append(path)\n    return n,times,pop_acc/ntraj,finals,jump_counts,np.asarray(reps)\n\n\ndef _pauli_expm(dx,dy,dz,theta=1.0):\n    """exp[-i theta (d.sigma)] for a two-level block."""\n    d=np.sqrt(dx*dx+dy*dy+dz*dz)\n    I=np.eye(2,dtype=complex)\n    if d<1e-14: return I\n    sx=np.array([[0,1],[1,0]],complex); sy=np.array([[0,-1j],[1j,0]],complex); sz=np.array([[1,0],[0,-1]],complex)\n    return np.cos(theta*d)*I-1j*np.sin(theta*d)*(dx*sx+dy*sy+dz*sz)/d\n\n\ndef floquet_ssh_bands(theta1=0.65*np.pi,theta2=0.90*np.pi,nk=301):\n    """Two-step chiral Floquet SSH drive U(k)=exp(-i H2) exp(-i H1)."""\n    k=np.linspace(-np.pi,np.pi,nk)\n    eps=np.zeros((nk,2))\n    for i,kk in enumerate(k):\n        U2=_pauli_expm(theta2*np.cos(kk),theta2*np.sin(kk),0,theta=1/theta2 if theta2 else 1)\n        # equivalently exp[-i theta2(cos k sx + sin k sy)]\n        U2=np.cos(theta2)*np.eye(2)-1j*np.sin(theta2)*(np.cos(kk)*np.array([[0,1],[1,0]])+np.sin(kk)*np.array([[0,-1j],[1j,0]]))\n        U1=np.cos(theta1)*np.eye(2)-1j*np.sin(theta1)*np.array([[0,1],[1,0]])\n        ph=np.angle(np.linalg.eigvals(U2@U1)); eps[i]=np.sort(ph)\n    return k,eps\n\n\ndef floquet_ssh_open(theta1=0.65*np.pi,theta2=0.90*np.pi,ncell=26):\n    """Open-chain two-step Floquet operator and edge localization weights."""\n    from scipy.linalg import expm\n    d=2*ncell; H1=np.zeros((d,d),complex); H2=np.zeros_like(H1)\n    for c in range(ncell):\n        a,b=2*c,2*c+1; H1[a,b]=H1[b,a]=theta1\n        if c<ncell-1:\n            H2[b,2*(c+1)]=H2[2*(c+1),b]=theta2\n    U=expm(-1j*H2)@expm(-1j*H1)\n    val,V=np.linalg.eig(U); ep=np.angle(val); order=np.argsort(ep); ep=ep[order]; V=V[:,order]\n    x=np.arange(d); ew=np.exp(-x/2.5)+np.exp(-(d-1-x)/2.5)\n    loc=np.sum(abs(V)**2*ew[:,None],axis=0)/np.sum(abs(V)**2,axis=0)\n    ipr=np.sum(abs(V)**4,axis=0)/(np.sum(abs(V)**2,axis=0)**2)\n    return ep,V,loc,ipr\n\n\ndef floquet_edge_map(n=41,ncell=18):\n    """Maximum edge weight of eigenmodes near quasienergy 0 and pi."""\n    th=np.linspace(0.08*np.pi,0.96*np.pi,n)\n    z=np.zeros((n,n)); p=np.zeros_like(z)\n    for i,t1 in enumerate(th):\n      for j,t2 in enumerate(th):\n        ep,V,loc,ipr=floquet_ssh_open(t1,t2,ncell)\n        d0=np.abs(np.angle(np.exp(1j*ep)))\n        dpi=np.abs(np.pi-np.abs(ep))\n        m0=d0<0.18; mp=dpi<0.18\n        z[j,i]=loc[m0].max() if np.any(m0) else 0\n        p[j,i]=loc[mp].max() if np.any(mp) else 0\n    return th,z,p\n\n\ndef hofstadter_flux_defect(L=19,alpha=1/3,delta_flux=np.pi,j=1.0):\n    """Finite square Hofstadter lattice with one local Peierls-phase defect bond."""\n    sites=[(x,y) for x in range(L) for y in range(L)]; idx={s:i for i,s in enumerate(sites)}; N=L*L\n    H=np.zeros((N,N),complex); cx=L//2; cy=L//2\n    for x,y in sites:\n        i=idx[(x,y)]\n        if x+1<L:\n            phase=0.0\n            # modify one horizontal bond bordering the central plaquette\n            if x==cx and y==cy: phase=delta_flux\n            jj=idx[(x+1,y)]; amp=j*np.exp(1j*phase); H[jj,i]+=amp; H[i,jj]+=np.conj(amp)\n        if y+1<L:\n            jj=idx[(x,y+1)]; amp=j*np.exp(1j*2*np.pi*alpha*x); H[jj,i]+=amp; H[i,jj]+=np.conj(amp)\n    return sites,H\n\n\ndef flux_defect_spectral_flow(fluxes=np.linspace(0,2*np.pi,61),L=13,alpha=1/3):\n    """Eigenvalues nearest the central magnetic gap and defect-localization weight."""\n    vals=[]; weights=[]; cx=L//2; cy=L//2; rr=[]\n    sites=[(x,y) for x in range(L) for y in range(L)]\n    for x,y in sites: rr.append(np.hypot(x-cx,y-cy))\n    dw=np.exp(-np.asarray(rr)**2/(2*2.0**2))\n    for ph in fluxes:\n        _,H=hofstadter_flux_defect(L,alpha,ph); E,V=eigh(H)\n        # retain middle-energy window around zero; localization highlights defect branches\n        order=np.argsort(np.abs(E))[:18]; Ee=E[order]; Ve=V[:,order]\n        ww=np.sum(abs(Ve)**2*dw[:,None],axis=0)\n        vals.append(Ee); weights.append(ww)\n    return np.asarray(fluxes),np.asarray(vals),np.asarray(weights)\n\n\ndef rice_mele_nonhermitian_pump(ncell=22,cycles=1,nsteps=140,J=1.0,delta0=0.72,Delta0=1.15,eta=0.0,gamma=0.0):\n    """Normalized state transport through a Rice-Mele cycle with nonreciprocal hopping/loss."""\n    from scipy.linalg import expm\n    d=2*ncell; x=np.repeat(np.arange(ncell),2).astype(float)\n    psi=np.zeros(d,complex); psi[2*(ncell//3)]=1.0\n    ts=np.linspace(0,2*np.pi*cycles,nsteps); com=[]; norm=[]; edge=[]\n    dt=(ts[1]-ts[0]) if len(ts)>1 else 0.04\n    for t in ts:\n        delta=delta0*np.cos(t); stagger=Delta0*np.sin(t)\n        H=np.zeros((d,d),complex)\n        for c in range(ncell):\n            a,b=2*c,2*c+1; H[a,a]=stagger; H[b,b]=-stagger-1j*gamma\n            t1=J+delta; H[a,b]=t1*np.exp(+eta); H[b,a]=t1*np.exp(-eta)\n            if c<ncell-1:\n                t2=J-delta; H[b,2*(c+1)]=t2*np.exp(+eta); H[2*(c+1),b]=t2*np.exp(-eta)\n        psi=expm(-1j*H*dt)@psi\n        nn=np.vdot(psi,psi).real; norm.append(nn); psi/=np.sqrt(max(nn,1e-30))\n        p=abs(psi)**2; com.append(np.sum(x*p)); edge.append(np.sum(p[:6])+np.sum(p[-6:]))\n    return ts,np.asarray(com),np.asarray(norm),np.asarray(edge),psi\n\n\ndef propagation_caustic(g1=2.0,g2=1.15,g3=0.72,phi2=0.7,phi3=-1.1,nz=181,nt=420,zmax=0.16):\n    """Temporal intensity manifold during free propagation of a three-color PINEM comb."""\n    n,A=threecolor_coefficients(g1,g2,g3,phi2,phi3,nmax=15)\n    theta=np.linspace(-np.pi,np.pi,nt,endpoint=False); zetas=np.linspace(0,zmax,nz)\n    I=np.zeros((nz,nt)); ridge=np.zeros(nz); part=np.zeros(nz)\n    for iz,z in enumerate(zetas):\n        psi=np.sum((A*np.exp(-1j*z*n*n))[:,None]*np.exp(-1j*n[:,None]*theta),axis=0)\n        q=abs(psi)**2; q/=q.max()+1e-30; I[iz]=q; ridge[iz]=theta[np.argmax(q)]\n        qq=q/q.sum(); part[iz]=1/np.sum(qq*qq)\n    return n,A,theta,zetas,I,ridge,part\n\n\ndef experimental_error_budget(nsamples=700,seed=12):\n    """Monte-Carlo forward model for uncertainty in a two-color energy-OAM observable.\n\n    Outputs standardized parameters and observable metrics for sensitivity analysis.\n    """\n    rng=np.random.default_rng(seed)\n    # nominal operating point and independent experimental uncertainties\n    names=[\'g1\',\'g2\',\'phase\',\'sigma_E\',\'sigma_L\',\'counts\']\n    X=np.empty((nsamples,6)); Y=np.empty((nsamples,3))\n    for i in range(nsamples):\n        g1=rng.normal(1.55,0.10); g2=rng.normal(1.05,0.08); ph=rng.normal(0.65,0.13)\n        se=max(0.05,rng.normal(0.72,0.10)); sl=max(0.05,rng.normal(0.65,0.10)); counts=max(400,rng.normal(4200,800))\n        _,_,ideal,meas=measured_joint_distribution(g1,g2,-1,-2,se,sl,int(counts),seed=int(rng.integers(1e9)),nmax=10,phi2=ph)\n        mi=mutual_information(meas); fi=phase_fisher(g1,g2,-1,-2,se,sl,ph,nmax=10)\n        # Bhattacharyya fidelity to corresponding ideal state\n        fid=np.sum(np.sqrt(np.maximum(ideal,0)*np.maximum(meas,0)))**2/(ideal.sum()*meas.sum()+1e-30)\n        X[i]=[g1,g2,ph,se,sl,counts]; Y[i]=[mi,fi,fid]\n    # standardized linear sensitivities; useful local/global diagnostic, not causal Sobol indices\n    Xz=(X-X.mean(0))/X.std(0); Yz=(Y-Y.mean(0))/Y.std(0)\n    sens=(Xz.T@Yz)/(len(Xz)-1)\n    return names,X,Y,sens\n\n# --- v16: quantized-light PINEM, fermionic interference, noise spectroscopy and tomography ---\ndef _electron_shift(ne):\n    """Finite electron energy-ladder raising operator |n+1><n|, n=-ne..ne."""\n    d=2*ne+1; S=np.zeros((d,d),complex)\n    for i in range(d-1): S[i+1,i]=1.0\n    return S\n\n\ndef quantized_pinem_hamiltonian(ne=7,nph=28,coupling=1.0):\n    """Quantized single-mode PINEM interaction H = g(S+ a + S- a^dagger).\n\n    The electron ladder step S+ raises electron energy by one photon quantum while\n    annihilating a cavity photon. The Hermitian conjugate describes stimulated/spontaneous\n    emission into the same mode. Units are chosen such that pulse area is time*coupling.\n    """\n    from scipy.sparse import csr_matrix, kron, identity, diags\n    S=csr_matrix(_electron_shift(ne)); a=diags(np.sqrt(np.arange(1,nph+1)),1,shape=(nph+1,nph+1),dtype=complex)\n    H=coupling*(kron(S,a)+kron(S.getH(),a.getH()))\n    return H.tocsr()\n\n\ndef photon_state(kind=\'coherent\',nph=28,mean=9.0,phase=0.0,fock_n=None,squeeze_r=1.2):\n    """Return a pure photon ket when available, or diagonal weights for thermal light."""\n    from scipy.special import gammaln\n    m=np.arange(nph+1)\n    if kind==\'coherent\':\n        alpha=np.sqrt(mean)*np.exp(1j*phase)\n        logamp=-0.5*abs(alpha)**2 + m*np.log(alpha+0j) - 0.5*np.array([gammaln(x+1) for x in m])\n        c=np.exp(logamp); c/=np.linalg.norm(c); return c,None\n    if kind==\'fock\':\n        N=int(round(mean if fock_n is None else fock_n)); c=np.zeros(nph+1,complex); c[min(N,nph)]=1; return c,None\n    if kind==\'squeezed\':\n        # squeezed vacuum coefficients in even Fock states\n        from scipy.special import gammaln\n        c=np.zeros(nph+1,complex)\n        for k in range((nph//2)+1):\n            n=2*k\n            if n>nph: break\n            logpref=0.5*gammaln(2*k+1)-k*np.log(2.0)-gammaln(k+1)-0.5*np.log(np.cosh(squeeze_r))\n            c[n]=np.exp(logpref)*((-np.exp(1j*phase)*np.tanh(squeeze_r))**k)\n        c/=np.linalg.norm(c); return c,None\n    if kind==\'thermal\':\n        nbar=float(mean); w=(nbar**m)/(1+nbar)**(m+1); w/=w.sum(); return None,w\n    raise ValueError(kind)\n\n\ndef quantum_pinem_joint(kind=\'coherent\',ne=7,nph=28,mean=9.0,pulse_area=0.42,phase=0.0,squeeze_r=1.2):\n    """Joint electron-photon probability after a quantized PINEM interaction.\n\n    Thermal light is propagated as an incoherent mixture of Fock states. Pure input states\n    additionally return the final statevector for entanglement/heralding calculations.\n    """\n    from scipy.sparse.linalg import expm_multiply\n    H=quantized_pinem_hamiltonian(ne,nph,coupling=1.0)\n    de=2*ne+1; e0=np.zeros(de,complex); e0[ne]=1\n    c,w=photon_state(kind,nph,mean,phase,squeeze_r=squeeze_r)\n    if c is not None:\n        psi0=np.kron(e0,c); psi=expm_multiply((-1j*pulse_area)*H,psi0)\n        A=psi.reshape(de,nph+1); P=np.abs(A)**2; P/=P.sum()\n        return np.arange(-ne,ne+1),np.arange(nph+1),P,psi\n    P=np.zeros((de,nph+1))\n    for m0,wm in enumerate(w):\n        if wm<1e-10: continue\n        p0=np.zeros(nph+1,complex); p0[m0]=1; psi0=np.kron(e0,p0)\n        psi=expm_multiply((-1j*pulse_area)*H,psi0); A=psi.reshape(de,nph+1)\n        P+=wm*np.abs(A)**2\n    P/=P.sum(); return np.arange(-ne,ne+1),np.arange(nph+1),P,None\n\n\ndef quantum_light_spectra(kinds=(\'coherent\',\'fock\',\'thermal\',\'squeezed\'),ne=8,nph=34,mean=10,pulse_area=.38):\n    out={}\n    for k in kinds:\n        n,m,P,psi=quantum_pinem_joint(k,ne,nph,mean,pulse_area,squeeze_r=np.arcsinh(np.sqrt(mean)))\n        out[k]=(n,P.sum(axis=1),P.sum(axis=0),P,psi)\n    return out\n\n\ndef bipartite_entropy_from_state(psi,ne,nph):\n    """Electron-photon entanglement entropy for a pure state."""\n    A=np.asarray(psi).reshape(2*ne+1,nph+1); rho=A@A.conj().T\n    lam=np.linalg.eigvalsh((rho+rho.conj().T)/2); lam=lam[lam>1e-13]\n    return float(-np.sum(lam*np.log2(lam))),lam[::-1],rho\n\n\ndef quantized_entanglement_scan(means=np.linspace(.2,16,55),areas=np.linspace(.05,.8,55),ne=6,nph=28):\n    S=np.zeros((len(areas),len(means))); width=np.zeros_like(S)\n    for ia,a in enumerate(areas):\n      for im,mu in enumerate(means):\n        n,m,P,psi=quantum_pinem_joint(\'coherent\',ne,nph,mu,a)\n        S[ia,im]=bipartite_entropy_from_state(psi,ne,nph)[0]\n        pe=P.sum(1); av=np.sum(n*pe); width[ia,im]=np.sqrt(np.sum((n-av)**2*pe))\n    return np.asarray(means),np.asarray(areas),S,width\n\n\ndef heralded_photon_state(mean=8,pulse_area=.45,herald_n=2,ne=7,nph=30):\n    n,m,P,psi=quantum_pinem_joint(\'coherent\',ne,nph,mean,pulse_area)\n    A=psi.reshape(2*ne+1,nph+1); i=int(np.argmin(abs(n-herald_n)))\n    c=A[i].copy(); prob=float(np.vdot(c,c).real); c/=np.sqrt(prob+1e-30)\n    pn=np.abs(c)**2; nav=np.sum(m*pn); g2=np.sum(m*(m-1)*pn)/(nav*nav+1e-30)\n    return m,pn,prob,float(nav),float(g2),c\n\n\ndef photon_statistics_response(max_input=18,ne=7,nph=30,pulse_area=.42):\n    """Response K[electron order, input photon number] for number-state illumination."""\n    ns=np.arange(-ne,ne+1); K=np.zeros((len(ns),max_input+1))\n    for N in range(max_input+1):\n        n,m,P,_=quantum_pinem_joint(\'fock\',ne,nph,N,pulse_area)\n        K[:,N]=P.sum(1)\n    return ns,np.arange(max_input+1),K\n\n\ndef invert_photon_statistics(weights, max_input=18, ne=7,nph=30,pulse_area=.42,counts=12000,seed=2,reg=2e-3):\n    """Infer an unknown photon-number distribution from an electron spectrum using NNLS/Tikhonov."""\n    from scipy.optimize import nnls\n    ns,N,K=photon_statistics_response(max_input,ne,nph,pulse_area)\n    w=np.asarray(weights,float)[:max_input+1]; w=np.maximum(w,0); w/=w.sum()\n    p=K@w; rng=np.random.default_rng(seed); c=rng.multinomial(counts,p/p.sum()); y=c/c.sum()\n    A=np.vstack([K, np.sqrt(reg)*np.eye(max_input+1)])\n    b=np.r_[y, np.zeros(max_input+1)]\n    wh,_=nnls(A,b); wh/=wh.sum()+1e-30\n    return ns,N,K,p,y,wh,c\n\n\ndef classical_pinem_unitary(ne=12,g=1.8,phase=0.0):\n    """Finite energy-bin unitary kernel of a classical monochromatic PINEM phase modulator."""\n    n=np.arange(-ne,ne+1); U=np.zeros((len(n),len(n)),complex)\n    for i,m in enumerate(n):\n      for j,k in enumerate(n):\n        q=m-k; U[i,j]=(1j**q)*jv(q,2*g)*np.exp(1j*q*phase)\n    # finite truncation is approximately unitary in the central sector\n    return n,U\n\n\ndef two_electron_exchange_map(g=1.8,separation=2,ne=12):\n    """Coincidence matrices for identical fermions vs distinguishable electrons in energy bins."""\n    n,U=classical_pinem_unitary(ne,g)\n    # choose two distinct input bins whose integer separation equals the requested value\n    left=-int(np.ceil(separation/2)); right=left+int(separation)\n    a=np.argmin(abs(n-left)); b=np.argmin(abs(n-right))\n    Pf=np.zeros((len(n),len(n))); Pd=np.zeros_like(Pf)\n    for i in range(len(n)):\n      for j in range(len(n)):\n        amp=U[i,a]*U[j,b]-U[i,b]*U[j,a]\n        Pf[i,j]=0.5*abs(amp)**2\n        Pd[i,j]=0.5*(abs(U[i,a]*U[j,b])**2+abs(U[i,b]*U[j,a])**2)\n    Pf/=Pf.sum(); Pd/=Pd.sum()\n    exchange=Pf-Pd\n    return n,Pf,Pd,exchange\n\n\ndef two_electron_visibility_scan(gs=np.linspace(.1,4.5,120),seps=(1,2,4,6),ne=14):\n    V=np.zeros((len(seps),len(gs)))\n    for isep,s in enumerate(seps):\n      for ig,g in enumerate(gs):\n        n,Pf,Pd,E=two_electron_exchange_map(g,s,ne)\n        V[isep,ig]=0.5*np.sum(np.abs(Pf-Pd))\n    return np.asarray(gs),np.asarray(seps),V\n\n\ndef two_pulse_phase_noise(g=1.4,delays=None,sigma_phi=.5,tau_c=1.0,nmax=18):\n    """Two-pulse PINEM interferometer under Ornstein-Uhlenbeck phase noise.\n\n    The relative phase variance is 2 sigma_phi^2(1-exp(-tau/tau_c)). Spectra are averaged\n    analytically by Gaussian quadrature over phase noise.\n    """\n    from numpy.polynomial.hermite import hermgauss\n    if delays is None: delays=np.linspace(0,5,121)\n    n=np.arange(-nmax,nmax+1); X,W=hermgauss(22); W=W/np.sqrt(np.pi)\n    spectra=[]; visibility=[]; coherence=[]\n    for tau in delays:\n        var=2*sigma_phi**2*(1-np.exp(-tau/tau_c)); sd=np.sqrt(max(var,1e-15))\n        P=np.zeros(len(n));\n        for x,w in zip(X,W):\n            dphi=np.sqrt(2)*sd*x\n            # two equal complex couplings add coherently\n            geff=abs(g*(1+np.exp(1j*dphi)))\n            P+=w*(jv(n,2*geff)**2)\n        P/=P.sum(); spectra.append(P)\n        visibility.append(np.exp(-0.5*var))\n        coherence.append(np.sum(np.sqrt(P[:-1]*P[1:])))\n    return n,np.asarray(delays),np.asarray(spectra),np.asarray(visibility),np.asarray(coherence)\n\n\ndef robust_threecolor_design(target_n=(-3,-2,-1,0,1,2,3),target_p=None,jitter=(.06,.06,.06,.10,.10),seed=8):\n    """Robust inverse design minimizing ensemble-averaged spectral infidelity under control jitter."""\n    from scipy.optimize import differential_evolution\n    rng=np.random.default_rng(seed); tn=np.asarray(target_n,int)\n    if target_p is None:\n        target_p=np.exp(-0.5*(tn/1.15)**2); target_p=target_p/target_p.sum()\n    target_p=np.asarray(target_p,float)/np.sum(target_p)\n    noises=rng.normal(size=(42,5))*np.asarray(jitter)[None,:]\n    def fidelity(x,eps):\n        g1=max(.02,x[0]*(1+eps[0])); g2=max(.02,x[1]*(1+eps[1])); g3=max(.02,x[2]*(1+eps[2])); p2=x[3]+eps[3]; p3=x[4]+eps[4]\n        n,A=threecolor_coefficients(g1,g2,g3,p2,p3,nmax=12); p=np.abs(A)**2\n        pv=np.array([p[np.argmin(abs(n-q))] for q in tn]); pv/=pv.sum()+1e-30\n        return np.sum(np.sqrt(pv*target_p))**2\n    def obj(x):\n        fs=np.array([fidelity(x,e) for e in noises]); return -(0.7*fs.mean()+0.3*np.quantile(fs,.1))\n    bounds=[(.15,3.2),(.05,2.4),(.02,1.8),(-np.pi,np.pi),(-np.pi,np.pi)]\n    res=differential_evolution(obj,bounds,seed=seed,popsize=9,maxiter=55,tol=4e-4,polish=True)\n    x=res.x; fs=np.array([fidelity(x,e) for e in noises])\n    n,A=threecolor_coefficients(*x[:3],x[3],x[4],nmax=12); p=np.abs(A)**2\n    return x,fs,n,p,tn,target_p\n\n\ndef complex_beta_tomography(nx=70,ny=70,counts=18000,seed=11):\n    """Interferometric reconstruction of a spatially varying complex PINEM coupling beta(x,y).\n\n    Four reference phases are used. At moderate coupling the +1 sideband probability is evaluated\n    with the full Bessel response J1(2|beta+beta_ref|)^2; a nonlinear least-squares pixel inversion\n    reconstructs Re/Im beta. For speed, inversion uses a calibrated lookup/Newton approximation.\n    """\n    rng=np.random.default_rng(seed); x=np.linspace(-1,1,nx); y=np.linspace(-1,1,ny); X,Y=np.meshgrid(x,y)\n    amp=1.2*(X**2+Y**2)*np.exp(-2.0*(X**2+Y**2))*(1+0.22*np.cos(3*np.arctan2(Y,X)))\n    phase=2.0*np.arctan2(Y,X)+0.8*X-0.35*Y\n    beta=amp*np.exp(1j*phase); bref=.25\n    refs=np.array([0,np.pi/2,np.pi,3*np.pi/2]); meas=[]\n    for ph in refs:\n        z=beta+bref*np.exp(1j*ph); P=jv(1,2*np.abs(z))**2\n        C=rng.poisson(counts*P); meas.append(C/counts)\n    meas=np.asarray(meas)\n    # small/moderate-coupling calibrated intensity proxy: invert J1 branch to effective |z|^2 by lookup\n    rr=np.linspace(0,2.2,2400); yy=jv(1,2*rr)**2\n    # choose first monotonic branch up to first maximum, enough for generated field+reference\n    imax=np.argmax(yy); rr0=rr[:imax+1]; yy0=yy[:imax+1]\n    R=np.zeros_like(meas)\n    for k in range(4): R[k]=np.interp(np.clip(meas[k],yy0.min(),yy0.max()),yy0,rr0)**2\n    # phase-shifting interferometry: R0-Rpi=4*bref*Re beta; Rpi/2-R3pi/2=4*bref*Im beta\n    bre=(R[0]-R[2])/(4*bref); bim=(R[1]-R[3])/(4*bref)\n    bhat=bre+1j*bim\n    mask=amp>.08; err=np.sqrt(np.mean(np.abs(bhat[mask]-beta[mask])**2))/np.sqrt(np.mean(np.abs(beta[mask])**2))\n    return x,y,beta,meas,bhat,float(err)\n\n\ndef quantum_pinem_information(kind=\'coherent\',mean=8.0,area=.4,ne=6,nph=28,squeeze_r=1.2,darea=1e-3):\n    """Classical Fisher information in electron/photon/joint number measurements and pure-state QFI.\n\n    The parameter is the dimensionless interaction pulse area multiplying the quantized PINEM Hamiltonian.\n    Pure-state QFI is 4 Var(H) in the input state. Number-resolved classical FIs are evaluated by finite differences.\n    """\n    H=quantized_pinem_hamiltonian(ne,nph,coupling=1.0)\n    de=2*ne+1; e0=np.zeros(de,complex); e0[ne]=1\n    c,w=photon_state(kind,nph,mean,squeeze_r=squeeze_r)\n    if c is None: raise ValueError(\'QFI helper supports pure photon inputs only\')\n    psi0=np.kron(e0,c)\n    hpsi=H@psi0; hmean=np.vdot(psi0,hpsi).real; h2=np.vdot(hpsi,hpsi).real\n    qfi=4*max(0.0,h2-hmean*hmean)\n    def probs(a):\n        n,m,P,psi=quantum_pinem_joint(kind,ne,nph,mean,a,squeeze_r=squeeze_r)\n        return P,P.sum(1),P.sum(0)\n    P0,Pe0,Pp0=probs(area); Pp,PeP,PphP=probs(area+darea); Pm,PeM,PphM=probs(area-darea)\n    def FI(p,pp,pm):\n        dp=(pp-pm)/(2*darea); return float(np.sum(dp*dp/np.maximum(p,1e-12)))\n    return qfi,FI(Pe0,PeP,PeM),FI(Pp0,PphP,PphM),FI(P0,Pp,Pm)\n\n\ndef heralded_nonclassicality_map(mean=8.0,areas=np.linspace(.08,.72,36),heralds=np.arange(-5,6),ne=7,nph=30):\n    """Conditional photon Fano factor, g2 and success probability after electron energy heralding."""\n    areas=np.asarray(areas,float); heralds=np.asarray(heralds,int)\n    F=np.full((len(heralds),len(areas)),np.nan); G=np.full_like(F,np.nan); Pr=np.zeros_like(F)\n    m=np.arange(nph+1)\n    for ia,a in enumerate(areas):\n        n,mm,P,psi=quantum_pinem_joint(\'coherent\',ne,nph,mean,float(a)); A=psi.reshape(2*ne+1,nph+1)\n        for ih,h in enumerate(heralds):\n            i=np.argmin(abs(n-h)); c=A[i]; pr=np.vdot(c,c).real; Pr[ih,ia]=pr\n            if pr<1e-8: continue\n            p=abs(c)**2/pr; nav=np.sum(m*p); var=np.sum((m-nav)**2*p)\n            F[ih,ia]=var/(nav+1e-30); G[ih,ia]=np.sum(m*(m-1)*p)/(nav*nav+1e-30)\n    return areas,heralds,F,G,Pr\n', Path(__file__).parent/'models'/'novel_extensions.py')

