_install_module('models.reliability_design', 'import numpy as np\nfrom scipy.constants import c,hbar,e,m_e\nfrom scipy.special import jv\nfrom .pinem_core import electron_relativistic, drude_eps, rayleigh_efficiencies, mie_efficiencies_sphere, field_decay_length_cylinder\n\n\ndef exact_photon_momentum_shift(ke_eV, photon_eV, order=1):\n    """Exact longitudinal electron momentum change for absorbing `order` photons."""\n    K0=float(ke_eV)*e\n    dE=float(order)*float(photon_eV)*e\n    mc2=m_e*c*c\n    E0=K0+mc2; E1=E0+dE\n    p0=np.sqrt(E0*E0-mc2*mc2)/c\n    p1=np.sqrt(E1*E1-mc2*mc2)/c\n    return (p1-p0)/hbar\n\n\ndef nonrecoil_q(ke_eV, photon_eV, order=1):\n    rel=electron_relativistic(ke_eV)\n    omega=float(photon_eV)*e/hbar\n    return float(order)*omega/rel[\'v\']\n\n\ndef recoil_relative_error(ke_eV, photon_eV, order=1):\n    qx=exact_photon_momentum_shift(ke_eV,photon_eV,order)\n    q0=nonrecoil_q(ke_eV,photon_eV,order)\n    return abs(qx-q0)/max(abs(qx),1e-30)\n\n\ndef bessel_truncation_error(g,nmax):\n    n=np.arange(-int(nmax),int(nmax)+1)\n    return max(0.0,1.0-float(np.sum(jv(n,2*float(g))**2)))\n\n\ndef required_sideband_cutoff(g,tol=1e-6,nmax_limit=400):\n    for nmax in range(1,nmax_limit+1):\n        if bessel_truncation_error(g,nmax)<tol:\n            return nmax\n    return nmax_limit\n\n\ndef silver_eps_drude(wavelength_nm, wp_eV=9.01, gamma_eV=0.021, eps_inf=5.0):\n    lam=np.asarray(wavelength_nm,float)*1e-9\n    omega=2*np.pi*c/lam\n    return drude_eps(omega,wp_eV*e/hbar,gamma_eV*e/hbar,eps_inf)\n\n\ndef mie_rayleigh_relative_error(radius_nm,wavelength_nm):\n    r=float(radius_nm)*1e-9\n    lam=float(wavelength_nm)*1e-9\n    omega=2*np.pi*c/lam\n    eps=silver_eps_drude(wavelength_nm)\n    qsr,qar=rayleigh_efficiencies(r,omega,eps)\n    qsm,qam,qem=mie_efficiencies_sphere(r,omega,eps)\n    qer=float(qsr+qar)\n    return abs(qem-qer)/max(abs(qem),1e-12),qem,qer\n\n\ndef sideband_probs(g,nmax=20,blur=0.0):\n    from scipy.ndimage import gaussian_filter1d\n    n=np.arange(-nmax,nmax+1)\n    p=jv(n,2*float(g))**2; p=p/p.sum()\n    if blur>0:\n        p=gaussian_filter1d(p,float(blur)); p=p/p.sum()\n    return n,p\n\n\ndef geometry_coupling(radius_nm,impact_nm,wavelength_nm,ke_eV=200e3,scale=2.8):\n    """Compact physics-based surrogate: Mie extinction amplitude times evanescent decay.\n\n    The absolute scale is calibrated phenomenologically; derivatives/identifiability are the target.\n    """\n    err,qm,qr=mie_rayleigh_relative_error(radius_nm,wavelength_nm)\n    L=field_decay_length_cylinder(float(wavelength_nm)*1e-9,ke_eV)*1e9\n    # sqrt(extinction) is field-like, exponential factor is trajectory sampling.\n    return scale*np.sqrt(max(qm,1e-10))*np.exp(-(max(float(impact_nm),float(radius_nm))-float(radius_nm))/max(L,1e-9))\n\n\ndef poisson_fisher_for_geometry(radius_nm,impact_nm,wavelengths_nm,counts_per_wavelength=3000,ke_eV=200e3,blur=0.55,nmax=18):\n    th=np.array([float(radius_nm),float(impact_nm)])\n    F=np.zeros((2,2),float)\n    for lam in np.atleast_1d(wavelengths_nm):\n        g=geometry_coupling(th[0],th[1],float(lam),ke_eV)\n        _,p=sideband_probs(g,nmax,blur)\n        dp=np.zeros((2,len(p)))\n        steps=[max(.05,th[0]*2e-3),max(.05,th[1]*2e-3)]\n        for j,h in enumerate(steps):\n            tp=th.copy(); tm=th.copy(); tp[j]+=h; tm[j]-=h\n            gp=geometry_coupling(tp[0],tp[1],float(lam),ke_eV)\n            gm=geometry_coupling(tm[0],tm[1],float(lam),ke_eV)\n            _,pp=sideband_probs(gp,nmax,blur); _,pm=sideband_probs(gm,nmax,blur)\n            dp[j]=(pp-pm)/(2*h)\n        mu=np.maximum(p,1e-12)\n        F += float(counts_per_wavelength)*(dp/mu)@dp.T\n    return F\n\n\ndef d_optimal_pair_map(radius_nm=75,impact_nm=92,wavelengths=None,counts_each=2500,ke_eV=200e3,blur=.55):\n    if wavelengths is None: wavelengths=np.linspace(380,850,48)\n    wavelengths=np.asarray(wavelengths,float)\n    single=[poisson_fisher_for_geometry(radius_nm,impact_nm,[lam],counts_each,ke_eV,blur) for lam in wavelengths]\n    M=np.full((len(wavelengths),len(wavelengths)),np.nan)\n    for i in range(len(wavelengths)):\n        for j in range(i+1,len(wavelengths)):\n            M[i,j]=np.linalg.det(single[i]+single[j])\n    return wavelengths,M\n\ndef uncertainty_monte_carlo(nsamp=8000,seed=7,base=None):\n    """Small-noise uncertainty propagation using a local log-coupling expansion.\n\n    The expensive Mie calculation is evaluated only at the expansion point and\n    finite-difference stencil. This is appropriate for the quoted few-percent\n    experimental uncertainties and makes the statistical layer reproducible.\n    """\n    rng=np.random.default_rng(seed)\n    if base is None: base=dict(radius_nm=75.,impact_nm=92.,wavelength_nm=519.,ke_eV=200e3,blur=.55)\n    r=rng.normal(base[\'radius_nm\'],2.5,nsamp)\n    b=rng.normal(base[\'impact_nm\'],4.0,nsamp)\n    lam=rng.normal(base[\'wavelength_nm\'],1.5,nsamp)\n    ke=rng.normal(base[\'ke_eV\'],500.,nsamp)\n    blur=np.clip(rng.normal(base[\'blur\'],.06,nsamp),.05,None)\n    x0=np.array([base[\'radius_nm\'],base[\'impact_nm\'],base[\'wavelength_nm\'],base[\'ke_eV\']],float)\n    h=np.array([.2,.2,.2,50.0])\n    g0=geometry_coupling(*x0[:2],x0[2],x0[3])\n    grad=[]\n    for j in range(4):\n        xp=x0.copy(); xm=x0.copy(); xp[j]+=h[j]; xm[j]-=h[j]\n        gp=geometry_coupling(xp[0],xp[1],xp[2],xp[3]); gm=geometry_coupling(xm[0],xm[1],xm[2],xm[3])\n        grad.append((np.log(gp)-np.log(gm))/(2*h[j]))\n    grad=np.asarray(grad)\n    DX=np.column_stack([r-x0[0],b-x0[1],lam-x0[2],ke-x0[3]])\n    g=g0*np.exp(DX@grad)\n    qratio=np.array([c/electron_relativistic(kk)[\'v\'] for kk in ke])\n    support=np.array([required_sideband_cutoff(gg,1e-4,120) for gg in g],float)\n    fi=[]\n    for gg,ss in zip(g[::8],blur[::8]):\n        n,p=sideband_probs(gg,18,ss); dg=1e-3\n        _,pp=sideband_probs(gg+dg,18,ss); _,pm=sideband_probs(gg-dg,18,ss)\n        d=(pp-pm)/(2*dg); fi.append(np.sum(d*d/np.maximum(p,1e-12)))\n    return dict(radius_nm=r,impact_nm=b,wavelength_nm=lam,ke_eV=ke,blur=blur,g=g,qratio=qratio,support=support,fi=np.array(fi),logg_gradient=grad)\n\n', Path(__file__).parent/'models'/'reliability_design.py')

