_install_module('models.all_paper_reconstructions', "import numpy as np\nfrom scipy.special import jv, iv, eval_hermite, factorial\nfrom scipy.linalg import eigh, expm\nfrom scipy.ndimage import gaussian_filter\nfrom scipy.constants import c, e, hbar, m_e\n\nfrom .pinem_core import electron_relativistic, bessel_populations, temporal_bessel_population, dirac_spinor_components, mie_efficiencies_sphere, drude_eps\nfrom .feist2015 import sideband_coefficients, free_evolution_density, wigner_periodic\nfrom .baum2016 import compressed_width\nfrom .li2026 import dispersion as li_dispersion, joint_distribution\nfrom .cai2018 import eta_from_Omega\nfrom .wu2026 import electron_autocorr\nfrom .tavabi2025 import offaxis_oam_profile\nfrom .novel_extensions import quantum_light_spectra, quantum_pinem_information, heralded_photon_state\n\n# ---------- Generic utilities ----------\ndef gauss(x,s):\n    return np.exp(-0.5*(np.asarray(x)/s)**2)\n\ndef normalize(y,axis=None):\n    y=np.asarray(y,float); s=y.sum(axis=axis,keepdims=True)\n    return y/np.maximum(s,1e-30)\n\n# ---------- Volovik: Lifshitz topology ----------\ndef lifshitz_neck(mu=0.0,n=260,lim=2.2):\n    x=np.linspace(-lim,lim,n); y=np.linspace(-lim,lim,n); X,Y=np.meshgrid(x,y)\n    # 2D saddle proxy for a pz=const section of p_x^2+p_y^2-p_z^2-mu\n    E=X**2-Y**2-mu\n    return x,y,E\n\ndef saddle_dos(mu_values,eta=0.035,n=420,lim=3):\n    x=np.linspace(-lim,lim,n); y=np.linspace(-lim,lim,n); X,Y=np.meshgrid(x,y)\n    E=(X**2-Y**2)/2\n    out=[]\n    for mu in mu_values:\n        out.append(np.mean(eta/np.pi/((E-mu)**2+eta**2)))\n    return np.asarray(out)\n\ndef weyl_chern_slice(masses,nk=81):\n    # QWZ-type slices emulate Weyl-node Chern jumps as kz tunes mass.\n    k=np.linspace(-np.pi,np.pi,nk,endpoint=False); dk=2*np.pi/nk\n    out=[]\n    for m in masses:\n        F=0.0\n        for kx in k:\n            for ky in k:\n                d=np.array([np.sin(kx),np.sin(ky),m+np.cos(kx)+np.cos(ky)])\n                # analytic Berry curvature lower band d.hat derivatives\n                dx=np.array([np.cos(kx),0,-np.sin(kx)])\n                dy=np.array([0,np.cos(ky),-np.sin(ky)])\n                F += -0.5*np.dot(d,np.cross(dx,dy))/(np.linalg.norm(d)**3+1e-15)\n        out.append(F*dk*dk/(2*np.pi))\n    return np.asarray(out)\n\n# ---------- Tsang/Navarrete quantum optics ----------\ndef photon_number_distributions(mean=6,nmax=30,squeeze_r=1.0):\n    n=np.arange(nmax)\n    pois=np.exp(-mean)*mean**n/np.array([factorial(i,exact=False) for i in n]); pois/=pois.sum()\n    mf=float(mean); therm=(mf**n)/(1.0+mf)**(n+1); therm/=therm.sum()\n    fock=np.zeros(nmax); fock[min(int(round(mean)),nmax-1)]=1\n    # squeezed vacuum even distribution\n    sq=np.zeros(nmax); t=np.tanh(squeeze_r)\n    for k in range(nmax//2):\n        nn=2*k\n        sq[nn]=(factorial(2*k)/(2**(2*k)*factorial(k)**2))*t**(2*k)/np.cosh(squeeze_r)\n    sq/=sq.sum()\n    return n,dict(coherent=pois,thermal=therm,fock=fock,squeezed=sq)\n\ndef wigner_fock(nstate=1,xlim=3,n=180):\n    x=np.linspace(-xlim,xlim,n); p=x.copy(); X,P=np.meshgrid(x,p); r2=X*X+P*P\n    # W_n(alpha) with alpha=(x+ip)/sqrt(2), up to convention\n    from scipy.special import eval_laguerre\n    W=(((-1)**nstate)/np.pi)*np.exp(-r2)*eval_laguerre(nstate,2*r2)\n    return x,W\n\ndef jaynes_cummings_coherent(mean=8,g=1,tmax=35,nt=500,nmax=70):\n    t=np.linspace(0,tmax,nt); n=np.arange(nmax)\n    p=np.exp(-mean)*mean**n/np.array([factorial(i,exact=False) for i in n]); p/=p.sum()\n    pe=np.sum(p[:,None]*np.cos(g*np.sqrt(n[:,None]+1)*t[None,:])**2,axis=0)\n    return t,pe\n\n# ---------- Barwick 2009 ----------\ndef barwick_delay_spectra(delays_fs=(-450,0,450),g0=2.8,photon_eV=2.39):\n    E=np.linspace(-15,15,1600); out=[]\n    for d in delays_fs:\n        g=g0*np.exp(-(d/340)**2)\n        n,p=bessel_populations(g,7)\n        y=np.zeros_like(E)\n        for ni,pi in zip(n,p): y+=pi*np.exp(-(E-ni*photon_eV)**2/(2*0.38**2))\n        out.append(y/y.max())\n    return E,np.array(out)\n\ndef nearfield_image(nx=240,ny=180,L=52):\n    x=np.linspace(-280,280,nx); y=np.linspace(-210,210,ny); X,Y=np.meshgrid(x,y)\n    # nanowire along y; near-field localized at x=0 with polarization asymmetry\n    R=np.abs(X); field=np.exp(-R/L)*(0.35+0.65*np.cos(np.arctan2(Y,X))**2)\n    field*=np.exp(-(Y/260)**8)\n    return x,y,field\n\n# ---------- Baum 2016 ----------\ndef thz_phase_space(sigma_t=260,kappa=0.0036,drifts=None):\n    if drifts is None: drifts=np.linspace(0,420,140)\n    t=np.linspace(-3*sigma_t,3*sigma_t,400)\n    widths=np.array([abs(1-kappa*d)*sigma_t for d in drifts])\n    return t,np.asarray(drifts),widths\n\ndef streaking_curve(t_fs,amp=1.0,T=3200):\n    return amp*np.sin(2*np.pi*np.asarray(t_fs)/T)\n\n# ---------- Becker 2025 two-body KD ----------\ndef relative_ground(g=-5.0,n=320,L=8.0,sigma_delta=0.06):\n    x=np.linspace(-L,L,n); dx=x[1]-x[0]\n    main=np.ones(n)*2/dx**2 + 0.25*x*x + g*gauss(x,sigma_delta)/(np.sqrt(2*np.pi)*sigma_delta)\n    off=np.ones(n-1)*(-1/dx**2)\n    H=np.diag(main)+np.diag(off,1)+np.diag(off,-1)\n    E,V=eigh(H,subset_by_index=[0,3])\n    psi=V[:,0]; psi/=np.sqrt(np.trapz(abs(psi)**2,x))\n    return x,E,psi\n\ndef kd_two_body_map(g=-5.0,k=4.0,A=1.6,n=180,L=6):\n    r,_,pr=relative_ground(g,n=n,L=L)\n    R=np.linspace(-L/2,L/2,n); dR=R[1]-R[0]\n    pR=gauss(R,1.0); pR/=np.sqrt(np.trapz(abs(pR)**2,R))\n    RR,rr=np.meshgrid(R,r,indexing='ij')\n    psi=(pR[:,None]*pr[None,:]).astype(complex)\n    x1=RR+rr/2; x2=RR-rr/2\n    psi*=np.exp(-1j*A*(np.cos(k*x1)**2+np.cos(k*x2)**2))\n    F=np.fft.fftshift(np.fft.fft2(psi)); P=abs(F)**2; P/=P.sum()\n    pRaxis=np.fft.fftshift(np.fft.fftfreq(n,d=dR))*2*np.pi\n    draxis=r[1]-r[0]; praxis=np.fft.fftshift(np.fft.fftfreq(n,d=draxis))*2*np.pi\n    return R,r,abs(psi)**2,pRaxis,praxis,P\n\n# ---------- Garcia 2010 ----------\ndef multiphoton_map(gvals=np.linspace(0,7,220),nmax=12):\n    n=np.arange(-nmax,nmax+1)\n    P=np.array([jv(n,2*g)**2 for g in gvals]).T\n    return n,np.asarray(gvals),P\n\ndef coherent_vs_incoherent(gvals=np.linspace(0,6,220),order=0):\n    pc=jv(order,2*gvals)**2\n    # random-walk comparison with mu~2g^2\n    pi=np.exp(-2*gvals*gvals)*iv(abs(order),2*gvals*gvals)\n    return np.asarray(gvals),pc,pi\n\n# ---------- Park 2012 ----------\ndef relativistic_corrections(ke=np.linspace(1e3,500e3,300),deltaE=2.4):\n    rel=[electron_relativistic(x) for x in ke]\n    beta=np.array([r['beta'] for r in rel]); gamma=np.array([r['gamma'] for r in rel])\n    # quadratic dispersion coefficient scaling ~1/gamma^3 compared with NR longitudinal mass\n    d2=1/gamma**3\n    # recoil fraction photon/electron momentum\n    rec=deltaE/np.maximum(ke,1)\n    return np.asarray(ke),beta,gamma,d2,rec\n\n# ---------- Park 2010 ----------\ndef maxwell_to_pinem(radius_nm=np.linspace(10,180,120),wavelength_nm=519,wp_eV=9.1,gamma_eV=0.05,eps_inf=5.0):\n    omega=2*np.pi*c/(wavelength_nm*1e-9); wp=wp_eV*e/hbar; gam=gamma_eV*e/hbar\n    eps=drude_eps(omega,wp,gam,eps_inf)\n    qsca=[]; qabs=[]\n    for a in radius_nm: \n        qs,qa,_=mie_efficiencies_sphere(a*1e-9,omega,eps); qsca.append(qs); qabs.append(qa)\n    # PINEM proxy: surface field enhancement times geometric overlap\n    enh=np.sqrt(np.asarray(qsca)+np.asarray(qabs)+1e-8)/np.maximum(radius_nm,1)**0.25\n    enh/=enh.max(); g=5.0*enh\n    return np.asarray(radius_nm),np.asarray(qsca),np.asarray(qabs),g\n\n# ---------- Rivera 2020 ----------\ndef quasiparticle_landscape(qnorm=np.logspace(0,3,240),families=None):\n    if families is None: families=('photon','SPP','phonon-polariton','graphene plasmon')\n    # normalized omega/(cq0) qualitative dispersions using physically representative confinement trends\n    q=np.asarray(qnorm)\n    curves={\n        'photon':q,\n        'SPP':np.sqrt(q*q/(1+q*q/25)),\n        'phonon-polariton':3+0.2*np.tanh(np.log10(q)-1),\n        'graphene plasmon':0.9*np.sqrt(q),\n    }\n    return q,curves\n\ndef free_electron_matching(beta_values,qnorm):\n    # normalized electron line omega/(c q0)=beta*q\n    return np.outer(np.asarray(beta_values),np.asarray(qnorm))\n\n# ---------- Tavabi 2025 ----------\ndef oam_blur_profiles(sigmas=(0.4,0.8,1.2),lmax=8):\n    ell=np.arange(-lmax,lmax+1); out=[]\n    for s in sigmas:\n        p=np.exp(-(ell-1)**2/(2*s*s)); p/=p.sum(); out.append(p)\n    return ell,np.array(out)\n\n# ---------- Common PINEM quantum-optics transfer ----------\ndef classical_quantum_light_comparison(means=(1,4,12,30),beta=1.8):\n    rows=[]\n    for mean in means:\n        # pulse area chosen beta/sqrt(mean)\n        tau=beta/np.sqrt(mean)\n        n,p=quantum_light_spectra(kinds=('coherent',),mean=mean,pulse_area=tau,ne=9,nph=max(25,int(mean+8*np.sqrt(mean)+12)))\n        # function returns tuple? normalize downstream robustly\n        rows.append((mean,n,p))\n    return rows\n", Path(__file__).parent/'models'/'all_paper_reconstructions.py')

