_install_module('models.all_paper_builders', "from pathlib import Path\nimport numpy as np\nimport matplotlib.pyplot as plt\nfrom scipy.special import jv, iv\nfrom scipy.constants import c,hbar,e\n\nfrom preamble import pubfig,safe_panel,safe_title,safe_colorbar,clean,finish_pub,style_3d\nfrom models import all_paper_reconstructions as M\nfrom models.pinem_core import bessel_populations,electron_relativistic,field_decay_length_cylinder,temporal_bessel_population\nfrom models.li2026 import joint_distribution,dispersion,mode_entropy,dos\nfrom models.cai2018 import eta_from_Omega,radial_probability_contribution,far_radial\nfrom models.feist2015 import energy_map,wigner_periodic,free_evolution_density\nfrom models.tavabi2025 import offaxis_oam_profile, uncertainty_sigma_l\nfrom models.wu2026 import electron_autocorr_grid,scan_steady_state,iterate_at,V0,config\nfrom models.novel_extensions import quantum_light_spectra,quantum_pinem_information,heralded_nonclassicality_map\n\nOUT=Path(__file__).resolve().parents[1]/'paper_deep_reconstructions'\n\n\ndef _axes6(fig):\n    gs=fig.add_gridspec(2,3,wspace=.56,hspace=.55)\n    return [fig.add_subplot(gs[i,j]) for i in range(2) for j in range(3)]\n\ndef _tag(ax,i,title): safe_panel(ax,chr(97+i)); safe_title(ax,title); clean(ax)\n\ndef build_volovik(path):\n    fig=pubfig(8.2,5.7,top=.91); ax=_axes6(fig)\n    # neck disruption\n    x,y,E=M.lifshitz_neck(0); im=ax[0].contourf(x,y,E,levels=31,cmap='coolwarm'); ax[0].contour(x,y,E,[0],colors='k',linewidths=1.4); _tag(ax[0],0,'Neck-disrupting Lifshitz point'); ax[0].set(xlabel='$p_x$',ylabel='$p_y$'); safe_colorbar(fig,im,ax[0],label='$\\\\epsilon$')\n    mus=np.linspace(-.7,.7,240); D=M.saddle_dos(mus); ax[1].plot(mus,D); ax[1].axvline(0,ls='--',c='0.25'); _tag(ax[1],1,'Van Hove singularity'); ax[1].set(xlabel='$\\\\mu$',ylabel='DOS (a.u.)')\n    # three topology examples\n    k=np.linspace(-2,2,250); X,Y=np.meshgrid(k,k); for_mu=[-.55,0,.55]\n    for mu in for_mu:\n        cs=ax[2].contour(X,Y,X**2-Y**2-mu,[0],linewidths=1.1)\n    _tag(ax[2],2,'Fermi-surface reconnection'); ax[2].set(xlabel='$p_x$',ylabel='$p_y$',xlim=(-2,2),ylim=(-2,2))\n    masses=np.linspace(-3,3,61); ch=M.weyl_chern_slice(masses,nk=41); ax[3].plot(masses,ch); ax[3].axvline(-2,ls=':',c='0.4'); ax[3].axvline(0,ls=':',c='0.4'); ax[3].axvline(2,ls=':',c='0.4'); _tag(ax[3],3,'Chern jump across Weyl slices'); ax[3].set(xlabel='slice mass / $k_z$',ylabel='Chern number')\n    tilt=np.linspace(0,2,220); gap=np.maximum(1-tilt,0); ax[4].plot(tilt,gap,label='closed cone gap proxy'); ax[4].fill_between(tilt,0,1-gap,alpha=.2); ax[4].axvline(1,ls='--',c='k'); _tag(ax[4],4,'Type-I to type-II Weyl transition'); ax[4].set(xlabel='tilt / cone velocity',ylabel='open-FS measure'); ax[4].legend(frameon=False)\n    # PINEM mapping: Li dispersion ratios and DOS peaks\n    ratios=np.linspace(.2,3,80); peak=[]\n    for r in ratios:\n        en,dd=dos(1,r,n=160,bins=150); peak.append(dd.max())\n    ax[5].plot(ratios,peak); _tag(ax[5],5,'PINEM synthetic Lifshitz susceptibility'); ax[5].set(xlabel='$|\\\\beta_{2\\\\omega}|/|\\\\beta_\\\\omega|$',ylabel='max DOS')\n    finish_pub(fig,path)\n\ndef build_tsang(path):\n    fig=pubfig(8.2,5.7,top=.91); ax=_axes6(fig)\n    n,d=M.photon_number_distributions(mean=7,squeeze_r=1.15)\n    for k,v in d.items(): ax[0].plot(n,v,marker='o',ms=2,label=k)\n    _tag(ax[0],0,'Photon-number statistics'); ax[0].set(xlabel='$n$',ylabel='$P_n$',xlim=(0,22)); ax[0].legend(frameon=False,ncol=2)\n    x,W0=M.wigner_fock(0); _,W1=M.wigner_fock(1); im=ax[1].imshow(W1,extent=[x[0],x[-1],x[0],x[-1]],origin='lower',cmap='RdBu_r'); _tag(ax[1],1,'Nonclassical Wigner negativity'); ax[1].set(xlabel='$X$',ylabel='$P$'); safe_colorbar(fig,im,ax[1],label='$W_1$')\n    t,pe=M.jaynes_cummings_coherent(mean=8); ax[2].plot(t,pe); _tag(ax[2],2,'Collapse and revival'); ax[2].set(xlabel='$gt$',ylabel='$P_e$')\n    kinds=('coherent','fock','thermal','squeezed'); qspec=quantum_light_spectra(kinds=kinds,mean=8,pulse_area=.40,ne=7,nph=32)\n    for k in kinds:\n        nn,row=qspec[k][0],qspec[k][1]; ax[3].plot(nn,row,label=k)\n    _tag(ax[3],3,'Quantum-light PINEM fingerprints'); ax[3].set(xlabel='electron sideband $N$',ylabel='$P_N$'); ax[3].legend(frameon=False,ncol=2)\n    means=np.array([1,2,4,8,16,32]); qfi=[]; frac=[]\n    for m in means:\n        z=quantum_pinem_information(kind='coherent',mean=float(m),area=.4,ne=5,nph=max(20,int(m+8*np.sqrt(m)+8)))\n        # tuple/dict robust\n        qfi.append(float(z[0])); frac.append(float(z[1]/z[0]) if z[0]>0 else np.nan)\n    ax[4].plot(means,qfi,marker='o'); _tag(ax[4],4,'Quantum-information scaling'); ax[4].set(xlabel='mean photon number',ylabel='QFI / information proxy')\n    areas=np.linspace(.08,.7,24); heralds=np.arange(-4,5); A,H,F,G,P=heralded_nonclassicality_map(mean=8,areas=areas,heralds=heralds,ne=6,nph=28); im=ax[5].imshow(F,origin='lower',aspect='auto',extent=[areas[0],areas[-1],heralds[0],heralds[-1]],cmap='viridis'); _tag(ax[5],5,'Electron-heralded nonclassical light'); ax[5].set(xlabel='interaction area',ylabel='electron herald $N$'); safe_colorbar(fig,im,ax[5],label='Fano factor')\n    finish_pub(fig,path)\n\ndef build_barwick(path):\n    fig=pubfig(8.2,5.7,top=.91); ax=_axes6(fig)\n    E,S=M.barwick_delay_spectra(); cols=['0.45','C0','C3']\n    for y,c,l in zip(S,cols,['early','overlap','late']): ax[0].plot(E,y,c=c,label=l)\n    _tag(ax[0],0,'Photon-gain/loss spectra vs delay'); ax[0].set(xlabel='energy shift (eV)',ylabel='normalized counts'); ax[0].legend(frameon=False)\n    x,y,F=M.nearfield_image(); im=ax[1].imshow(F,origin='lower',extent=[x[0],x[-1],y[0],y[-1]],aspect='auto',cmap='magma'); _tag(ax[1],1,'Energy-filtered near-field image'); ax[1].set(xlabel='transverse $x$ (nm)',ylabel='$y$ (nm)'); safe_colorbar(fig,im,ax[1],label='PINEM gain')\n    r=np.linspace(0,250,250); ax[2].semilogy(r,np.exp(-r/52)); ax[2].axvline(52,ls='--',c='k'); _tag(ax[2],2,'Evanescent spatial decay'); ax[2].set(xlabel='distance from interface (nm)',ylabel='relative field')\n    d=np.linspace(-900,900,500); P=M.gauss(d,340)**2; ax[3].plot(d,P); _tag(ax[3],3,'Electron–photon cross correlation'); ax[3].set(xlabel='delay (fs)',ylabel='gain-electron signal')\n    ke=np.linspace(20e3,300e3,250); lam=[]\n    for K in ke: lam.append(field_decay_length_cylinder(519e-9,K)*1e9)\n    ax[4].plot(ke/1e3,lam); _tag(ax[4],4,'Momentum matching sets near-field scale'); ax[4].set(xlabel='electron kinetic energy (keV)',ylabel='evanescent scale (nm)')\n    g=np.linspace(0,5,200); n=np.arange(-6,7); P=np.array([jv(n,2*x)**2 for x in g]).T; im=ax[5].imshow(P,origin='lower',aspect='auto',extent=[g[0],g[-1],n[0],n[-1]],cmap='viridis'); _tag(ax[5],5,'PINEM Bessel ladder hidden in the 2009 data'); ax[5].set(xlabel='$|g|$',ylabel='photon order $N$'); safe_colorbar(fig,im,ax[5],label='$P_N$')\n    finish_pub(fig,path)\n\ndef build_baum(path):\n    fig=pubfig(8.2,5.7,top=.91); ax=_axes6(fig)\n    t=np.linspace(-900,900,500); E=.0036*t; ax[0].plot(t,E); _tag(ax[0],0,'THz longitudinal phase-space lens'); ax[0].set(xlabel='arrival time (fs)',ylabel='$\\\\Delta E$ (arb.)')\n    _,d,w=M.thz_phase_space(); ax[1].plot(d,w); ax[1].axhline(5,ls=':',c='0.4'); _tag(ax[1],1,'Compression vs drift'); ax[1].set(xlabel='effective drift',ylabel='rms pulse width (fs)')\n    ts=np.linspace(-1800,1800,700); ax[2].plot(ts,M.streaking_curve(ts,T=3200)); _tag(ax[2],2,'THz streaking transfer function'); ax[2].set(xlabel='delay (fs)',ylabel='deflection')\n    sig=np.linspace(2,80,200); res=np.sqrt(sig**2+4**2); ax[3].plot(sig,res); _tag(ax[3],3,'Timing-jitter convolution'); ax[3].set(xlabel='intrinsic pulse width (fs)',ylabel='measured width (fs)')\n    # phase-space before/after\n    rng=np.random.default_rng(2); tt=rng.normal(0,220,3000); ee=rng.normal(0,.25,3000); ax[4].scatter(tt,ee,s=2,alpha=.25,label='before'); ax[4].scatter(.08*tt,ee+.0036*tt,s=2,alpha=.15,label='compressed'); _tag(ax[4],4,'Phase-space rotation'); ax[4].set(xlabel='time (fs)',ylabel='energy coordinate'); ax[4].legend(frameon=False)\n    amp=np.linspace(0,.007,120); opt=260*np.abs(1-amp*278); ax[5].plot(amp,opt); _tag(ax[5],5,'Compression operating window'); ax[5].set(xlabel='THz chirp strength',ylabel='final width (fs)')\n    finish_pub(fig,path)\n\ndef build_becker(path):\n    fig=pubfig(8.2,5.7,top=.91); ax=_axes6(fig)\n    gs=[-5,0,5]; colors=['C0','0.35','C3']\n    for g,c0 in zip(gs,colors):\n        r,E,psi=M.relative_ground(g,n=220,L=7); ax[0].plot(r,abs(psi)**2,c=c0,label=f'g={g}')\n    _tag(ax[0],0,'Interacting relative ground states'); ax[0].set(xlabel='relative coordinate $r/\\\\ell$',ylabel='$|\\\\psi_r|^2$'); ax[0].legend(frameon=False)\n    R,r,Px,pR,pr,Pk=M.kd_two_body_map(-5,k=4,A=1.8,n=160,L=6); im=ax[1].imshow(Pk,origin='lower',extent=[pr[0],pr[-1],pR[0],pR[-1]],aspect='auto',cmap='magma',vmax=np.quantile(Pk,.999)); _tag(ax[1],1,'Two-body Kapitza–Dirac momentum map'); ax[1].set(xlabel='$p_r$',ylabel='$P_R$'); safe_colorbar(fig,im,ax[1],label='probability')\n    # correlation cuts for g\n    ks=np.arange(-3,4); corr=[]\n    for g in np.linspace(-6,6,31):\n        _,_,_,_,_,P=M.kd_two_body_map(g,k=4,A=1.3,n=96,L=5); mid=P.shape[0]//2; # anti-diagonal score\n        corr.append(np.sum(np.diag(np.fliplr(P)))/np.sum(P))\n    ax[2].plot(np.linspace(-6,6,31),corr); _tag(ax[2],2,'Interaction-controlled pair correlations'); ax[2].set(xlabel='$g/(\\\\hbar\\\\omega\\\\ell)$',ylabel='anti-diagonal momentum weight')\n    klist=[4,6]; t=np.linspace(0,.035,160)\n    for kk in klist: ax[3].plot(t,np.exp(-(t/(.007*(kk/4)**2))**2),label=f'$k_{{lat}}={kk}/\\\\ell$')\n    _tag(ax[3],3,'Sudden-approximation fidelity scale'); ax[3].set(xlabel='$t\\\\omega$',ylabel='$F$'); ax[3].legend(frameon=False)\n    gscan=np.linspace(-6,6,90); widths=[]\n    for g in gscan:\n        r,_,psi=M.relative_ground(g,n=130,L=6); widths.append(np.sqrt(np.trapz(r*r*abs(psi)**2,r)))\n    ax[4].plot(gscan,widths); _tag(ax[4],4,'Pair size across attraction and repulsion'); ax[4].set(xlabel='$g$',ylabel='$\\\\sqrt{\\\\langle r^2\\\\rangle}$')\n    # transfer to PINEM analogy\n    n=np.arange(-8,9); P=jv(n,3.4)**2; ax[5].stem(n,P,basefmt=' '); _tag(ax[5],5,'Diffraction-order analogy to PINEM'); ax[5].set(xlabel='momentum / photon order',ylabel='population')\n    finish_pub(fig,path)\n\ndef build_cai(path):\n    fig=pubfig(8.2,5.7,top=.91); ax=_axes6(fig)\n    Om=np.linspace(.05,4,300); eta=eta_from_Omega(1.8,Om); ax[0].plot(Om,eta); ax[0].axvline(1,ls='--',c='k'); _tag(ax[0],0,'Velocity/plasmon matching'); ax[0].set(xlabel='$\\\\Omega$',ylabel='$\\\\eta$')\n    rho=np.linspace(0,45,700)\n    for ell in [1,2,5]: ax[1].plot(rho,radial_probability_contribution(rho,ell,3,eta=2.5,fwhm=30),label=f'$\\\\ell={ell}$')\n    _tag(ax[1],1,'Real-plane OAM channels'); ax[1].set(xlabel='$k_pR$',ylabel='local probability'); ax[1].legend(frameon=False)\n    Q=np.linspace(0,2,220)\n    for ell in [1,2,5]:\n        F=far_radial(Q,ell,3,2.5,nr=1400,rmax=50); ax[2].plot(Q,abs(F)**2/np.max(abs(F)**2),label=f'$\\\\ell={ell}$')\n    _tag(ax[2],2,'Far-field vortex rings'); ax[2].set(xlabel='$Q/k_p$',ylabel='normalized intensity')\n    l=np.arange(-8,9); mvals=np.arange(1,9); Z=np.zeros((len(mvals),len(l)))\n    for i,m in enumerate(mvals): Z[i]=jv(l,3.6)**2*(np.abs(l*m)+1)**.15\n    im=ax[3].imshow(Z,origin='lower',aspect='auto',extent=[l[0],l[-1],mvals[0],mvals[-1]],cmap='viridis'); _tag(ax[3],3,'Energy–OAM transfer phase space'); ax[3].set(xlabel='PINEM order $\\\\ell$',ylabel='plasmon charge $m$'); safe_colorbar(fig,im,ax[3],label='weighted yield')\n    target=np.arange(0,31); best=[]\n    for L in target:\n        cand=[]\n        for m in range(1,11):\n            ell=max(1,int(round(L/m))) if L else 0\n            if abs(ell*m-L)<=1: cand.append(jv(ell,3.6)**2)\n        best.append(max(cand) if cand else 0)\n    ax[4].semilogy(target,np.maximum(best,1e-6)); _tag(ax[4],4,'High-OAM efficiency frontier'); ax[4].set(xlabel='target $|L_z|/\\\\hbar$',ylabel='best channel probability')\n    # azimuthal current proxy\n    et=np.linspace(.1,5,180); jphi=3*1.2e-3*np.abs(jv(1,2*et))**2; ax[5].plot(et,jphi); _tag(ax[5],5,'OAM as real azimuthal current'); ax[5].set(xlabel='$\\\\eta$',ylabel='$j_\\\\phi/j_z$ proxy')\n    finish_pub(fig,path)\n\ndef build_feist(path):\n    fig=pubfig(8.2,5.7,top=.91); ax=_axes6(fig)\n    g=np.linspace(0,6,260); n,P=energy_map(g,nmax=12); im=ax[0].imshow(P,origin='lower',aspect='auto',extent=[g[0],g[-1],n[0],n[-1]],cmap='viridis'); _tag(ax[0],0,'Coherent energy-lattice diffraction'); ax[0].set(xlabel='$|g|$',ylabel='sideband $N$'); safe_colorbar(fig,im,ax[0],label='$P_N$')\n    for N in [0,1,2,3]: ax[1].plot(g,jv(N,2*g)**2,label=f'$N={N}$')\n    _tag(ax[1],1,'Bessel population oscillations'); ax[1].set(xlabel='$|g|$',ylabel='population'); ax[1].legend(frameon=False)\n    th,nw,W=wigner_periodic(3.2,18); im=ax[2].imshow(W,origin='lower',aspect='auto',extent=[th[0],th[-1],nw[0],nw[-1]],cmap='RdBu_r',vmin=-1,vmax=1); _tag(ax[2],2,'Electron Wigner phase-space interference'); ax[2].set(xlabel='optical phase',ylabel='energy order'); safe_colorbar(fig,im,ax[2],label='Wigner proxy')\n    taus=np.linspace(0,70,180); peak=[]\n    for t0 in taus:\n        th,I=free_evolution_density(3.2,t0); peak.append(I.max())\n    ax[3].plot(taus,peak); _tag(ax[3],3,'Free-drift temporal compression'); ax[3].set(xlabel='dispersion / drift',ylabel='peak density')\n    # ensemble averaging washes oscillations\n    gs=np.linspace(0,6,180); for_sig=[0,.2,.5]\n    for s in for_sig:\n        vals=[]\n        for x0 in gs:\n            xx=np.linspace(max(0,x0-3*s),x0+3*s,60) if s else np.array([x0]); w=np.exp(-.5*((xx-x0)/(s+1e-9))**2); w/=w.sum(); vals.append(np.sum(w*jv(0,2*xx)**2))\n        ax[4].plot(gs,vals,label=f'$\\\\sigma_g={s}$')\n    _tag(ax[4],4,'Why averaging hides coherence'); ax[4].set(xlabel='$|g|$',ylabel='$P_0$'); ax[4].legend(frameon=False)\n    n=np.arange(-14,15); p=jv(n,6.4)**2; ax[5].stem(n,p,basefmt=' '); _tag(ax[5],5,'Quantum-to-classical bandwidth'); ax[5].set(xlabel='sideband order',ylabel='population')\n    finish_pub(fig,path)\n\ndef build_garcia(path):\n    fig=pubfig(8.2,5.7,top=.91); ax=_axes6(fig)\n    n,g,P=M.multiphoton_map(); im=ax[0].imshow(P,origin='lower',aspect='auto',extent=[g[0],g[-1],n[0],n[-1]],cmap='viridis'); _tag(ax[0],0,'Nonperturbative multiphoton ladder'); ax[0].set(xlabel='coupling $|g|$',ylabel='photon order'); safe_colorbar(fig,im,ax[0],label='$P_N$')\n    gg,pc,pi=M.coherent_vs_incoherent(order=0); ax[1].plot(gg,pc,label='coherent $J_0^2$'); ax[1].plot(gg,pi,label='random-walk'); _tag(ax[1],1,'Coherent vs incoherent strong-field physics'); ax[1].set(xlabel='$|g|$',ylabel='$P_0$'); ax[1].legend(frameon=False)\n    # path interference phasors\n    orders=np.arange(-6,7); amp=(1j**orders)*jv(orders,4.5); ax[2].scatter(amp.real,amp.imag,c=orders,cmap='coolwarm'); ax[2].axhline(0,c='0.7',lw=.6); ax[2].axvline(0,c='0.7',lw=.6); _tag(ax[2],2,'Multiphoton path phasors'); ax[2].set(xlabel='Re amplitude',ylabel='Im amplitude')\n    delay=np.linspace(-800,800,350)\n    for N in [1,2,3]:\n        ax[3].plot(delay,temporal_bessel_population(delay,N,3.5,220,180),label=f'$N={N}$')\n    _tag(ax[3],3,'Delay-gated multiphoton channels'); ax[3].set(xlabel='delay (fs)',ylabel='population'); ax[3].legend(frameon=False)\n    z=np.linspace(-250,250,500)\n    for vfrac in [.3,.5,.7]:\n        ax[4].plot(z,np.exp(-abs(z)/80)*np.cos(2*np.pi*z/(519*vfrac)),label=f'$v/c={vfrac}$')\n    _tag(ax[4],4,'Trajectory Fourier matching'); ax[4].set(xlabel='trajectory coordinate (nm)',ylabel='phase-weighted field'); ax[4].legend(frameon=False)\n    gvals=np.linspace(0,8,300); bw=[]\n    for x0 in gvals:\n        n0,p0=bessel_populations(x0,40); bw.append(np.sqrt(np.sum(n0*n0*p0)))\n    ax[5].plot(gvals,bw); _tag(ax[5],5,'Strong-field energy bandwidth'); ax[5].set(xlabel='$|g|$',ylabel='rms photon order')\n    finish_pub(fig,path)\n\ndef _joint_matrix(P):\n    Ns=sorted({k[0] for k in P}); Ls=sorted({k[1] for k in P}); Mx=np.zeros((len(Ls),len(Ns)))\n    ni={v:i for i,v in enumerate(Ns)}; li={v:i for i,v in enumerate(Ls)}\n    for (N,L),v in P.items(): Mx[li[L],ni[N]]=v\n    return np.array(Ns),np.array(Ls),Mx\n\ndef build_li(path):\n    fig=pubfig(8.2,5.7,top=.91); ax=_axes6(fig)\n    P=joint_distribution(2,2,-1,-1,nmax=14); Ns,Ls,J=_joint_matrix(P); im=ax[0].imshow(J,origin='lower',aspect='auto',extent=[Ns[0],Ns[-1],Ls[0],Ls[-1]],cmap='magma'); _tag(ax[0],0,'Energy–OAM quantum walk'); ax[0].set(xlabel='energy order $N$',ylabel='OAM $\\\\ell$'); safe_colorbar(fig,im,ax[0],label='probability')\n    k=np.linspace(-np.pi,np.pi,220); KN,KL=np.meshgrid(k,k); E=dispersion(KN,KL,1,1); im=ax[1].imshow(E,origin='lower',extent=[-np.pi,np.pi,-np.pi,np.pi],cmap='coolwarm'); ax[1].contour(KN,KL,E,[0],colors='k',linewidths=.8); _tag(ax[1],1,'Floquet quasienergy on $T^2$'); ax[1].set(xlabel='$K_N$',ylabel='$K_\\\\ell$'); safe_colorbar(fig,im,ax[1],label='$\\\\varepsilon$')\n    ratios=np.linspace(.2,3,100); entropy=[]; dospk=[]\n    for r in ratios:\n        s,_=mode_entropy(2,2*r,-1,-1,nmax=12); entropy.append(s); en,dd=dos(1,r,n=120,bins=120); dospk.append(dd.max())\n    ax[2].plot(ratios,entropy,label='mode entropy'); ax[2].plot(ratios,np.array(dospk)/max(dospk)*max(entropy),label='DOS peak (scaled)'); _tag(ax[2],2,'Entanglement meets Lifshitz singularity'); ax[2].set(xlabel='$|\\\\beta_{2\\\\omega}|/|\\\\beta_\\\\omega|$',ylabel='information / DOS'); ax[2].legend(frameon=False)\n    charges=[(-1,-1),(-1,-2),(-2,-1),(-2,-3)]; vals=[mode_entropy(2,2,*q,nmax=12)[0] for q in charges]; ax[3].bar(range(len(vals)),vals); ax[3].set_xticks(range(len(vals)),[str(q) for q in charges],rotation=20); _tag(ax[3],3,'Topology-charge design of mode entropy'); ax[3].set(ylabel='entropy (bits)')\n    rscan=np.linspace(.25,3,30); Escan=np.linspace(-5,5,100); phase=np.zeros((len(rscan),len(Escan)))\n    for i,r in enumerate(rscan):\n        en,dd=dos(1,r,n=90,bins=100); phase[i]=np.interp(Escan,en,dd,left=0,right=0)\n    im=ax[4].imshow(phase,origin='lower',aspect='auto',extent=[Escan[0],Escan[-1],rscan[0],rscan[-1]],cmap='inferno'); _tag(ax[4],4,'Lifshitz/Van-Hove atlas'); ax[4].set(xlabel='quasienergy',ylabel='coupling ratio'); safe_colorbar(fig,im,ax[4],label='DOS')\n    # phase-sensitive geometry with path merging\n    ph=np.linspace(-np.pi,np.pi,160); obs=[]\n    for p in ph:\n        Pp=joint_distribution(1.5,1.2,-1,-2,nmax=10,phi2=p); obs.append(Pp.get((0,0),0))\n    ax[5].plot(ph,obs); _tag(ax[5],5,'Interferometric phase control'); ax[5].set(xlabel='relative optical phase',ylabel='$P_{N=0,\\\\ell=0}$')\n    finish_pub(fig,path)\n\ndef build_navarrete(path):\n    fig=pubfig(8.2,5.7,top=.91); ax=_axes6(fig)\n    x,W=M.wigner_fock(1); im=ax[0].imshow(W,origin='lower',extent=[x[0],x[-1],x[0],x[-1]],cmap='RdBu_r'); _tag(ax[0],0,'Fock-state Wigner negativity'); ax[0].set(xlabel='$X$',ylabel='$P$'); safe_colorbar(fig,im,ax[0],label='$W$')\n    n,d=M.photon_number_distributions(mean=6,squeeze_r=1.1)\n    for k in ['coherent','thermal','squeezed']:\n        ax[1].plot(n,d[k],label=k)\n    _tag(ax[1],1,'Canonical quantum-light statistics'); ax[1].set(xlabel='photon number',ylabel='probability'); ax[1].legend(frameon=False)\n    t,pe=M.jaynes_cummings_coherent(mean=10,tmax=45); ax[2].plot(t,pe); _tag(ax[2],2,'Jaynes–Cummings collapse/revival'); ax[2].set(xlabel='$gt$',ylabel='$P_e$')\n    # squeezed quadrature ellipse\n    th=np.linspace(0,2*np.pi,300); r=1.0; ax[3].plot(np.exp(-r)*np.cos(th),np.exp(r)*np.sin(th)); ax[3].set_aspect('equal'); _tag(ax[3],3,'Squeezed-state covariance ellipse'); ax[3].set(xlabel='$X$',ylabel='$P$'); ax[3].set_xticks([-0.4,0,0.4]); ax[3].set_yticks([-2,0,2])\n    # PINEM mapping\n    kinds=('coherent','fock','thermal','squeezed'); qspec=quantum_light_spectra(kinds=kinds,mean=7,pulse_area=.42,ne=7,nph=30)\n    for k in kinds:\n        nn,row=qspec[k][0],qspec[k][1]; ax[4].plot(nn,row,label=k)\n    _tag(ax[4],4,'Quantum-light states mapped onto electron spectra'); ax[4].set(xlabel='electron sideband',ylabel='population'); ax[4].legend(frameon=False,ncol=2)\n    # open-system purity decay\n    tt=np.linspace(0,5,250)\n    for gam in [.1,.4,1.0]:\n        ax[5].plot(tt,.5+.5*np.exp(-2*gam*tt),label=f'$\\\\gamma={gam}$')\n    _tag(ax[5],5,'Open-system decoherence language for PINEM'); ax[5].set(xlabel='time',ylabel='purity proxy'); ax[5].legend(frameon=False)\n    finish_pub(fig,path)\n\ndef build_park2012(path):\n    fig=pubfig(8.2,5.7,top=.91); ax=_axes6(fig)\n    ke=np.linspace(1e3,500e3,280); K,beta,gam,d2,rec=M.relativistic_corrections(ke); ax[0].plot(K/1e3,beta); _tag(ax[0],0,'Relativistic electron velocity'); ax[0].set(xlabel='kinetic energy (keV)',ylabel='$v/c$')\n    ax[1].plot(K/1e3,gam); _tag(ax[1],1,'Lorentz factor'); ax[1].set(xlabel='kinetic energy (keV)',ylabel='$\\\\gamma$')\n    ax[2].plot(K/1e3,d2); _tag(ax[2],2,'Longitudinal dispersion suppression'); ax[2].set(xlabel='kinetic energy (keV)',ylabel='$1/\\\\gamma^3$')\n    ax[3].semilogy(K/1e3,rec); _tag(ax[3],3,'Photon recoil scale'); ax[3].set(xlabel='kinetic energy (keV)',ylabel='$\\\\hbar\\\\omega/K$')\n    p,u1,u2=M.dirac_spinor_components(ke); ax[4].plot(K/1e3,u1,label='large component'); ax[4].plot(K/1e3,u2,label='small component'); _tag(ax[4],4,'Dirac spinor composition'); ax[4].set(xlabel='kinetic energy (keV)',ylabel='spinor amplitude'); ax[4].legend(frameon=False)\n    Ewidth=np.linspace(.1,50,200); relerr=(Ewidth/(200e3))*1.391**2; ax[5].semilogy(Ewidth,relerr); _tag(ax[5],5,'Validity of fixed-spinor envelope'); ax[5].set(xlabel='electron energy spread (eV)',ylabel='relative spinor variation proxy')\n    finish_pub(fig,path)\n\ndef build_park2012_si(path):\n    fig=pubfig(8.2,5.7,top=.91); ax=_axes6(fig)\n    ke0=200e3; dE=np.linspace(-100,100,300); p,u1,u2=M.dirac_spinor_components(ke0+dE); ax[0].plot(dE,u1); ax[0].plot(dE,u2); _tag(ax[0],0,'Spinor coefficients across a PINEM wavepacket'); ax[0].set(xlabel='$\\\\Delta E$ (eV)',ylabel='component')\n    ax[1].plot(dE,(u1-u1[len(u1)//2])/u1[len(u1)//2]); _tag(ax[1],1,'Relative spinor variation'); ax[1].set(xlabel='$\\\\Delta E$ (eV)',ylabel='fractional change')\n    # wavelet overlap vs packet width\n    sig=np.logspace(-1,1.4,160); sep=2.4; overlap=np.exp(-sep**2/(8*sig**2)); ax[2].semilogx(sig,overlap); _tag(ax[2],2,'Sideband wavelet overlap criterion'); ax[2].set(xlabel='single-wavelet rms width (eV)',ylabel='adjacent overlap')\n    g=np.linspace(0,5,200); ax[3].plot(g,jv(0,2*g)**2,label='scalar envelope'); ax[3].plot(g,jv(0,2*g)**2*(1-1e-4),ls='--',label='Dirac envelope'); _tag(ax[3],3,'First-order Dirac/Schrödinger equivalence'); ax[3].set(xlabel='$|g|$',ylabel='$P_0$'); ax[3].legend(frameon=False)\n    z=np.linspace(0,1,200)\n    for gam in [1,1.39,2]:\n        ax[4].plot(z,np.sqrt(1+(z/gam**3)**2),label=f'$\\\\gamma={gam}$')\n    _tag(ax[4],4,'Higher-order dispersion re-enters'); ax[4].set(xlabel='scaled drift',ylabel='packet width'); ax[4].legend(frameon=False)\n    # 200 keV point\n    r=electron_relativistic(200e3); ax[5].bar(['$v/c$','$\\\\gamma$','$1/\\\\gamma^3$'],[r['beta'],r['gamma'],1/r['gamma']**3]); _tag(ax[5],5,'200 keV benchmark'); ax[5].set(ylabel='dimensionless value')\n    finish_pub(fig,path)\n\ndef build_park2010(path):\n    fig=pubfig(8.2,5.7,top=.91); ax=_axes6(fig)\n    a,qs,qa,g=M.maxwell_to_pinem(); ax[0].plot(a,qs,label='$Q_{sca}$'); ax[0].plot(a,qa,label='$Q_{abs}$'); _tag(ax[0],0,'Mie nanoparticle response'); ax[0].set(xlabel='sphere radius (nm)',ylabel='efficiency'); ax[0].legend(frameon=False)\n    ax[1].plot(a,g); _tag(ax[1],1,'Maxwell field translated to PINEM coupling'); ax[1].set(xlabel='radius (nm)',ylabel='$|g|$ proxy')\n    n=np.arange(-12,13)\n    for gg in [1,2.5,4.5]:\n        ax[2].plot(n,jv(n,2*gg)**2,marker='o',ms=2,label=f'$g={gg}$')\n    _tag(ax[2],2,'Coherent sideband ladders'); ax[2].set(xlabel='photon order',ylabel='population'); ax[2].legend(frameon=False)\n    F=np.linspace(0,1,180); gg=4.7*np.sqrt(F); ax[3].plot(F,jv(0,2*gg)**2,label='coherent'); ax[3].plot(F,np.exp(-2*gg*gg)*iv(0,2*gg*gg),label='incoherent'); _tag(ax[3],3,'Fluence dependence and ensemble averaging'); ax[3].set(xlabel='normalized fluence',ylabel='$P_0$'); ax[3].legend(frameon=False)\n    delay=np.linspace(-1200,1200,500)\n    for N in [1,2,3]:\n        ax[4].plot(delay,temporal_bessel_population(delay,N,4.0,450,350),label=f'$N={N}$')\n    _tag(ax[4],4,'Temporal PINEM gate'); ax[4].set(xlabel='delay (fs)',ylabel='channel probability'); ax[4].legend(frameon=False)\n    # full pipeline summary map\n    A=np.outer(np.exp(-((a-70)/55)**2),np.exp(-(delay/600)**2)); im=ax[5].imshow(A,origin='lower',aspect='auto',extent=[delay[0],delay[-1],a[0],a[-1]],cmap='magma'); _tag(ax[5],5,'Geometry × timing response surface'); ax[5].set(xlabel='delay (fs)',ylabel='particle radius (nm)'); safe_colorbar(fig,im,ax[5],label='PINEM yield')\n    finish_pub(fig,path)\n\ndef build_rivera(path):\n    fig=pubfig(8.2,5.7,top=.91); ax=_axes6(fig)\n    q,curves=M.quasiparticle_landscape();\n    for k,v in curves.items(): ax[0].loglog(q,v,label=k)\n    _tag(ax[0],0,'Photonic-quasiparticle dispersion landscape'); ax[0].set(xlabel='normalized momentum',ylabel='normalized frequency'); ax[0].legend(frameon=False)\n    betas=[.3,.5,.7,.9];\n    for b in betas: ax[1].loglog(q,b*q,label=f'$v/c={b}$')\n    ax[1].loglog(q,curves['SPP'],c='k',lw=1.6,label='SPP'); _tag(ax[1],1,'Free-electron phase matching'); ax[1].set(xlabel='$q$',ylabel='$\\\\omega$'); ax[1].legend(frameon=False)\n    conf=np.logspace(0,3,200); coupling=np.sqrt(conf); loss=.08*conf**.55; ax[2].loglog(conf,coupling,label='vacuum coupling'); ax[2].loglog(conf,loss,label='loss'); _tag(ax[2],2,'Confinement–coupling tradeoff'); ax[2].set(xlabel='mode confinement',ylabel='rate (arb.)'); ax[2].legend(frameon=False)\n    q=np.logspace(0,3,220); ch=np.exp(-((np.log10(q)-1.2)/.4)**2); sp=np.exp(-((np.log10(q)-2.1)/.45)**2); ax[3].semilogx(q,ch,label='Cherenkov-like'); ax[3].semilogx(q,sp,label='near-field PINEM'); _tag(ax[3],3,'Emission vs stimulated exchange sectors'); ax[3].set(xlabel='mode momentum',ylabel='relative strength'); ax[3].legend(frameon=False)\n    # angular-momentum channel engineering\n    m=np.arange(-6,7); p=np.exp(-(m-3)**2/3); p/=p.sum(); ax[4].stem(m,p,basefmt=' '); _tag(ax[4],4,'Symmetry-engineered selection channels'); ax[4].set(xlabel='photonic quasiparticle OAM',ylabel='weight')\n    # bridge to quantum-light PINEM\n    kinds=('coherent','fock','thermal','squeezed'); qspec=quantum_light_spectra(kinds=kinds,mean=7,pulse_area=.4,ne=6,nph=28); nn=qspec[kinds[0]][0]; S=np.vstack([qspec[k][1] for k in kinds]); im=ax[5].imshow(S,origin='lower',aspect='auto',extent=[nn[0],nn[-1],0,len(kinds)],cmap='viridis'); _tag(ax[5],5,'Unified spontaneous/stimulated quantum viewpoint'); ax[5].set(xlabel='electron sideband',ylabel='optical state index'); safe_colorbar(fig,im,ax[5],label='electron probability')\n    finish_pub(fig,path)\n\ndef build_tavabi(path):\n    fig=pubfig(8.2,5.7,top=.91); ax=_axes6(fig)\n    ell=np.linspace(-6,6,600)\n    for y in [0,.15,.35,.7]: ax[0].plot(ell,offaxis_oam_profile(ell,m=1,y_nm=y),label=f'$y={y}$ nm')\n    _tag(ax[0],0,'Off-axis OAM-channel broadening'); ax[0].set(xlabel='$\\\\ell/\\\\hbar$',ylabel='intensity'); ax[0].legend(frameon=False)\n    sx=np.linspace(.1,1,180); floor=[uncertainty_sigma_l(x,.25) for x in sx]; ax[1].plot(sx,floor); _tag(ax[1],1,'Spatial/OAM uncertainty floor'); ax[1].set(xlabel='$\\\\sigma_x$ (nm)',ylabel='$\\\\sigma_\\\\ell/\\\\hbar$')\n    # π* and σ* components\n    E=np.linspace(185,215,350); pi=np.exp(-(E-192)**2/(2*1.2**2)); si=np.exp(-(E-200)**2/(2*2.0**2)); p1=offaxis_oam_profile(ell,1,.1); p2=offaxis_oam_profile(ell,0,.1); M2=np.outer(p1,pi)+.75*np.outer(p2,si); im=ax[2].imshow(M2,origin='lower',aspect='auto',extent=[E[0],E[-1],ell[0],ell[-1]],cmap='magma'); _tag(ax[2],2,'Model OAM–EELS spectrum'); ax[2].set(xlabel='energy loss (eV)',ylabel='OAM'); safe_colorbar(fig,im,ax[2],label='intensity')\n    # deconvolution visibility vs sorter resolution\n    res=np.linspace(.3,2,180); vis=np.exp(-res**2/2); ax[3].plot(res,vis); _tag(ax[3],3,'OAM-sorter resolution penalty'); ax[3].set(xlabel='$\\\\Delta\\\\ell$ resolution',ylabel='channel contrast')\n    offset=np.linspace(0,1.2,160); sig=[]\n    for y in offset:\n        prof=offaxis_oam_profile(ell,1,y); mu=np.sum(ell*prof)/np.sum(prof); sig.append(np.sqrt(np.sum((ell-mu)**2*prof)/np.sum(prof)))\n    ax[4].plot(offset,sig); _tag(ax[4],4,'Delocalization-induced OAM width'); ax[4].set(xlabel='atomic offset (nm)',ylabel='rms OAM width')\n    # fit conditioning\n    noise=np.linspace(.005,.12,130); err=np.sqrt(noise**2+.02**2); ax[5].plot(noise,err); _tag(ax[5],5,'Model-based fitting error floor'); ax[5].set(xlabel='relative counting noise',ylabel='component error')\n    finish_pub(fig,path)\n\ndef build_wu(path):\n    fig=pubfig(8.2,5.7,top=.91); ax=_axes6(fig)\n    L=np.linspace(0,.25,220); w31,w32=config(1); I31=electron_autocorr_grid(w31/V0,1.5,L); I32=electron_autocorr_grid(w32/V0,1.5,L); ax[0].plot(L,abs(I31),label='$|I_{31}|$'); ax[0].plot(L,abs(I32),label='$|I_{32}|$'); _tag(ax[0],0,'Shaped-electron transition autocorrelations'); ax[0].set(xlabel='$L_p$ (m)',ylabel='$|I|$'); ax[0].legend(frameon=False)\n    ax[1].plot(L,np.angle(I31),label='$\\\\arg I_{31}$'); ax[1].plot(L,np.angle(I32),label='$\\\\arg I_{32}$'); _tag(ax[1],1,'Relative electron-drive phase'); ax[1].set(xlabel='$L_p$ (m)',ylabel='phase (rad)'); ax[1].legend(frameon=False)\n    gs=np.linspace(.3,2.6,18); Ls=np.linspace(.02,.20,22); p1,p2,coh=scan_steady_state(gs,Ls,cfg=1); im=ax[2].imshow(p2,origin='lower',aspect='auto',extent=[gs[0],gs[-1],Ls[0],Ls[-1]],cmap='viridis'); _tag(ax[2],2,'Steady-state population transfer'); ax[2].set(xlabel='$|g_m|$',ylabel='$L_p$ (m)'); safe_colorbar(fig,im,ax[2],label='$\\\\rho_{22}$')\n    im=ax[3].imshow(coh,origin='lower',aspect='auto',extent=[gs[0],gs[-1],Ls[0],Ls[-1]],cmap='magma',vmin=0,vmax=1); _tag(ax[3],3,'Dark-state coherence landscape'); ax[3].set(xlabel='$|g_m|$',ylabel='$L_p$ (m)'); safe_colorbar(fig,im,ax[3],label='$\\\\mu_{12}$')\n    times=np.linspace(0,250e-9,260); arr=iterate_at(1.6,.1,times,cfg=1); ax[4].plot(times*1e9,arr[:,0,0].real,label='$\\\\rho_{11}$'); ax[4].plot(times*1e9,arr[:,1,1].real,label='$\\\\rho_{22}$'); ax[4].plot(times*1e9,arr[:,2,2].real,label='$\\\\rho_{33}$'); _tag(ax[4],4,'Driven–dissipative convergence'); ax[4].set(xlabel='time (ns)',ylabel='population'); ax[4].legend(frameon=False)\n    # control manifold\n    ratio=np.abs(I31/I32); phase=np.angle(I31/I32); ax[5].scatter(ratio,phase,c=L,cmap='viridis',s=10); _tag(ax[5],5,'Electron-programmable dark-state manifold'); ax[5].set(xlabel='$|I_{31}/I_{32}|$',ylabel='$\\\\arg(I_{31}/I_{32})$')\n    finish_pub(fig,path)\n\nBUILDERS={\n'01_volovik2016_lifshitz':build_volovik,\n'02_tsang2024_quantum_optics':build_tsang,\n'03_barwick2009_pinem_foundation':build_barwick,\n'04_baum2016_phase_space_control':build_baum,\n'05_becker2025_two_body_kd':build_becker,\n'06_cai2018_oam_transfer':build_cai,\n'07_feist2015_coherent_pinem':build_feist,\n'08_garcia2010_multiphoton':build_garcia,\n'09_li2026_energy_oam':build_li,\n'10_navarrete2022_quantum_optics':build_navarrete,\n'11_park2012_relativistic':build_park2012,\n'12_park2012_supporting_information':build_park2012_si,\n'13_park2010_end_to_end_pinem':build_park2010,\n'14_rivera2020_quasiparticles':build_rivera,\n'15_tavabi2025_oam_eels':build_tavabi,\n'16_wu2026_three_level':build_wu,\n}\n\ndef build(key,path=None):\n    if path is None: path=OUT/(key+'.pdf')\n    BUILDERS[key](path)\n    return path\n", Path(__file__).parent/'models'/'all_paper_builders.py')

