_mod=_install_module('models.source_builders.cai2018', "import os,sys\nROOT=os.path.dirname(os.path.dirname(os.path.dirname(__file__)))\nsys.path.insert(0,ROOT)\nimport numpy as np\nimport matplotlib.pyplot as plt\nfrom matplotlib.gridspec import GridSpec\nfrom models.cai2018 import *\nfrom preamble import panel,clean,save\nOUT=ROOT\n\ndef complex_image(ax,ell,m,eta,fwhm=30,lim=18,N=301):\n    x=np.linspace(-lim,lim,N); X,Y=np.meshgrid(x,x); R=np.hypot(X,Y); PH=np.arctan2(Y,X)\n    W=image_wave(R,PH,ell,m,eta,fwhm); I=abs(W)**2\n    ax.imshow(np.angle(W),extent=[-lim,lim,-lim,lim],origin='lower',cmap='hsv',vmin=-np.pi,vmax=np.pi,alpha=np.clip(I/I.max(),0,1))\n    ax.contour(X,Y,I/I.max(),levels=[.05,.25,.6],colors='k',linewidths=.35,alpha=.55)\n    ax.set(xticks=[],yticks=[],xlim=(-lim,lim),ylim=(-lim,lim),aspect='equal')\n\ndef far_image(ax,ell,m,eta,fwhm=30,qmax=1.8,Nq=250):\n    q=np.linspace(0,qmax,220); F=far_radial(q,ell,m,eta,fwhm,rmax=75,nr=1800)\n    x=np.linspace(-qmax,qmax,Nq); X,Y=np.meshgrid(x,x); Q=np.hypot(X,Y); PH=np.arctan2(Y,X)\n    amp=np.interp(Q,q,abs(F),left=0,right=0)*np.exp(1j*ell*m*PH)\n    I=abs(amp)**2\n    ax.imshow(np.angle(amp),extent=[-qmax,qmax,-qmax,qmax],origin='lower',cmap='hsv',vmin=-np.pi,vmax=np.pi,alpha=np.clip(I/I.max(),0,1))\n    ax.contour(X,Y,I/I.max(),levels=[.08,.35,.7],colors='k',linewidths=.35,alpha=.55)\n    ax.set(xticks=[],yticks=[],aspect='equal')\n\ndef fig1():\n    fig=plt.figure(figsize=(7.05,2.45)); gs=GridSpec(1,3,figure=fig,wspace=.16)\n    ax=fig.add_subplot(gs[0]); panel(ax,'(a)',-.08,1.02)\n    xx=np.linspace(-2.7,2.7,300); ax.plot(xx,.36*np.cos(2*np.pi*xx/1.1),'k',lw=.8); ax.axhline(0,color='.55',lw=3)\n    for y in [-.45,.45]: ax.annotate('',(2.3,y),(-2.3,y),arrowprops=dict(arrowstyle='->',lw=1))\n    ax.text(-2.55,.60,'Gaussian electron'); ax.text(-2.55,-.72,'vortex plasmon'); ax.set(xlim=(-2.8,2.8),ylim=(-1,1)); ax.axis('off')\n    for j,title in [(1,'image plane'),(2,'Fourier plane')]:\n        ax=fig.add_subplot(gs[j]); panel(ax,f'({chr(97+j)})',-.08,1.02)\n        (complex_image if j==1 else far_image)(ax,1,1,2.5)\n        ax.set_title(title,pad=3)\n    save(fig,os.path.join(OUT,'source_reconstructions__cai2018_fig01.pdf'))\n\ndef _surface_real(ax,ell,m,eta=2.5,fwhm=30.0,lim=20.0,N=81):\n    from matplotlib import cm, colors\n    x=np.linspace(-lim,lim,N); X,Y=np.meshgrid(x,x); R=np.hypot(X,Y); PH=np.arctan2(Y,X)\n    W=image_wave(R,PH,ell,m,eta,fwhm); Z=np.abs(W)**2\n    if Z.max()>0: Z=Z/Z.max()\n    phase=(np.angle(W)+np.pi)/(2*np.pi)\n    fc=cm.twilight(phase)\n    ax.plot_surface(X,Y,Z,facecolors=fc,rstride=2,cstride=2,linewidth=0,antialiased=True,shade=False)\n    ax.set(xlim=(-lim,lim),ylim=(-lim,lim),zlim=(0,1.08)); ax.set_axis_off(); ax.view_init(elev=30,azim=-55)\n    try: ax.set_box_aspect((1,1,.62))\n    except Exception: pass\n\n\ndef _surface_far(ax,ell,m,eta=2.5,fwhm=30.0,qmax=2.2,N=81):\n    from matplotlib import cm\n    q=np.linspace(0,qmax,260); F=far_radial(q,ell,m,eta,fwhm,rmax=75,nr=2000)\n    x=np.linspace(-qmax,qmax,N); X,Y=np.meshgrid(x,x); Q=np.hypot(X,Y); PH=np.arctan2(Y,X)\n    Fr=np.interp(Q,q,np.abs(F),left=0,right=0)\n    W=Fr*np.exp(1j*ell*m*PH); Z=np.abs(W)**2\n    if Z.max()>0: Z=Z/Z.max()\n    fc=cm.twilight((np.angle(W)+np.pi)/(2*np.pi))\n    ax.plot_surface(X,Y,Z,facecolors=fc,rstride=2,cstride=2,linewidth=0,antialiased=True,shade=False)\n    ax.set(xlim=(-qmax,qmax),ylim=(-qmax,qmax),zlim=(0,1.08)); ax.set_axis_off(); ax.view_init(elev=30,azim=-55)\n    try: ax.set_box_aspect((1,1,.62))\n    except Exception: pass\n\n\ndef fig3():\n    # Paper Fig. 3: rows are ell=1,2,5; columns are real/Fourier planes for m=1 and m=10.\n    # Heights are normalized within each panel for shape visibility; phase is encoded cyclically.\n    # The printed numerical labels are the published peak relative intensities.\n    ells=[1,2,5]\n    labels=[[r'$0.34$',r'$8.2\\times10^3$',r'$0.21$',r'$7.1\\times10^3$'],\n            [r'$0.23$',r'$836.9$',r'$0.036$',r'$106.8$'],\n            [r'$1.4\\times10^{-7}$',r'$0.027$',r'$2.3\\times10^{-6}$',r'$6.73\\times10^{-4}$']]\n    fig=plt.figure(figsize=(7.15,5.05))\n    gs=GridSpec(3,4,figure=fig,wspace=.01,hspace=.02,left=.055,right=.995,bottom=.035,top=.91)\n    for r,ell in enumerate(ells):\n        for c,(m,kind) in enumerate([(1,'real'),(1,'fourier'),(10,'real'),(10,'fourier')]):\n            ax=fig.add_subplot(gs[r,c],projection='3d')\n            if kind=='real': _surface_real(ax,ell,m,lim=20 if m==1 else 25)\n            else: _surface_far(ax,ell,m,qmax=2.3)\n            ax.text2D(.03,.91,labels[r][c],transform=ax.transAxes,fontsize=6.5,\n                      bbox=dict(facecolor='white',edgecolor='none',alpha=.72,pad=.5))\n            if c==0:\n                ax.text2D(-.10,.50,rf'$\\ell={ell}$',transform=ax.transAxes,rotation=90,va='center',fontsize=8)\n    fig.text(.265,.965,r'$m=1$',ha='center',fontsize=8)\n    fig.text(.745,.965,r'$m=10$',ha='center',fontsize=8)\n    for x0,txt in [(.145,'real plane'),(.385,'Fourier plane'),(.625,'real plane'),(.865,'Fourier plane')]:\n        fig.text(x0,.932,txt,ha='center',fontsize=7)\n    save(fig,os.path.join(OUT,'source_reconstructions__cai2018_fig03.pdf'))\n\ndef fig4():\n    rho=np.linspace(0,20,900)\n    fig,axs=plt.subplots(3,1,figsize=(4.25,4.55),sharex=True,gridspec_kw={'hspace':.055,'left':.13,'right':.98,'bottom':.11,'top':.98})\n    cols=['#0072B2','#D55E00','#E69F00','#CC79A7']\n    for ax,eta in zip(axs,[1,5,20]):\n        for ell,c in zip(range(4),cols):\n            ax.plot(rho,radial_probability_contribution(rho,ell,1,eta,30),color=c,lw=1.0,label=rf'$\\ell={ell}$')\n        ax.plot(rho,radial_envelope(rho,30),color='#4D9221',lw=1.15,label='Envelope')\n        ax.text(.53,.58,rf'$\\eta={eta}$',transform=ax.transAxes,fontsize=8)\n        ax.set_ylim(0,1.03); ax.set_yticks([0,.5,1]); clean(ax)\n    axs[1].set_ylabel(r'Intensity $|\\phi_0 f_\\ell|^2$')\n    axs[-1].set_xlabel(r'$2\\pi R/\\lambda_p$')\n    axs[0].legend(frameon=True,fontsize=6,loc='upper right',ncol=1,borderpad=.25,labelspacing=.2)\n    save(fig,os.path.join(OUT,'source_reconstructions__cai2018_fig04.pdf'))\n\ndef fig5():\n    # Paper Fig. 5 uses different beam-width windows in the longitudinal-current (left)\n    # and azimuthal/longitudinal-ratio (right) panels.\n    eta=np.linspace(.2,20,78); widths_z=np.linspace(2,100,92); widths_phi=np.linspace(.5,10,78)\n    fig,axs=plt.subplots(2,2,figsize=(5.05,4.25),gridspec_kw={'wspace':.48,'hspace':.28,'left':.10,'right':.92,'bottom':.11,'top':.98})\n    for row,(m,ell) in enumerate([(1,1),(10,5)]):\n        z,_=currents(eta,widths_z,ell,m,nr=900)\n        _,r=currents(eta,widths_phi,ell,m,nr=900)\n        for col,(data,widths) in enumerate([(z,widths_z),(np.log10(np.maximum(np.abs(r),1e-6)),widths_phi)]):\n            ax=axs[row,col]; im=ax.imshow(data,origin='lower',aspect='auto',extent=[widths.min(),widths.max(),eta.min(),eta.max()],cmap='turbo',interpolation='bilinear')\n            ax.text(.94,.92,f'({chr(97+2*row+col)})',transform=ax.transAxes,ha='right',va='top',color='white',fontsize=8)\n            ax.text(.13,.72,f'$m={m}$\\n$\\\\ell={ell}$',transform=ax.transAxes,color='white',fontsize=8)\n            ax.set_ylabel(r'Coupling efficiency $\\eta$',fontsize=7); ax.set_xlabel(r'$2\\pi\\Delta/\\lambda_p$',fontsize=7)\n            ax.tick_params(labelsize=6.2,pad=1.5); clean(ax)\n            cb=fig.colorbar(im,ax=ax,pad=.025,fraction=.055); cb.ax.tick_params(labelsize=6,pad=1)\n            # color scale meaning is encoded by column and documented in FIGURE_CATALOG.md\n    save(fig,os.path.join(OUT,'source_reconstructions__cai2018_fig05.pdf'))\n\nif __name__=='__main__':\n    fig1(); fig3(); fig4(); fig5()\n\ndef fig2():\n    # Full retarded short-range TM mode of a free-standing Ag film.  Ag response uses\n    # the Rakic Drude-Lorentz parametrization; the paper does not tabulate the optical dataset.\n    from scipy.constants import hbar,electron_volt,c,epsilon_0,e,m_e\n    from scipy.optimize import brentq\n    def eps_ag(E):\n        wp=9.01; f0=.845; G0=.048\n        pars=[(.065,.816,3.886),(.124,4.481,.452),(.011,8.185,.065),(.840,9.083,.916),(5.646,20.29,2.419)]\n        z=1-f0*wp**2/(E*(E+1j*G0))\n        for f,w,G in pars: z += f*wp**2/(w*w-E*E-1j*G*E)\n        return z\n    def lambda_spp(E,tnm):\n        er=eps_ag(E).real; k0=E*electron_volt/(hbar*c); t=tnm*1e-9\n        def fn(k):\n            kd=np.sqrt(k*k-k0*k0); km=np.sqrt(k*k-er*k0*k0)\n            return 1/np.tanh(km*t/2)+er*kd/km\n        ks=np.geomspace(k0*(1+1e-8),max(k0*1e5,1e11),700); old=fn(ks[0])\n        for a,b in zip(ks[:-1],ks[1:]):\n            fa,fb=fn(a),fn(b)\n            if fa*fb<0: return 2*np.pi/brentq(fn,a,b)\n        return np.nan\n    Eev=np.linspace(.5,3.0,170)\n    lam={t:np.array([lambda_spp(E,t) for E in Eev]) for t in [1,5]}\n    fig,axs=plt.subplots(2,1,figsize=(4.25,5.0),sharex=True,gridspec_kw={'hspace':.06,'left':.16,'right':.97,'bottom':.10,'top':.98})\n    for t,ls in [(1,'--'),(5,'-')]: axs[0].plot(Eev,lam[t]*1e6,color='k',ls=ls,lw=1.1,label=rf'$t={t}$ nm')\n    axs[0].set_ylabel(r'Plasmon wavelength $\\lambda_p$ ($\\mu$m)'); axs[0].set_ylim(0,2.0); axs[0].legend(frameon=True,fontsize=6,loc='upper right'); axs[0].text(.18,.83,'(a)',transform=axs[0].transAxes,fontsize=11.5)\n    # Thin-film geometry inset reproduced from the source figure.\n    ia=axs[0].inset_axes([.42,.50,.45,.34]); ia.set_xlim(0,1); ia.set_ylim(0,1); ia.axis('off')\n    ia.add_patch(plt.Rectangle((.10,.37),.80,.16,fc='#B7B7B7',ec='none'))\n    ia.text(.86,.55,'Ag',fontsize=6.4,ha='center')\n    ia.annotate('',(.28,.82),(.28,.55),arrowprops=dict(arrowstyle='-|>',lw=.8,color='red')); ia.text(.24,.85,r'$E_0$',color='red',fontsize=7)\n    xx=np.linspace(.48,.74,120); ia.plot(xx,.67+.08*np.sin(8*np.pi*(xx-.48)/(.26)),color='#67A9CF',lw=1.0)\n    ia.annotate('',(.50,.81),(.72,.81),arrowprops=dict(arrowstyle='<->',lw=.7)); ia.text(.61,.84,r'$\\lambda_p$',fontsize=7,ha='center')\n    ia.annotate('',(.18,.31),(.18,.59),arrowprops=dict(arrowstyle='<->',lw=.7)); ia.text(.14,.45,r'$t$',fontsize=7,ha='right',va='center')\n    I=1e13; Efield=np.sqrt(2*I/(c*epsilon_0)); colors={100:'k',1e3:'#D55E00',1e4:'#0072B2',1e5:'#CC00CC'}\n    for Ee in [100,1e3,1e4,1e5]:\n        gamma=1+Ee*electron_volt/(m_e*c*c); v=c*np.sqrt(1-gamma**-2)\n        for t,ls in [(1,'--'),(5,'-')]:\n            lp=lam[t]; w=Eev*electron_volt/hbar; Om=w*lp/(2*np.pi*v); gg=e*Efield*lp*gamma/(2*np.pi*hbar*w); eta=2*gg*Om/(1+Om**2)\n            axs[1].plot(Eev,np.real(eta),color=colors[Ee],ls=ls,lw=1.0,label=(rf'{Ee/1e3:g} KeV' if Ee>=1e3 else '100 eV') if t==5 else None)\n    axs[1].set_yscale('log'); axs[1].set_ylim(.02,30); axs[1].set_ylabel(r'Coupling strength $\\eta$'); axs[1].set_xlabel('Plasmon energy (eV)'); axs[1].text(.18,.82,'(b)',transform=axs[1].transAxes,fontsize=11.5); axs[1].text(.09,.12,r'$1$ GW/cm$^2$',transform=axs[1].transAxes,fontsize=8)\n    axs[1].legend(frameon=False,fontsize=6,loc='upper right')\n    for ax in axs: clean(ax)\n    save(fig,os.path.join(OUT,'source_reconstructions__cai2018_fig02.pdf'))\n\n", Path(__file__).parent/'models'/'source_builders'/'cai2018.py')
setattr(sys.modules['models.source_builders'], 'cai2018', _mod)

