_mod=_install_module('models.source_builders.li2026', "import os,sys\nROOT=os.path.dirname(os.path.dirname(os.path.dirname(__file__)))\nsys.path.insert(0,ROOT)\nimport numpy as np\nimport matplotlib.pyplot as plt\nfrom matplotlib.gridspec import GridSpec\nfrom models.li2026 import *\nfrom preamble import panel,clean,save\nOUT=ROOT\n\ndef lattice_points(b1,b2,l1,l2,nmax=7):\n    P=joint_distribution(b1,b2,l1,l2,nmax)\n    a=np.array([(N,L,p) for (N,L),p in P.items() if p>2e-4])\n    return a\n\ndef fig1():\n    # Paper Fig. 1: spectral collapse from the hidden (n1,n2) photon lattice to N=n1+2n2.\n    b1,b2=2.4,2.0; ns1=np.arange(-6,8); ns2=np.arange(-6,7)\n    P=np.array([[abs(coeff(int(n1),int(n2),b1,b2))**2 for n1 in ns1] for n2 in ns2])\n    P/=P.sum(); p1=P.sum(axis=0); p2=P.sum(axis=1)\n    fig=plt.figure(figsize=(4.75,7.05)); outer=GridSpec(4,1,figure=fig,height_ratios=[.72,2.25,1.65,1.20],hspace=.38,left=.13,right=.92,top=.98,bottom=.06)\n    # (a) free electron + two-color field schematic.\n    ax=fig.add_subplot(outer[0]); ax.text(-.08,1.02,'(a)',transform=ax.transAxes,fontsize=8)\n    ax.annotate('',(.90,.38),(.12,.38),arrowprops=dict(arrowstyle='->',lw=1.0,color='k')); ax.text(.07,.40,'Free electron',ha='left',va='bottom',fontsize=7)\n    xx=np.linspace(.42,.60,100)\n    ax.plot(xx,.72+.08*np.sin(18*np.pi*(xx-.42)),color='#D62728',lw=1.0); ax.text(.59,.80,r'$\\omega_1$',fontsize=7)\n    xx=np.linspace(.60,.78,100); ax.plot(xx,.72+.08*np.sin(24*np.pi*(xx-.60)),color='#1583C4',lw=1.0); ax.text(.78,.80,r'$\\omega_2$',fontsize=7)\n    ax.set(xlim=(0,1),ylim=(0,1)); ax.axis('off')\n    # (b) hidden 2D walk with top/right one-dimensional marginals.\n    gs=outer[1].subgridspec(2,2,height_ratios=[.34,1],width_ratios=[1,.26],hspace=.02,wspace=.03)\n    atop=fig.add_subplot(gs[0,0]); ar=fig.add_subplot(gs[1,1]); ax=fig.add_subplot(gs[1,0])\n    ax.text(-.22,1.20,'(b)',transform=ax.transAxes,fontsize=8,clip_on=False)\n    X,Y=np.meshgrid(ns1,ns2); vals=P.ravel();\n    \n    normy=plt.Normalize(Y.min(),Y.max()); rgba=plt.get_cmap('coolwarm')(normy(Y.ravel())); rgba[:,3]=.08+.92*(vals/vals.max())**.55\n    ax.scatter(X.ravel(),Y.ravel(),s=34,c=rgba,edgecolors='.45',linewidths=.2)\n    for y in ns2: ax.plot([ns1.min(),ns1.max()],[y,y],color='#B9B9B9',lw=.35,zorder=0)\n    for x in ns1: ax.plot([x,x],[ns2.min(),ns2.max()],color='#B9B9B9',lw=.35,zorder=0)\n    ax.set(xlabel=r'$n_1$ photon order',ylabel=r'$n_2$ photon order',xlim=(-6.6,7.6),ylim=(-6.6,6.6)); ax.set_xticks([-6,-3,0,3,6]); ax.set_yticks([-6,-3,0,3,6]); ax.tick_params(labelsize=6); clean(ax)\n    atop.vlines(ns1,0,p1,color='#E07000',lw=.9); atop.scatter(ns1,p1,s=8,color='#E07000'); atop.set_xlim(ax.get_xlim()); atop.set_ylim(0,p1.max()*1.25); atop.axis('off'); atop.text(.5,.83,'1D quantum walk',transform=atop.transAxes,ha='center',fontsize=7)\n    ar.hlines(ns2,0,p2,color='#4A4AB7',lw=.9); ar.scatter(p2,ns2,s=8,color='#4A4AB7'); ar.set_ylim(ax.get_ylim()); ar.set_xlim(0,p2.max()*1.25); ar.axis('off'); ar.text(.52,.50,'1D\\nquantum\\nwalk',transform=ar.transAxes,ha='center',va='center',fontsize=6)\n    # (c) same hidden lattice, constant-N diagonals and composite coordinate coloring.\n    ax=fig.add_subplot(outer[2]); ax.text(-.08,1.02,'(c)',transform=ax.transAxes,fontsize=8)\n    Ngrid=X+2*Y\n    normN=plt.Normalize(Ngrid.min(),Ngrid.max()); rgba=plt.get_cmap('Spectral')(normN(Ngrid.ravel())); rgba[:,3]=.08+.92*(vals/vals.max())**.55\n    ax.scatter(X.ravel(),Y.ravel(),s=32,c=rgba,edgecolors='.55',linewidths=.18,zorder=2)\n    for N in range(-16,17,2):\n        x=np.array([-7.0,8.0]); y=(N-x)/2; ax.plot(x,y,color='#AEBBAE',lw=.5,zorder=0)\n    ax.set(xlabel=r'$n_1$ photon order',ylabel=r'$n_2$ photon order',xlim=(-6.6,7.6),ylim=(-6.6,6.6)); ax.set_xticks([-6,-3,0,3,6]); ax.set_yticks([-6,-3,0,3,6]); ax.tick_params(labelsize=6); clean(ax)\n    ax.text(.98,.90,'composite coin',transform=ax.transAxes,ha='right',fontsize=6.5)\n    ia=ax.inset_axes([.83,.08,.14,.72]); ia.axis('off')\n    yy=np.linspace(.08,.92,9); cc=plt.get_cmap('Spectral')(np.linspace(0,1,9))\n    ia.scatter(np.full_like(yy,.48),yy,s=18,c=cc,edgecolor='.45',linewidth=.15)\n    ia.annotate('',(.48,.98),(.48,.02),arrowprops=dict(arrowstyle='<->',lw=.6,color='.35'))\n    # (d) coherent collapse to measured energy sidebands plus the synthetic 1D lattice.\n    gs=outer[3].subgridspec(2,1,height_ratios=[1,.28],hspace=.15)\n    ax=fig.add_subplot(gs[0]); ax.text(-.08,1.03,'(d)',transform=ax.transAxes,fontsize=8)\n    pp=collapsed_energy(b1,b2); N=np.array(sorted(pp)); yy=np.array([pp[n] for n in N]); m=yy>3e-4\n    cmap=plt.get_cmap('Spectral'); norm=plt.Normalize(N[m].min(),N[m].max())\n    for n,y in zip(N[m],yy[m]): ax.vlines(n,0,y,color=cmap(norm(n)),lw=.9)\n    ax.scatter(N[m],yy[m],c=N[m],cmap='Spectral',s=11,edgecolors='.3',linewidth=.2)\n    ax.set(xlim=(-15,15),ylim=(0,yy[m].max()*1.20),ylabel='Probability'); ax.tick_params(labelbottom=False,labelsize=6); clean(ax); ax.text(.5,.90,'Synthetic 1D quantum walk',transform=ax.transAxes,ha='center',fontsize=7)\n    ax2=fig.add_subplot(gs[1],sharex=ax); NN=np.arange(-14,15); ax2.plot(NN,np.zeros_like(NN),color='#C7C7C7',lw=1); ax2.scatter(NN,np.zeros_like(NN),c=NN,cmap='Spectral',s=18); ax2.set_ylim(-.4,.4); ax2.set_yticks([]); ax2.set_xlabel(r'$N=n_1+2n_2$',fontsize=7); ax2.tick_params(labelsize=6); clean(ax2)\n    save(fig,os.path.join(OUT,'source_reconstructions__li2026_fig01.pdf'))\n\ndef _rgba_from_values(vals,cmap_name='Spectral',alpha_floor=.10):\n    vals=np.asarray(vals,float); vmax=max(float(vals.max()),1e-15)\n    norm=plt.Normalize(vals.min(),vals.max() if vals.max()>vals.min() else vals.min()+1)\n    rgba=plt.get_cmap(cmap_name)(norm(vals))\n    rgba[:,3]=alpha_floor+(1-alpha_floor)*(vals/vmax)**0.55\n    return rgba\n\ndef fig2():\n    # Paper Fig. 2: (a) physical interaction + primitive hops; (b-d) fixed-size lattice\n    # sites, where opacity (not marker size) encodes the Bessel probability magnitude.\n    fig=plt.figure(figsize=(7.1,2.16)); gs=GridSpec(1,4,figure=fig,width_ratios=[.82,1,1,1],wspace=.20,\n                                                  left=.035,right=.995,bottom=.20,top=.93)\n    ax=fig.add_subplot(gs[0]); ax.text(-.08,1.04,'(a)',transform=ax.transAxes,fontsize=8,clip_on=False)\n    # compact schematic following the published panel grammar\n    ax.annotate('',(.88,.75),(.08,.75),arrowprops=dict(arrowstyle='->',lw=.9,color='k'))\n    ax.text(.06,.82,'Free electron',fontsize=6.5,ha='left')\n    ax.text(.06,.61,'Co-rotating',fontsize=6.2,ha='left',va='top')\n    ax.text(.06,.53,'vortex fields',fontsize=6.2,ha='left',va='top')\n    xw=np.linspace(.34,.58,140)\n    ax.plot(xw,.58+.055*np.sin(24*np.pi*(xw-.28)),color='#D62728',lw=.9)\n    ax.plot(xw,.46+.055*np.sin(34*np.pi*(xw-.28)),color='#168BD2',lw=.9)\n    ax.text(.54,.58,r'$\\omega,\\ell_1=-1$',fontsize=5.7,va='center')\n    ax.text(.54,.46,r'$2\\omega,\\ell_2=-1$',fontsize=5.7,va='center')\n    # primitive lattice hops at lower right\n    O=np.array([.38,.12]); v1=np.array([.16,.13]); v2=np.array([.30,.13])\n    for i in range(4):\n        for j in range(4):\n            q=O+i*v1+j*v2\n            if q[0]>.94 or q[1]>.38: continue\n            ax.plot(q[0],q[1],'o',ms=2.1,color='.45')\n            if i<3: ax.plot([q[0],q[0]+v1[0]],[q[1],q[1]+v1[1]],lw=.45,color='#C7B28C')\n            if j<3 and q[0]+v2[0]<.96: ax.plot([q[0],q[0]+v2[0]],[q[1],q[1]+v2[1]],lw=.45,color='#B5C7B8')\n    ax.annotate('',O+v1,O,arrowprops=dict(arrowstyle='->',lw=1.0,color='#E67E22')); ax.text(*(O+v1+[-.02,.025]),r'$\\mathbf{v}_1$',fontsize=6.5)\n    ax.annotate('',O+v2,O,arrowprops=dict(arrowstyle='->',lw=1.0,color='#4C9F70')); ax.text(*(O+v2+[.00,-.045]),r'$\\mathbf{v}_2$',fontsize=6.5)\n    ax.text(.34,.02,'Single step',fontsize=6.2)\n    ax.set(xlim=(0,1),ylim=(0,1)); ax.axis('off')\n\n    for q,eta in enumerate([1/3,1,3],1):\n        ax=fig.add_subplot(gs[q]); ax.text(-.08,1.04,f'({chr(97+q)})',transform=ax.transAxes,fontsize=8,clip_on=False)\n        b1=2.4; b2=b1*eta; a=lattice_points(b1,b2,-1,-1,10)\n        # lattice mesh first\n        v1=np.array([1,-1]); v2=np.array([2,-1])\n        for n1 in range(-9,10):\n            P=np.array([n1*v1+n2*v2 for n2 in range(-9,10)]); ax.plot(P[:,0],P[:,1],color='#C9D2C9',lw=.35,zorder=0)\n        for n2 in range(-9,10):\n            P=np.array([n1*v1+n2*v2 for n1 in range(-9,10)]); ax.plot(P[:,0],P[:,1],color='#C9D2C9',lw=.35,zorder=0)\n        colors=_rgba_from_values(a[:,2],'Spectral',.08)\n        ax.scatter(a[:,0],a[:,1],c=colors,s=17,edgecolor='.45',linewidth=.18,zorder=2)\n        # inset coupling-direction spheres, as in the source figure\n        ia=ax.inset_axes([.58,.67,.34,.26]); ia.axis('off')\n        ia.add_patch(plt.Circle((.30,.52),.16,fc='#E7A36E',ec='none',alpha=.95))\n        ia.add_patch(plt.Circle((.70,.52),.16,fc='#9EC7CD',ec='none',alpha=.95))\n        ia.text(.30,.52,r'$\\omega$',ha='center',va='center',fontsize=5.5); ia.text(.70,.52,r'$2\\omega$',ha='center',va='center',fontsize=5.5)\n        if eta<1: ia.annotate('',(.43,.52),(.57,.52),arrowprops=dict(arrowstyle='<-',lw=1.0))\n        elif eta>1: ia.annotate('',(.57,.52),(.43,.52),arrowprops=dict(arrowstyle='<-',lw=1.0))\n        else: ia.annotate('',(.56,.52),(.44,.52),arrowprops=dict(arrowstyle='<->',lw=1.0))\n        ratio='1:3' if eta<1 else ('1:1' if eta==1 else '3:1')\n        ax.set_title(rf'$|\\beta_{{2\\omega}}|:|\\beta_\\omega|={ratio}$',fontsize=7,pad=2)\n        ax.set(xlabel=r'$N=n_1+2n_2$',xlim=(-18,18),ylim=(-13,13)); ax.set_xticks([-18,-12,-6,0,6,12,18]); ax.tick_params(labelsize=5.8,pad=1)\n        if q==1: ax.set_ylabel(r'OAM order $\\ell$',fontsize=7)\n        else: ax.tick_params(labelleft=False)\n        clean(ax)\n    save(fig,os.path.join(OUT,'source_reconstructions__li2026_fig02.pdf'))\n\ndef torus_xyz(KN,KL,R=2.0,r=.75):\n    return (R+r*np.cos(KL))*np.cos(KN),(R+r*np.cos(KL))*np.sin(KN),r*np.sin(KL)\n\ndef fig3():\n    # Paper Fig. 3 exactly: left planar BZ sign map + epsilon=0 contour; right the same\n    # contour on a periodically identified BZ torus. Coupling ratios are 1:3, 1:1, 3:1.\n    ratios=[1/3,1,3]\n    colors=['#0587D1','#18B8B5','#E31A1C']\n    titles=['Before transition','Critical point','After transition']\n    fig=plt.figure(figsize=(4.7,6.5)); gs=GridSpec(3,2,figure=fig,wspace=.04,hspace=.28,left=.08,right=.98,bottom=.055,top=.97)\n    k=np.linspace(-np.pi,np.pi,601); KN,KL=np.meshgrid(k,k,indexing='xy')\n    for row,(eta,col,title) in enumerate(zip(ratios,colors,titles)):\n        E=dispersion(KN,KL,1,eta,-1,-1)\n        ax=fig.add_subplot(gs[row,0])\n        ax.contourf(KN,KL,np.sign(E),levels=[-1.5,0,1.5],colors=['#8ED8F8','#F4B583'],alpha=.96)\n        ax.contour(KN,KL,E,levels=[0],colors='k',linewidths=1.05)\n        if row==1: ax.plot([-np.pi],[-np.pi],'o',ms=5,mfc='none',mec='#D62728',mew=1.0,clip_on=False); ax.text(-2.95,-2.65,r'$K_\\ast$',fontsize=7)\n        plabel='('+chr(97+2*row)+')'; ax.text(-.16,1.03,plabel,transform=ax.transAxes,fontsize=8,clip_on=False)\n        ax.text(.5,.90,title,transform=ax.transAxes,ha='center',fontsize=7.2)\n        ax.set(xlim=(-np.pi,np.pi),ylim=(-np.pi,np.pi),aspect='equal')\n        ax.set_xticks([-np.pi,-np.pi/2,0,np.pi/2,np.pi]); ax.set_xticklabels([r'$-\\pi$',r'$-\\pi/2$','0',r'$\\pi/2$',r'$\\pi$'],fontsize=6.2)\n        ax.set_yticks([-np.pi,-np.pi/2,0,np.pi/2,np.pi]); ax.set_yticklabels([r'$-\\pi$',r'$-\\pi/2$','0',r'$\\pi/2$',r'$\\pi$'],fontsize=6.2)\n        ax.set_xlabel(r'$K_N$',fontsize=7); ax.set_ylabel(r'$K_\\ell$',fontsize=7)\n        ax.set_title(rf'$\\eta=|\\beta_{{2\\omega}}|:|\\beta_\\omega|={eta:g}:1$' if eta>=1 else r'$\\eta=|\\beta_{2\\omega}|:|\\beta_\\omega|=1:3$',fontsize=6.8,pad=2)\n        if eta==1: ax.set_title(r'$\\eta=|\\beta_{2\\omega}|:|\\beta_\\omega|=1:1$',fontsize=6.8,pad=2)\n        # torus\n        ax3=fig.add_subplot(gs[row,1],projection='3d'); ax3.text2D(-.03,1.02,'('+chr(98+2*row)+')',transform=ax3.transAxes,fontsize=8)\n        uu=np.linspace(-np.pi,np.pi,72); vv=np.linspace(-np.pi,np.pi,42); U,V=np.meshgrid(uu,vv); X,Y,Z=torus_xyz(U,V)\n        ax3.plot_surface(X,Y,Z,color='#B5B5B5',edgecolor='none',alpha=.55,shade=True,rstride=2,cstride=2)\n        tmp=plt.figure(); aa=tmp.add_subplot(); CS=aa.contour(KN,KL,E,levels=[0]); segs=CS.allsegs[0]; plt.close(tmp)\n        # draw periodic copies so the stitched contour visibly closes on the torus\n        for seg in segs:\n            x,y,z=torus_xyz(seg[:,0],seg[:,1]); ax3.plot(x,y,z,color=col,lw=2.0)\n        ax3.view_init(elev=28,azim=-52); ax3.set_axis_off(); ax3.set_box_aspect((1,1,.62))\n    save(fig,os.path.join(OUT,'source_reconstructions__li2026_fig03.pdf'))\n\ndef _lattice_panel(ax,l1,l2,b=2,nmax=6):\n    # Draw the geometric lattice first, then overlay exact Bessel probabilities.\n    v1=np.array([1,l1]); v2=np.array([2,l2])\n    for n1 in range(-nmax,nmax+1):\n        P=[]\n        for n2 in range(-nmax,nmax+1): P.append(n1*v1+n2*v2)\n        P=np.asarray(P); ax.plot(P[:,0],P[:,1],color='#C9D2C9',lw=.45,zorder=0)\n    for n2 in range(-nmax,nmax+1):\n        P=[]\n        for n1 in range(-nmax,nmax+1): P.append(n1*v1+n2*v2)\n        P=np.asarray(P); ax.plot(P[:,0],P[:,1],color='#C9D2C9',lw=.45,zorder=0)\n    a=lattice_points(b,b,l1,l2,nmax)\n    colors=_rgba_from_values(a[:,2],'Spectral',.09); sc=ax.scatter(a[:,0],a[:,1],c=colors,s=15,edgecolor='0.45',linewidth=.15,zorder=2)\n    ax.arrow(0,0,v1[0],v1[1],width=.025,head_width=.25,length_includes_head=True,color='#E67E22',zorder=4)\n    ax.arrow(0,0,v2[0],v2[1],width=.025,head_width=.25,length_includes_head=True,color='#4C9F70',zorder=4)\n    ax.set_xlim(-18,18); ax.set_xlabel(r'$N=n_1+2n_2$',fontsize=7); ax.set_ylabel(r'OAM order $\\ell$',fontsize=7); ax.tick_params(labelsize=6)\n    clean(ax)\n\ndef fig4():\n    cfg=[(0,1),(1,0),(-1,1)]\n    fig=plt.figure(figsize=(5.0,6.4)); gs=GridSpec(3,3,figure=fig,width_ratios=[1.05,1,.055],wspace=.20,hspace=.22,left=.10,right=.92,bottom=.06,top=.97)\n    k=np.linspace(-np.pi,np.pi,260); KN,KL=np.meshgrid(k,k,indexing='xy')\n    last=None\n    for j,(l1,l2) in enumerate(cfg):\n        ax=fig.add_subplot(gs[j,0]); ax.text(-.17,1.03,f'({chr(97+2*j)})',transform=ax.transAxes,fontsize=8,clip_on=False)\n        _lattice_panel(ax,l1,l2,2,7); ax.set_title('Synthetic lattice' if j==0 else '',fontsize=7.5,pad=2)\n        # Match row ranges used in the paper.\n        if (l1,l2)==(0,1): ax.set_ylim(-6.5,6.5)\n        elif (l1,l2)==(1,0): ax.set_ylim(-6.5,6.5)\n        else: ax.set_ylim(-12.5,12.5)\n        ax=fig.add_subplot(gs[j,1]); ax.text(-.16,1.03,f'({chr(98+2*j)})',transform=ax.transAxes,fontsize=8,clip_on=False)\n        E=dispersion(KN,KL,2,2,l1,l2)\n        last=ax.imshow(E,origin='lower',extent=[-np.pi,np.pi,-np.pi,np.pi],aspect='auto',cmap='RdBu_r',vmin=-8,vmax=8,interpolation='bilinear')\n        ax.set_xticks([-np.pi,0,np.pi]); ax.set_xticklabels([r'$-\\pi$','0',r'$\\pi$'],fontsize=6.2); ax.set_yticks([-np.pi,0,np.pi]); ax.set_yticklabels([r'$-\\pi$','0',r'$\\pi$'],fontsize=6.2)\n        ax.set_xlabel(r'$K_N$',fontsize=7); ax.set_ylabel(r'$K_\\ell$',fontsize=7); ax.set_title('Synthetic band dispersion' if j==0 else '',fontsize=7.5,pad=2)\n    cax=fig.add_subplot(gs[:,2]); cb=fig.colorbar(last,cax=cax); cb.set_ticks([-8,-4,0,4,8]); cb.ax.tick_params(labelsize=6); cb.set_label(r'$\\varepsilon$',fontsize=7)\n    save(fig,os.path.join(OUT,'source_reconstructions__li2026_fig04.pdf'))\n\nif __name__=='__main__':\n    fig1(); fig2(); fig3(); fig4()\n", Path(__file__).parent/'models'/'source_builders'/'li2026.py')
