_mod=_install_module('models.source_builders.wu2026', "import os,sys\nROOT=os.path.dirname(os.path.dirname(os.path.dirname(__file__)))\nsys.path.insert(0,ROOT)\nimport numpy as np\nimport matplotlib.pyplot as plt\nfrom matplotlib.gridspec import GridSpec\nfrom models.wu2026 import *\nfrom preamble import clean,save\nOUT=ROOT\n\n# Paper-specific visual grammar.  These figures intentionally do not use the generic\n# multi-panel styling: panel labels, aspect ratios and color scales follow the PRL figures.\ndef plabel(ax,s):\n    ax.text(-.12,1.065,s,transform=ax.transAxes,ha='left',va='bottom',fontsize=8.2,clip_on=False)\n\ndef fig1():\n    fig=plt.figure(figsize=(6.25,4.0)); G=GridSpec(2,2,figure=fig,height_ratios=[.9,1],hspace=.25,wspace=.32)\n    ax=fig.add_subplot(G[0,:]); plabel(ax,'(a)')\n    # Free-electron pulse train, PINEM stage and resonant interaction (paper Fig. 1a geometry).\n    z=np.linspace(0,1,1600); y=np.zeros_like(z)\n    centers=[.05,.25,.45,.69,.86]\n    for j,c0 in enumerate(centers):\n        amp=1 if j<3 else .72\n        y += amp*np.exp(-((z-c0)/(0.018 if j<3 else .010))**2)\n    ax.plot(z,y,lw=1.0)\n    for c0 in centers: ax.scatter([c0],[0],s=18,zorder=4)\n    ax.annotate('',(.48,.88),(.48,.05),arrowprops=dict(arrowstyle='->',lw=.9))\n    ax.text(.48,.94,r'$g_m$',ha='center')\n    ax.text(.31,-.18,r'$L_s$',ha='center'); ax.text(.67,-.18,r'$L_p$',ha='center')\n    ax.annotate('',(.44,-.11),(.08,-.11),arrowprops=dict(arrowstyle='<->',lw=.8))\n    ax.annotate('',(.84,-.11),(.51,-.11),arrowprops=dict(arrowstyle='<->',lw=.8))\n    ax.text(.92,.03,'Bound\\nelectron',ha='center',va='bottom',fontsize=7)\n    ax.set(xlim=(0,1),ylim=(-.28,1.18)); ax.axis('off')\n\n    for j,cfg in enumerate([1,2]):\n        ax=fig.add_subplot(G[1,j]); plabel(ax,f'({chr(98+j)})')\n        w31,w32=config(cfg); delta=(w31-w32)/1e15\n        ys=[0,delta,max(w31,w32)/1e15]\n        levels=[]\n        for yv in ys:\n            if not any(abs(yv-q)<1e-6 for q in levels):\n                ax.hlines(yv,.18,.84,color='k',lw=1.0); levels.append(yv)\n        if abs(ys[1]-ys[0])<0.15:\n            ax.text(.055,ys[0],r'$|1\\rangle,|2\\rangle$',va='center',fontsize=7)\n        else:\n            ax.text(.08,ys[0],r'$|1\\rangle$',va='center'); ax.text(.08,ys[1],r'$|2\\rangle$',va='center')\n        ax.text(.08,ys[2],r'$|3\\rangle$',va='center')\n        ax.annotate('',(.38,ys[2]-.05),(.38,ys[0]+.05),arrowprops=dict(arrowstyle='->',lw=.9))\n        ax.annotate('',(.64,ys[2]-.05),(.64,ys[1]+.05),arrowprops=dict(arrowstyle='->',lw=.9))\n        ax.text(.31,(ys[0]+ys[2])/2,r'$\\omega_{31}$',fontsize=7,rotation=90,va='center')\n        ax.text(.68,(ys[1]+ys[2])/2,r'$\\omega_{32}$',fontsize=7,rotation=90,va='center')\n        ax.set_title(f'Configuration {cfg}',fontsize=8,pad=3); ax.set_axis_off()\n    save(fig,os.path.join(OUT,'source_reconstructions__wu2026_fig01.pdf'))\n\ndef maps(cfg,ng=41,nL=81):\n    gs=np.linspace(0,12,ng); Ls=np.linspace(0,0.25,nL)\n    p1,p2,mu=scan_steady_state(gs,Ls,cfg)\n    return gs,Ls,p1,p2,mu\n\ndef fig2_3():\n    cache={cfg:maps(cfg) for cfg in [1,2]}\n    # Fig. 2: four square-ish panels + one shared vertical population bar, matching paper order.\n    fig=plt.figure(figsize=(4.65,4.45)); G=GridSpec(2,3,figure=fig,width_ratios=[1,1,.065],wspace=.11,hspace=.14)\n    ims=[]\n    for row,cfg in enumerate([1,2]):\n        g,L,p1,p2,mu=cache[cfg]\n        for col,data in enumerate([p1,p2]):\n            ax=fig.add_subplot(G[row,col]); im=ax.imshow(data,origin='lower',aspect='auto',extent=[0,12,0,250],vmin=0,vmax=1,cmap='RdYlBu',interpolation='bilinear')\n            ims.append(im); plabel(ax,f'({chr(97+2*row+col)})')\n            ax.set_title((r'$\\rho_{11}$' if col==0 else r'$\\rho_{22}$')+f' (Configuration {cfg})',fontsize=7.4,pad=3)\n            ax.set_xticks([0,3,6,9,12]); ax.set_yticks([0,50,100,150,200,250]); ax.tick_params(labelsize=6.4,pad=1.5)\n            if col==0: ax.set_ylabel(r'Drift length $L_p$ (mm)',fontsize=7)\n            else: ax.tick_params(labelleft=False)\n            if row==1: ax.set_xlabel(r'Coupling strength $|g_m|$',fontsize=7)\n            else: ax.tick_params(labelbottom=False)\n    cax=fig.add_subplot(G[:,2]); cb=fig.colorbar(ims[-1],cax=cax); cb.set_ticks(np.linspace(0,1,6)); cb.ax.tick_params(labelsize=6.3,pad=1)\n    cax.set_title('Population',fontsize=7,pad=4)\n    save(fig,os.path.join(OUT,'source_reconstructions__wu2026_fig02.pdf'))\n\n    # Fig. 3: two coherence panels, same color language and aspect as the paper.\n    fig=plt.figure(figsize=(4.65,2.35)); G=GridSpec(1,3,figure=fig,width_ratios=[1,1,.065],wspace=.11)\n    for j,cfg in enumerate([1,2]):\n        g,L,p1,p2,mu=cache[cfg]; ax=fig.add_subplot(G[0,j])\n        im=ax.imshow(mu,origin='lower',aspect='auto',extent=[0,12,0,250],vmin=0,vmax=1,cmap='RdYlBu',interpolation='bilinear')\n        plabel(ax,f'({chr(97+j)})'); ax.set_title(r'$\\mu_{12}$'+f' (Configuration {cfg})',fontsize=7.4,pad=3)\n        ax.set_xlabel(r'Coupling strength $|g_m|$',fontsize=7); ax.set_xticks([0,3,6,9,12]); ax.set_yticks([0,50,100,150,200,250]); ax.tick_params(labelsize=6.4,pad=1.5)\n        if j==0: ax.set_ylabel(r'Drift length $L_p$ (mm)',fontsize=7)\n        else: ax.tick_params(labelleft=False)\n    cax=fig.add_subplot(G[0,2]); cb=fig.colorbar(im,cax=cax); cb.set_ticks(np.linspace(0,1,6)); cb.ax.tick_params(labelsize=6.3,pad=1); cax.set_title('Degree of\\nCoherence',fontsize=7,pad=4)\n    save(fig,os.path.join(OUT,'source_reconstructions__wu2026_fig03.pdf'))\n\ndef fig4():\n    targets=[(1,.01110,2.00,80),(1,.05960,5.24,80),(2,.03260,1.00,80),(2,.04682,1.05,200)]\n    colors=['#4C8DCB','#F28E2B','#C9413A','#36B7B4','#C49A8B','#8CB3DE']\n    labels=[r'$\\rho_{11}$',r'$\\rho_{22}$',r'$\\rho_{33}$',r'$\\mu_{12}$',r'$\\mu_{13}$',r'$\\mu_{23}$']\n    fig,axs=plt.subplots(2,2,figsize=(5.1,4.15),gridspec_kw={'wspace':.13,'hspace':.38,'left':.10,'right':.80,'bottom':.10,'top':.90})\n    for idx,(cfg,L,g,tmax_us) in enumerate(targets):\n        ax=axs.flat[idx]; t=np.linspace(0,tmax_us,501); arr=iterate_at(g,L,t*1e-6,cfg)\n        series=[arr[:,0,0].real,arr[:,1,1].real,arr[:,2,2].real]\n        series += [np.array([coherence(r,0,1) for r in arr]),np.array([coherence(r,0,2) for r in arr]),np.array([coherence(r,1,2) for r in arr])]\n        for j,y in enumerate(series): ax.plot(t,y,color=colors[j],lw=1.0,ls='-' if j<3 else '--',label=labels[j])\n        plabel(ax,f'({chr(97+idx)})')\n        ax.set(xlim=(0,tmax_us),ylim=(-.02,1.03)); ax.set_xlabel(r'$t$ ($\\mu$s)',fontsize=7)\n        if idx%2==0: ax.set_ylabel('',fontsize=7)\n        ax.set_title(rf'$L_p$={L*1e3:.2f} mm, $|g_m|$={g:.2f}',fontsize=7.2,pad=3)\n        ax.grid(True,lw=.35,alpha=.35); ax.tick_params(labelsize=6.4,pad=1.5); clean(ax)\n    fig.text(.45,.955,'Configuration 1',ha='center',fontsize=8)\n    axs[0,1].legend(frameon=False,fontsize=6.1,ncol=1,loc='center left',bbox_to_anchor=(1.02,.5),handlelength=2.2)\n    save(fig,os.path.join(OUT,'source_reconstructions__wu2026_fig04.pdf'))\n\nif __name__=='__main__':\n    fig1(); fig2_3(); fig4()\n", Path(__file__).parent/'models'/'source_builders'/'wu2026.py')
setattr(sys.modules['models.source_builders'], 'wu2026', _mod)

# --- Unified atlas visual language (dimensionless comparison figures) ---
ATLAS_COLORS = ['#24566f','#c56a3d','#5b7f62','#8a6f9e','#9b873c','#60717b']
ATLAS_CMAP = 'viridis'
ATLAS_DIVERGING = 'RdBu_r'

def atlas_cycle():
    from cycler import cycler
    return cycler(color=ATLAS_COLORS)

