def atlas_figure(rows=2, cols=3, width=8.0, panel_h=None):
    fig, axs = plt.subplots(rows, cols, figsize=STANDARD_FIGSIZE, constrained_layout=True)
    return fig, np.atleast_1d(axs).ravel()

def atlas_panel(ax, label, title=None):
    ax.text(-0.13, 1.04, label, transform=ax.transAxes, ha='left', va='bottom',
            fontsize=12.0, fontweight='bold', color='0.12', clip_on=False)
    if title:
        ax.set_title(title, loc='left', pad=8, fontweight='semibold')
    ax.tick_params(direction='out', length=3.5, width=.8, pad=3)
    ax.spines['left'].set_linewidth(.7); ax.spines['bottom'].set_linewidth(.7)
    return ax

def atlas_heatmap(fig, ax, z, extent, xlabel, ylabel, cbar='', cmap=None, vmin=None, vmax=None):
    im=ax.imshow(z, origin='lower', aspect='auto', extent=extent, cmap=cmap or ATLAS_CMAP,
                 vmin=vmin, vmax=vmax, interpolation='bilinear')
    ax.set_xlabel(xlabel); ax.set_ylabel(ylabel)
    cb=fig.colorbar(im, ax=ax, fraction=.046, pad=.025)
    if cbar: cb.set_label(cbar, labelpad=2)
    cb.ax.tick_params(labelsize=9.0, length=3, pad=2)
    return im

def atlas_save(fig, path):
    save(fig, path)
